insert into public.theory_questions
  (external_ref, section_id, sort_order, prompt, prompt_ckb, answer, answer_ckb, status, source)
values
  ('theory:alertness:1',(select id from public.theory_sections where slug = 'alertness'),1,'You''re following a large vehicle. Why should you stay a safe distance behind it?','لە دواى ئۆتۆمبێلێکـى گەورەوە شۆفیری دەکەیت. بۆچـی دەبێت بۆشایـی سەلامەتـى لە دواوەى ئۆتۆمبێلەکەوە بهێڵیتەوە ؟','You''ll give the driver a chance to see you in their Mirrors','یارمەتـی شۆفێرەکە دەدەیت لە ئاوێنەکانـى خۆیەوە بتبینێت.','draft','content:uk-theory-questions'),
  ('theory:alertness:2',(select id from public.theory_sections where slug = 'alertness'),2,'You''re travelling along this road. How should you pass the cyclist?','بە درێژایـی ئەم ڕێگایە گەشت دەکەیت. چۆن بە لای پاسکیل سوارەکەدا تێپەڕدەبیت؟','Leave them plenty of room as you pass','کاتێـک بەلایدا تێپەڕ دەبیت مەوداى زۆرى بۆ بەجێـبهـێڵە.','draft','content:uk-theory-questions'),
  ('theory:alertness:3',(select id from public.theory_sections where slug = 'alertness'),3,'Why should you switch your headlights on when it first starts to get dark?','بۆچـی دەبێت لایتـى پێشەوە هەڵبکەیت کاتێک وردە وردە دونیا تاریک دەبێت؟','So others can see you more easily','بۆ ئەوەى ئەوانـى تر ئاسانتـر بتوانن بتبینن.','draft','content:uk-theory-questions'),
  ('theory:alertness:4',(select id from public.theory_sections where slug = 'alertness'),4,'There are objects hanging from your interior mirror. Why could this be a hazard?','هەندێک شت شۆڕ بوونەتەوە لە ئاوێنەى ناوەڕاستـی ئۆتۆمبێلەکەتەوە. بۆچـی دەکرێـت ئەمە مەترسـی بێـت؟','Your view could be obstructed','دەکرێـت ببێتە ڕێگر لەبەردەم ئاسۆی بینینت.','draft','content:uk-theory-questions'),
  ('theory:alertness:5',(select id from public.theory_sections where slug = 'alertness'),5,'How can you make sure that a satellite navigation (satnav) system doesn''t distract you when you''re driving?','چۆن دڵنیا دەبیت لە ئەوەى کە ئامێـرى سیستەمـى ڕێنیشاندەری سەتەلایتـى (ساتناڤ) مەشغوڵت ناکـات کـاتێک شۆفێـرى دەکەیت؟','Set it before starting your journey','پێش دەستپێکردنـی گەشتەکەت بەکاری بهێنە.','draft','content:uk-theory-questions'),
  ('theory:alertness:6',(select id from public.theory_sections where slug = 'alertness'),6,'Why are these yellow lines painted across the road?','بۆچى ئەم هێڵە زەردانە بە درێژایـی ڕێگـاکە کێشراون ؟','To make you aware of your speed','بۆ ئەوەى ئاگـادارى خێراییەکەت بیت.','draft','content:uk-theory-questions'),
  ('theory:alertness:7',(select id from public.theory_sections where slug = 'alertness'),7,'When do windscreen pillars cause a serious obstruction to your view?','کەى شانـی جامـى پێشەوە دەبێتە هۆى ڕێگریـى لە مەدوای بینینت ؟','When you''re approaching bends and junctions','کاتێک نزیک دەبیتەوە لە ڕێگـای چەماوە و یەکتربڕ.','draft','content:uk-theory-questions'),
  ('theory:alertness:8',(select id from public.theory_sections where slug = 'alertness'),8,'What should you do when you''re approaching traffic lights that have been green for some time?','دەبێـت چـی بکەیت کاتێک نزیک دەبیتەوە لە ترافیک لایتێک بۆ ماوەیەک سەوزە؟','Be ready to stop','ئامادە بە بۆ وەستان.','draft','content:uk-theory-questions'),
  ('theory:alertness:9',(select id from public.theory_sections where slug = 'alertness'),9,'You''re waiting to turn right at the end of a road. What should you do if your view is obstructed by parked vehicles?','لە کۆتایـی ڕێگەیەکدا چاوەڕێیت بە دەستە ڕاستدا پێچ بکەیتەوە. دەبێـت چـی بکەیت ئەگەر مەودای بینینت بەهۆی ئۆتۆمبێلێکـى پارکراوە گیرا ؟','Stop and then move forward slowly and carefully for a clear view','بوەستە و پاشان بەهێواشـی و بە وریاییەوە بەرەو پێشەوە بڕۆ بۆ مەودایەکـی بینىنی باشتر.','draft','content:uk-theory-questions'),
  ('theory:alertness:10',(select id from public.theory_sections where slug = 'alertness'),10,'What should you do before making a U-turn?','دەبێـت چـی بکەیت پێش ئەوەى یوتێرن بکەیت؟','Look over your shoulder for a final check','سەیری ئەملاو لا بەباشـی بکە بۆ ئەنجام دانـى دواین پشکنین.','draft','content:uk-theory-questions'),
  ('theory:alertness:11',(select id from public.theory_sections where slug = 'alertness'),11,'Why should you use your mirrors when you see a hazard ahead?','بۆچـی دەبێـت سەیری ئاوێنەکـانت بکەیت کاتێک لە پێشەوە مەترسییەک دەبینیت؟','To assess how your actions will affect the traffic behind','بۆ هەڵسەنگـاندنـى ئەوەى چۆن کـاردانەوەت کـاریگەری لەسەر هاتووچۆى دواوەت دەبێت.','draft','content:uk-theory-questions'),
  ('theory:alertness:12',(select id from public.theory_sections where slug = 'alertness'),12,'Where should you avoid overtaking?','لە کوێ نابێت تێپەڕاندن ئەنجام بدەیت؟','Approaching a dip in the road','لەکاتـی نزیک بوونەوە لە ڕێگـایەکـی بەرز و نزمـی تێدا بێت.','draft','content:uk-theory-questions'),
  ('theory:alertness:13',(select id from public.theory_sections where slug = 'alertness'),13,'What does the term ''blind spot'' mean?','دەستەواژەى ناوچەى کوێر مانای چیە؟','An area not visible to the driver','ناوچەیەکە شۆفێر ناتوانێت بیبینێت.','draft','content:uk-theory-questions'),
  ('theory:alertness:14',(select id from public.theory_sections where slug = 'alertness'),14,'What should you do if your mobile phone rings while you''re driving or riding?','دەبێـت چـی بکەیت ئەگەر مۆبایلەکەت زەنگ لێبدات لە کاتێـکدا شۆفێری دەکەیت یان ماتۆڕسکیل لێدەخوڕیت؟','Leave it until you have stopped in a safe place','وەڵامـى مەدەرەوە تاوەکو لە شوێنێکـى سەلامەت دەوەستیت.','draft','content:uk-theory-questions'),
  ('theory:alertness:15',(select id from public.theory_sections where slug = 'alertness'),15,'You''re turning right onto a dual carriageway. What should you do before emerging?','پێچ دەکەیتەوە بە دەستەڕاستدا بۆ سەر ڕێگـاى کاریجوەی. دەبێـت چـی بکەیت پێش ئەوەى دەربچیت؟','Check that the central reservation is wide enough for your vehicle','چێکـی ناوچەی جەزرە وەسەتـی بکە بزانە تەواو فراوانە بۆ ئۆتۆمبێلەکەت.','draft','content:uk-theory-questions'),
  ('theory:alertness:16',(select id from public.theory_sections where slug = 'alertness'),16,'You''re waiting to emerge from a junction. The windscreen pillar is restricting your view. What should you be particularly aware of?','لە چاوەڕوانیدایت بۆ ئەوەى دەربچیت لە یەکتربڕێکدا. شانـی ڕاگرى جامـى پێشەوە ڕێگرى دەکات لە مەودای بینینت. دەبێـت بە تایبەت وریاى چی بیت؟','Motorcyclists','شۆفێرانـى ماتۆڕسکیل','draft','content:uk-theory-questions'),
  ('theory:alertness:17',(select id from public.theory_sections where slug = 'alertness'),17,'What''s likely to happen if you use a hands-free phone while you''re driving?','ئەگەری چـی زۆرە ڕووبدات کاتێک ئامێری بیستۆکـی(سەماعە) بەکاربهێنیت لە کاتێکدا شۆفێری دەکەیت؟','It will divert your attention','بیروهۆشت دەبات.','draft','content:uk-theory-questions'),
  ('theory:alertness:18',(select id from public.theory_sections where slug = 'alertness'),18,'You''re driving on a wet road. What should you do if you have to stop your vehicle in an emergency?','لەسەر ڕێگایەکـى تەڕ شۆفێری دەکەیت. دەبێـت چـی بکەیت ئەگەر پێویستـى کرد ئۆتۆمبێلەکەت لە ئێمرجنسیدا بوەستێنیت ؟','Keep both hands on the steering wheel','هەردوو دەستت بهێڵەرەوە لەسەر سوکـانەکە.','draft','content:uk-theory-questions'),
  ('theory:alertness:19',(select id from public.theory_sections where slug = 'alertness'),19,'You''re on a long motorway journey. What should you do if you start to feel sleepy?','لە گەشتێکدا لەسەر مۆتۆروەیەکـی درێژ شۆفێری دەکەیت. دەبێـت چـی بکەیت ئەگەر بەهەستکردن بە خەواڵووى؟','Leave the motorway and stop in a safe place','مۆتۆروەیەکە بەجێبهێڵەو لە شوێنێکـى سەلامەتدا بوەستە.','draft','content:uk-theory-questions'),
  ('theory:alertness:20',(select id from public.theory_sections where slug = 'alertness'),20,'What should you do if you can''t see clearly behind when you''re reversing?','دەبێـت چـی بکەیت ئەگەر نەتوانیت بە ڕوونـى دواوە ببینیت کاتێـک بەگ دادەنێت؟','Ask someone to guide you','داوا لە یەکێک بکە ڕێنموونیت بکـات.','draft','content:uk-theory-questions'),
  ('theory:alertness:21',(select id from public.theory_sections where slug = 'alertness'),21,'What should you do when you move off from behind a parked car?','دەبێـت چـی بکەیت کاتێک دەتەوێت لە پشتـی ئۆتۆمبێلێکـی وەستاوە دەربچیت؟','Look around before moving off','سەیرى دەوروبەرى خۆت بکە پێش ئەوەى دەربچیت.','draft','content:uk-theory-questions'),
  ('theory:alertness:22',(select id from public.theory_sections where slug = 'alertness'),22,'You''re driving your car. When may you use a hand-held mobile phone?','ئۆتۆمبێلەکەت لێدەخوڕیت. کەى دەکرێـت مۆبایلەکەت بەکـاربهێنیت؟','When you''ve parked safely','کاتێک بەشێوەیەکـى سەلامەت ئۆتۆمبێلەکەت پارک کردووە.','draft','content:uk-theory-questions'),
  ('theory:alertness:23',(select id from public.theory_sections where slug = 'alertness'),23,'What should you do before slowing down or stopping your vehicle?','دەبێـت چـی بکەیت پێش هێواش کردنەوە یان وەستاندنـى ئۆتۆمبێلەکەت؟','Use the mirrors','سەیری ئاوێنەکـان بکە.','draft','content:uk-theory-questions'),
  ('theory:alertness:24',(select id from public.theory_sections where slug = 'alertness'),24,'What should you do as you approach this bridge?','دەبێـت چـی بکەیت کاتێک نزیک دەبیتەوە لەم پردە؟','Slow down','ئۆتۆمبێلەکەت هێواش بکەرەوە.','draft','content:uk-theory-questions'),
  ('theory:alertness:25',(select id from public.theory_sections where slug = 'alertness'),25,'What''s most likely to distract you while you''re driving?','دەکرێـت چـی زیاتر سەرت لـێ تێکبدات لە کاتێکدا شۆفێـری دەکەیت؟','Using a mobile phone','بەکـارهێنانـى مۆبایل.','draft','content:uk-theory-questions'),
  ('theory:alertness:26',(select id from public.theory_sections where slug = 'alertness'),26,'What does this curved arrow road marking mean?','ئەم تیرە چەماوەى سەر ڕێگـاکە بە ماناى چـی دێــــت؟','Overtaking traffic should move back to the left','ئەو ئۆتۆمبێلانەى تێپەڕاندن ئەنجام دەدەن دەبێـت بگەڕێنە دواوە بۆ دەستە چەپ','draft','content:uk-theory-questions'),
  ('theory:attitude:201',(select id from public.theory_sections where slug = 'attitude'),1,'What must you do when the amber light is flashing at a pelican crossing?','دەبێـــت چـی بکەیت کاتێـک لەناوچەی پیادەڕۆ گڵـۆپـی زەردباو فلاش دەکات؟','Give way to pedestrians already on the crossing','ڕێگە بدە بەو پیادەڕۆیـانەى کە لـەسەر هێڵـى پەڕینەوەکەن','draft','content:uk-theory-questions'),
  ('theory:attitude:202',(select id from public.theory_sections where slug = 'attitude'),2,'You''re approaching a zebra crossing. What should you do if pedestrians are waiting to cross?','تۆ نزیک دەبیتەوە لە شوێنێکى پەڕینەوەى سەر شەقام. تۆ دەبێـــت چی بکەیـت ئەگەر کەسانى پیادەڕۆ چاوەڕێی پەڕینەوە بکەن؟','Slow down and prepare to stop','ئۆتۆمبێلەکەت هێواش بکەرەوەو ئامادەبە بۆ وەستان','draft','content:uk-theory-questions'),
  ('theory:attitude:203',(select id from public.theory_sections where slug = 'attitude'),3,'What should you do if you''re driving a slow-moving vehicle on a narrow winding road?','دەبێـت چـی بکەیت ئەگەر شۆفێـرى ئۆتۆمبێلێـکـى هێـواش بکەیت لەسەر ڕێگایەکـى باریـک پێـچاوپێــچ؟','Pull in when you can, to let the vehicles behind overtake','هەرکاتێـک توانیت لابدە قەراغـی ڕیگـاکـە بۆ ئەوەی ئۆتۆمبێـلەکەى دواوەت تێپـەڕاندن ئەنـجام بـدات','draft','content:uk-theory-questions'),
  ('theory:attitude:204',(select id from public.theory_sections where slug = 'attitude'),4,'What should you do if a vehicle pulls out in front of you at a junction?','دەبێــت چـی بکەیت ئەگەر هاتوو ئۆتۆمبێلـێک لە بەردەمتــدا لەسەر ڕێگەکە لابچێــت لە یەکتربڕێـکدا؟','Slow down and be ready to stop','هێواشـی بکەرەوە ئامـادە بە بۆ وەسـتان','draft','content:uk-theory-questions'),
  ('theory:attitude:205',(select id from public.theory_sections where slug = 'attitude'),5,'You''re in a line of traffic. What action should you take if the driver behind is following very closely?','لە نێـو ئیزدیـحامـی ترافیکـدایت. دەبێـت چـی بکەیت ئەگەر ئوتومبیـلەکەی دواوەت زۆر نزیـک بۆیەوە ؟','Slow down, gradually increasing the gap between you and the vehicle in front','ئۆتۆمبێـلەکەت هێواش بکەرەوە و وردە وردە بۆشایــی نێوان خۆت و ئۆتۆمبێلـەکەى پێشـەوەت زیاتر بکە','draft','content:uk-theory-questions'),
  ('theory:attitude:206',(select id from public.theory_sections where slug = 'attitude'),6,'You''re driving on a clear night. Which lights should you use if the national speed limit applies and there''s a steady stream of oncoming traffic?','لە شەوێکــى ساماڵدا شۆفێـرى دەکەیــت. دەبێـت کـام لە لایــتەکان هەڵبکەیت ئەگەر ناشنــاڵ سپید لیمـتد بەکاربهێنترێـت وە بەردەوامـى ئۆتۆمبێـل بەرەو ڕووت بێـت؟','Dipped headlights','لایتــی نزمـی پێشەوە','draft','content:uk-theory-questions'),
  ('theory:attitude:207',(select id from public.theory_sections where slug = 'attitude'),7,'What should you do when a person herding sheep asks you to stop?','دەبێـت چـی بکەیت کاتێـک شوانێــک ڕانێک مەڕ لێــدەخوڕێت و داوات لێدەکــات بوەستیت؟','Stop and switch off your engine','بوەستە و بزوێنـەرەکەت بکوژێنەوە','draft','content:uk-theory-questions'),
  ('theory:attitude:208',(select id from public.theory_sections where slug = 'attitude'),8,'When should you flash your headlights at other road users?','چ کاتێک دەتوانـی لایەتەکانـى پێشـەوەت فلاش بۆ بەکارهێنەرانـى ترى ڕێگـاکـە لێبدەیت؟','When letting them know that you''re there','کاتێـک دەتەوێت بزانن تۆ لە ئەو شوێنـەدا هەیت','draft','content:uk-theory-questions'),
  ('theory:attitude:209',(select id from public.theory_sections where slug = 'attitude'),9,'The conditions are good and dry. When should you use the ''two-second rule''?','کەش و هەوا باش و وشکە. کەی دەبێـت یاسای دوو چـرکە بەکاربهێنیت؟','When checking your gap from the vehicle in front','کاتێـک چێـکــی بۆشای نێوان خۆت و ئۆتۆمبێلەکەى پێشــەوەت دەکەیت','draft','content:uk-theory-questions'),
  ('theory:attitude:210',(select id from public.theory_sections where slug = 'attitude'),10,'What type of emergency vehicle is fitted with a green flashing beacon?','چ جۆرە ئۆتۆمبێلیکــى حاڵەتـى ئیمرجنسـی گڵۆپـی ئاگادارکردنەوەى سەوزى لەسەرە ؟','Doctor''s car','ئۆتۆمبێلـى پزیــشک','draft','content:uk-theory-questions'),
  ('theory:attitude:211',(select id from public.theory_sections where slug = 'attitude'),11,'What should you do when you''re overtaking a horse and rider?','دەبێـت چـی بکەیت کاتێـــک سوارێــک و ئەســپەکەى تێدەپەڕێنیت؟','Go past slowly and carefully','بە هێواشـی و بە وریاییەوە تێیان پەڕێنـە','draft','content:uk-theory-questions'),
  ('theory:attitude:212',(select id from public.theory_sections where slug = 'attitude'),12,'You''re driving along this road. What should you do if the red car cuts in close in front of you?','بەدرێژایـی ئەم ڕێگەدا شۆفیـرى دەکەیت. دەبێـت چـی بکەیت ئەگەر ئۆتۆمبێـلە سوورەکە خۆی هەڵبـداتە بەردەمت؟','Drop back to leave the correct separation distance','ئۆتۆمبێـلـەکەت خاوبکەرەوە بۆئەوەی مەوداى دووری سەلامەت هەبێت','draft','content:uk-theory-questions'),
  ('theory:attitude:213',(select id from public.theory_sections where slug = 'attitude'),13,'You''re driving a car that has a diesel engine. What can a loose filler cap on your fuel tank cause?','شۆفیـرى ئۆتۆمبێلێـک دەکەیت کە بزوێنەرى دیزڵـى هەیە. ئەگەر سەرقەباغـی تانکـى سووتەمەنییەکە بە شلـى بەسترابێـت چـی ڕوودەدات؟','It can make the roads slippery for other road users','دەتوانێـت ڕێگـاکە خلیسک بکات بۆ بەکارهێنەرانـــى ترى ڕێگـاکە','draft','content:uk-theory-questions'),
  ('theory:attitude:214',(select id from public.theory_sections where slug = 'attitude'),14,'What style of driving causes increased risk to everyone?','چ شێوازیکـى شۆفیـریکردن دەبێتە هۆى زیادبوونـى مه ترسى بۆ هەمووان؟','Competitive','پێشبڕکێکـار بێـت','draft','content:uk-theory-questions'),
  ('theory:attitude:215',(select id from public.theory_sections where slug = 'attitude'),15,'What does it mean if the signs at a bus lane show no times of operation?','ئەگەر هێماکانـی سایدی پاس بە هیچ شێوەیەک کاتەکانــى کارکردن پیشان نەدەن واتای چییە؟','The lane is in operation 24 hours a day','سایدەکە ٢٤ کاتژمێر ئیشدەکـات','draft','content:uk-theory-questions'),
  ('theory:attitude:216',(select id from public.theory_sections where slug = 'attitude'),16,'You''re approaching a red light at a puffin crossing. Pedestrians are on the crossing. When will the red light change?','نزیک دەبیتەوە لە گڵـۆپــى سوورى شوێنێکــى پەڕینەوەى پیادەڕۆ. پیادەڕۆکان لەسەر هێلــى پەڕینەوەکەن. کەى گڵۆپە سوورەکە دەگۆڕێت؟','When the pedestrians have cleared the crossing','کاتێک پیادەڕۆکــان هێڵــى پەڕینەوەکەیان بەجێهێشت','draft','content:uk-theory-questions'),
  ('theory:attitude:217',(select id from public.theory_sections where slug = 'attitude'),17,'You''re driving in traffic at the speed limit for the road. What should you do if the driver behind is trying to overtake?','لەسەر ڕێگایەکــى هاتووچۆى ئۆتۆمبێـل بەهەمان خێرایـی ڕێگـاکە شۆفێـرى دەکەیت. دەبێـت چـی بکەیت ئەگەر شۆفێرەکەى دواوەت هەوڵ بدات تێپـەڕاندن ئەنجام بدات؟','Keep a steady course and allow the driver behind to overtake','لەسەر خێرای و ئاراستەیەکـى جێگیر بمێـنەرەوە ڕێگە بە شۆفێرەکەى دواوەت بدە کە تێپەڕانـدن ئەنجام بدات','draft','content:uk-theory-questions'),
  ('theory:attitude:218',(select id from public.theory_sections where slug = 'attitude'),18,'Which vehicle will use a blue flashing beacon?','کام ئۆتۆمبێل گڵۆپـی ئاگادارکردنەوەى شیـن بەکـاردەهێنێـت؟','Bomb disposal','ئۆتۆمبێلـى پوچەڵـکردنەوەى بۆمب','draft','content:uk-theory-questions'),
  ('theory:attitude:219',(select id from public.theory_sections where slug = 'attitude'),19,'What will happen if you follow this vehicle too closely?','چـی ڕوودەدات ئەگەر تـۆ زۆر بە نزیکـى بە دواى ئەم ئۆتـۆمبێلەوە بیت؟','Your view ahead will be reduced','ئاسۆى بینینـی پێشەوەت کەم دەبێتەوە','draft','content:uk-theory-questions'),
  ('theory:attitude:220',(select id from public.theory_sections where slug = 'attitude'),20,'When should you use your vehicle''s horn?','کەى دەبێــت هۆرنـەکەت بەکاربهێنیت؟','To alert others to your presence','بۆ ئاگادارکردنەوەى ئەوانـى تر لە بوونـى خۆت','draft','content:uk-theory-questions'),
  ('theory:attitude:221',(select id from public.theory_sections where slug = 'attitude'),21,'You''re driving at night on an unlit road. What should you do if you''re following another vehicle?','لە شەودا لەسەر ڕێگایەکـى ڕووناک نەکراوە شۆفیـرى دەکەیت. دەبێـت چـی بکەیت ئەگەر لە دواى ئۆتۆمبێلێـکـى ترەوە بوویت؟','Use dipped headlights','لایتـی نزمـی پێشەوەت بەکاربهێـنە','draft','content:uk-theory-questions'),
  ('theory:attitude:222',(select id from public.theory_sections where slug = 'attitude'),22,'You''re driving behind a large goods vehicle. What should you do if it signals left but steers to the right?','لە دوای ئۆتۆمبێلێکـى بارهەڵگرى گەورەوە شۆفیـرى دەکەیت. دەبێـت چـی بکەیت ئەگەر گڵـۆپــی ئیشارەتــی دەستە چەپــی داگیرساند بەڵام بە لای دەستە ڕاستـدا ڕۆیشت؟','Slow down and let the vehicle turn','ئۆتۆمبێـلەکەت هێواش بکەرەوەو ڕێگە بە ئۆتۆمبێلەکە بدە بە دەستە ڕاستـدا بڕوات','draft','content:uk-theory-questions'),
  ('theory:attitude:223',(select id from public.theory_sections where slug = 'attitude'),23,'Which type of crossing allows cyclists to ride across with pedestrians?','کام جۆرى هێڵى پەڕینەوە ڕێگە بە پاسکیـل سوارەکان دەدات کە پاسکـیلەکانیان لێبخوڕن لەگەڵ پیادەڕۆکاندا؟','Toucan','هێڵـى پەڕینـەوەى پاسکیل سوارو پیادەڕۆ','draft','content:uk-theory-questions'),
  ('theory:attitude:224',(select id from public.theory_sections where slug = 'attitude'),24,'Why should you never wave people across at pedestrian crossings?','بۆچـى هەرگیز نابێـت بەدەست ئامـاژە بۆ خەڵکـى بکەیت لە هێڵـى پەڕینەوەى پیادەڕۆ؟','Another vehicle may be coming','دەکرێـت ئۆتۆمبێلێکـى تر گوزەر بکـات','draft','content:uk-theory-questions'),
  ('theory:attitude:225',(select id from public.theory_sections where slug = 'attitude'),25,'Why is it dangerous to travel too close to the vehicle ahead?','بۆچى مەترسیدارە زۆر بە نزیکـى شۆفێری بکەیت لە ئۆتۆمبێلـی پێشەوەت؟','Your view of the road ahead will be restricted','ئاسۆى بینینت بۆ ڕێگـاکەى پێشەوە سنووردار دەبێـت','draft','content:uk-theory-questions'),
  ('theory:attitude:226',(select id from public.theory_sections where slug = 'attitude'),26,'Which instrument-panel warning light would show that headlights are on main beam?','کام لەو گڵـۆپە ئیشارەتە ئاگادارکەرەوانە ئەوە پیشان دەدات کە لایتەکانـى بەشـــی پێشەوەى ئۆتۆمبێلەکەت لەسەر فوولە؟','D','D','draft','content:uk-theory-questions'),
  ('theory:attitude:227',(select id from public.theory_sections where slug = 'attitude'),27,'You''re travelling at the legal speed limit. What should you do if the vehicle behind approaches quickly, flashing its headlights?','بە هەمان خێرایــی یاسایـی ڕێگەپێدراو گەشت دەکەیت. دەبێـت چــی بکەیت ئەگەر ئۆتۆمبێـلەکەى دواوە بە خێرایــی نزیک ببێتەوەو لایتەکانــى بەشــی پێشەوەت تــێ ئەگرێت وەکو ئاگادارکردنەوەیەک؟','Allow the vehicle to overtake','ڕێـگە بە ئۆتۆمبێلەکە بدە تێپەڕاندن ئەنجام بدات','draft','content:uk-theory-questions'),
  ('theory:attitude:228',(select id from public.theory_sections where slug = 'attitude'),28,'You''re approaching an unmarked crossroads. How should you deal with the junction?','نزیک دەبیتەوە لە چوارڕێیـانێک کە هیچ هێڵکـارییەکـى لە سەر نییە. چۆن مامەڵە لەگەڵ یەکتربڕەکەدا دەکەیت ؟','Slow down and look both ways','خێراییەکەت کەمبکەرەوە و سەیرى هەردوولا بکە','draft','content:uk-theory-questions'),
  ('theory:attitude:229',(select id from public.theory_sections where slug = 'attitude'),29,'On a road where trams operate, which vehicles will be most at risk from the tram rails?','لەسەر ڕێگـایەک کە شەمەندەفەرى کارەبایـی(ترام) لەسەرى ئیش دەکات کـام یەکێک لە هۆیەکانـى گواستنەوە زۆر لە ڕیـسکدا دەبێـت بەهۆى هێڵـى ئاسنــى شەمەندەفەرە کارەباییەکەوە؟','Cycles','پاسکیــل','draft','content:uk-theory-questions'),
  ('theory:attitude:230',(select id from public.theory_sections where slug = 'attitude'),30,'What''s the minimum time gap you should leave when following a vehicle on a wet road?','کەمترین ماوەى مەوداى بۆشایی چەندە کە تۆ دەبێـت بەجێی بهێڵیت کاتێک کە بە دواى ئۆتۆمبێلێکەوەیت لەسەر ڕێگایەکى تەڕ؟','Four seconds','چوار چرکە','draft','content:uk-theory-questions'),
  ('theory:attitude:231',(select id from public.theory_sections where slug = 'attitude'),31,'Which colour follows the green signal at a puffin crossing?','لە دواى گڵۆپــی ئاگادارکردنەوەى سەوز چ ڕەنگێکــى تر دێـت لە شوێنــى پەڕینەوەى کۆنترۆڵکراو بە ترافیک لایتــی زیرەک؟','Steady amber','زەربـــاوى جێگیر','draft','content:uk-theory-questions'),
  ('theory:attitude:232',(select id from public.theory_sections where slug = 'attitude'),32,'You wish to turn right ahead. Why should you take up the correct position in good time?','دەتەوێـت بە دەســتە ڕاستدا پێـــچ بکەیتەوە لە پێشەوە. بۆچــى دەبێـت لە کاتێــک و شوێنێکــى باشدا ئەنجامــی بدەیت؟','To help other road users know what you intend to do','بۆ یارمەتیدانــى بەکارهێنەرانــى ترى ڕێگـاکە لە ئەوەى بزانن کە تۆ نیازت چییە','draft','content:uk-theory-questions'),
  ('theory:attitude:233',(select id from public.theory_sections where slug = 'attitude'),33,'You''re in a one-way street and want to turn right. Where should you position your vehicle when there are two lanes?','لە شەقامێکــى یەک ئاراستەدایت وە دەتەوێـت بە دەسـتە ڕاستدا پێچ بکەیتەوە. دەبێـــــت ئۆتۆمبێلەکەت لە کوێدا دابێـــت لە کاتێکدا دوو ساید هەبێــــــــــــــــــــــت؟','In the right-hand lane','لە سایدى دەستە ڕاست','draft','content:uk-theory-questions'),
  ('theory:attitude:234',(select id from public.theory_sections where slug = 'attitude'),34,'You''re being overtaken by a long, heavily laden lorry. What should you do if it''s taking a long time for it to overtake?','لۆرییەکـى درێژ بە بارێکـى قورسەوە تێپەڕاندن بەلای تۆدا ئەنجام دەدات. دەبێـت چـی بکەیت ئەگەر کاتێکـى زیاتری ویسـت بۆ ئەوەى تێپەڕانـدن ئەنجام بدات؟','Slow down','ئۆتۆمبێلەکەت هێـواش بکەیتەوە','draft','content:uk-theory-questions'),
  ('theory:attitude:235',(select id from public.theory_sections where slug = 'attitude'),35,'What should you do to avoid fuel spillage?','دەبێـت چـی بکەیت بۆ دوورکەوتنەوە لە ڕژانــی سووتەمەنـى؟','Check that your filler cap is securely fastened','دڵـنیابەرەوە لەوەى سەرقەباغـی تانـکییەکەت بە تونـدی بەستووە','draft','content:uk-theory-questions'),
  ('theory:attitude:236',(select id from public.theory_sections where slug = 'attitude'),36,'Who should obey diamond-shaped traffic signs?','کـێ دەبێــــت گوێـڕایەڵـى هێماى هاتووچـۆى شێوە ئەڵمـاس بێت؟','Tram drivers','شۆفێرانـى شەمەندەفەرى کارەبایـی(ترام)','draft','content:uk-theory-questions'),
  ('theory:attitude:237',(select id from public.theory_sections where slug = 'attitude'),37,'You''re waiting in a traffic queue at night. How can you avoid dazzling drivers behind you?','لە چاوەڕوانیـدایت لە ڕیزێکـى ئۆتۆمبێلـى یەک لە دواى یەک لە شەودا. چۆن دەتوانـى دووربکەویتەوە لە سەرلێشێوانـدى شۆفێرەکانـى دواوەت؟','Use the parking brake and release the footbrake','برێکـى پارکیـن بەکاربهێنە و پـێ لە ئیستۆپ بەردە','draft','content:uk-theory-questions'),
  ('theory:attitude:238',(select id from public.theory_sections where slug = 'attitude'),38,'What should you do if you''re being followed by an ambulance showing flashing blue lights?','دەبێـت چـی بکەیت ئەگەر ئۆتۆمبێلێکـى ئامبوڵانس دوات کەوتبێـت و گڵۆپە شیـنە ئاگادارکردنەوەکەی داگیـرساندبێت ؟','Pull over as soon as it''s safe to do so','هەرچـی زووترەو سەلامەتترە لەبەردەمـى لابچیت','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:65',(select id from public.theory_sections where slug = 'safety-and-vehicle'),1,'What could you do to reduce the volume of traffic on the roads?','دەتوانى چـی بکەیــت بۆ کەمـکردنەوەى قەرەباڵـخی هاتووچۆى ئۆتۆمبێـل لەسەر ڕێگـاکـان؟','Walk or cycle on short journeys','بـەپــێ ڕۆشتـن یان پاسکیــل سوارى کردن بۆ ماوەیەکــی کـەم.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:66',(select id from public.theory_sections where slug = 'safety-and-vehicle'),2,'How can you reduce the environmental harm caused by your motor vehicle?','چۆن دەتوانـى زیانە ژینگەییەکانی ئۆتۆمبێــلەکەت کەم بکەیتەوە ؟','Keep engine revs low','گـێـچــی حەماوەی مەکینـەکە بە نزمـی بهێڵەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:67',(select id from public.theory_sections where slug = 'safety-and-vehicle'),3,'What''s most likely to increase fuel consumption?','بەزۆرى چـی دەبێتـە هۆکاری زیاد بەکارهێنـانـى سووتەمەنـى؟','Harsh braking and accelerating','لەپـڕ ئـیسـتۆپ کردن و خـێـراکــردن.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:68',(select id from public.theory_sections where slug = 'safety-and-vehicle'),4,'What may help to deter a thief from stealing your car?','دەبێت چـى بکەیت بۆ ڕێگـری کردن لە دز لە دزینـى ئۆتۆمبێلەکەت؟','Etching the registration number on the windows','ژمارەى ئوتومبیلەکە لەسەر پەنجەرەکـان بنووسە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:69',(select id from public.theory_sections where slug = 'safety-and-vehicle'),5,'What will help you to keep your car secure?','چـى یارمەتیت دەدات ئۆتۆمبێـلەکەت سەلامەت بێت؟','Registering with a Vehicle Watch scheme','تۆمارکردنــى ئۆتۆمبیلەکەت لە سیستمــی چاودێـری کردنــى ئۆتۆمبێـل. (وۆچ ڤیکـڵ)','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:70',(select id from public.theory_sections where slug = 'safety-and-vehicle'),6,'You''re leaving your vehicle parked on a road and unattended. When may you leave the engine running?','لەسەر ڕێگـایەک ئۆتۆمبێلەکەت پارک دەکەیت بەجێدەهێڵـی و کەسیشـی تێـدا نییە. کەی دەتوانـی بزوێنەرەکە(مەکینەکەت) بە ئیشپێـکراوى بەجێبهێڵـى؟','Never if you''re away from the vehicle','هـەرگــیز ئەو کـارە نەکـەیـت ئەگەر ئـۆتـۆمبـێـلـەکـەت بەجێهێشت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:71',(select id from public.theory_sections where slug = 'safety-and-vehicle'),7,'If you''re involved in a collision, what will reduce the risk of neck injury?','ئەگەر تووشی ڕووداوێکـى هاتووچۆ بووى, چى دەبێـــــتە هۆى کەمکردنەوەى مەترسی برینداربوونـى مل؟','A properly adjusted head restraint','بەشــی سەرەوەى کوشنەکە بە باشــی چاک بـکە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:72',(select id from public.theory_sections where slug = 'safety-and-vehicle'),8,'What''s most likely to waste fuel?','چـى زیاتر دەبێتە هۆى بەفیڕۆدانـى سووتەمەنـى؟','Under-inflated tyres','ئەگەر تایەکـان کەم هەوا بوو.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:73',(select id from public.theory_sections where slug = 'safety-and-vehicle'),9,'Why is it a good idea to plan your journey to avoid busy times?','بۆچـى بیرۆکەیەکـى باشە پلانـى گەشتەکەت دابنێیــــت بۆ خـۆلادان لە کاتە قەرەباڵغـەکـان؟','You''ll have an easier journey','گەشتێکـى ئاسانترت دەبێــــــت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:74',(select id from public.theory_sections where slug = 'safety-and-vehicle'),10,'What''s the legal minimum tread depth for tyres on your trailer or caravan?','کەمترین قوڵـى یاسایـی نەخشەی سەر تایەـی ئۆتۆمبێل دەبێـت چەنـد بێت لە تریلەر و کەرڤانەدا؟','1.6mm','١.٦ ملم','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:75',(select id from public.theory_sections where slug = 'safety-and-vehicle'),11,'What can you do to reduce environmental damage caused by your vehicle?','دەتوانیت چـی بکەیت بۆ کەمـکردنەوەى زیانەکانـی ئوتومبیلەکەت کە بە ژینگەی دەگەیەنێت ؟','Avoid making a lot of short journeys','دووربکەرەوە لە زۆر ئەنجامدانـى گەشتـی ماوەکورت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:76',(select id from public.theory_sections where slug = 'safety-and-vehicle'),12,'What can you expect if you drive using rapid acceleration and heavy braking?','چـی ڕوودەدات ئەگەر شۆفێرـى بکەیت و لە پڕا خێـرایــی زیاد بکەیت و ئیسـتۆپـى قورس بکەیت؟','Increased fuel consumption','بەکارهێنانــى سووتەمەنـى زیاد دەکات.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:77',(select id from public.theory_sections where slug = 'safety-and-vehicle'),13,'What should you do when leaving your vehicle parked and unattended?','دەبێـــت چـی بکەیت کاتێک کە ئۆتۆمبێـلەکەت پـارک کردووە و کەسـی تێدا نییە و بەجێیدەهێڵـیت','Lock it and remove the key','قفڵـى بـکەیت و سویـچەکەى لابەیت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:78',(select id from public.theory_sections where slug = 'safety-and-vehicle'),14,'What''s the most important reason for having a properly adjusted head restraint?','گرنگتـرین هۆکـارى بەباشـی جێگیرکردنـی بەشـی سەرەوەى کوشـن چییە؟','To help you avoid neck injury','یارمەتیـت دەدات لە برینـدارنەبوونـى مل.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:79',(select id from public.theory_sections where slug = 'safety-and-vehicle'),15,'What should you do if your anti-lock brakes (ABS) warning light stays on?','دەبێــت چـی بکەیت ئەگەر گـڵۆپـی ئاگـادارکردنەوەى برێـکەکەت (بە سیستەمــى ئەى بـی ئێس) بە هەڵـکراوى مایەوە؟','Have the brakes checked immediately','راستەوخۆ دەبێت چێکـی برێکەکـان بکرێت','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:80',(select id from public.theory_sections where slug = 'safety-and-vehicle'),16,'You need to top up your battery with distilled water. What level should you fill it to?','پێویســتە پاترى ئۆتۆمبێلەکەت پڕبکەیت لە ئاوى دڵۆپێنـراو. تا چ ئاستێک دەبێــت پـڕی بکەیت؟','Just above the cell plates','تۆزێک لەسەرەوەى خانە پلێتـییەکان.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:81',(select id from public.theory_sections where slug = 'safety-and-vehicle'),17,'On a vehicle, where would you find a catalytic converter?','لە ئۆتۆمبێـلدا, لە کوێ دەتوانیت ئامێـرى کەتەلایزەر کۆنڤێـرتەر بدۆزیتەوە؟','On the exhaust system','لەسـەر سیستەمـى ئەگزۆزەکە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:82',(select id from public.theory_sections where slug = 'safety-and-vehicle'),18,'When is fuel consumption at its highest?','کەى بەکارهێنانـى سووتەمەنـى لە بەرزترـین ئاسـتدایە؟','When you''re accelerating','کاتێـک بە خێرایـی دەڕۆیت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:83',(select id from public.theory_sections where slug = 'safety-and-vehicle'),19,'You''re parked on the road at night. When must you use parking lights?','ئۆتۆمبێلـەکەت لە سەر ڕێگـا و لە شەودا وەسـتاندووە. دەبێــت کەى گڵـۆپـى پارکین هەڵبکەیت؟','When the speed limit exceeds 30 mph','کاتێک خێرایـی دیاریکراو زیاتر بێـت لە ٣٠ میـل لە کاتژمێرێکدا.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:84',(select id from public.theory_sections where slug = 'safety-and-vehicle'),20,'What makes your tyres illegal?','چـى وا لە تایەکانـى ئۆتۆمبــێلەکەت دەکات نایاسایـی بن؟','If they have any large, deep cuts in the side wall','ئەگـەر دڕاوی گەورە و قـوڵ لەسەر ڕووى تایەکـان هەبن.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:85',(select id from public.theory_sections where slug = 'safety-and-vehicle'),21,'What can be damaged if you turn the steering wheel when the car isn''t moving?','چـى زیانـى پێدەگـات کاتێک ئۆتۆمبێـلەکە ناجـوڵێت و سوکـانەکەی دەسووڕێنیت؟','The tyres','تایەکـان','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:86',(select id from public.theory_sections where slug = 'safety-and-vehicle'),22,'You''re having difficulty finding a parking space in a busy town. Can you park on the zigzag lines of a zebra crossing?','کێشـەت هەیە لە دۆزینەوەى شوێنێک بۆ پارکینـی ئۆتۆمبـێلەکەت لە شارۆچکەیەکـى قەرەباڵـغدا. دەتوانـی ئۆتۆمبێلەکەت لەسەر هێڵە زیگـزاگەکانـى پێش شوێنـى پەڕینەوەى پیادەڕۆ پارکین بکەیت؟','No, not under any circumstances','نەخێر نابێــت ئەو کارە ئەنجام بدەیـــت لە هیـچ کاتێکدا.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:87',(select id from public.theory_sections where slug = 'safety-and-vehicle'),23,'How can drivers help the environment?','شۆفێـرەکـان چۆن دەتوانن یارمەتـى ژینگە بدەن؟','By accelerating gently','بە لێخوڕینـی نەرم و لەسەرخۆ.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:88',(select id from public.theory_sections where slug = 'safety-and-vehicle'),24,'You''re driving a friend''s children home from school. They''re both under 14 years old. Who''s responsible for making sure they wear a seat belt or approved child restraint where required?','منداڵانـى هاوڕێکەت لە قوتابخانەوە دەگەیەنیتە ماڵەوە بە ئۆتۆمبێلەکەت. ئەوان هەردووکیاـن لە خوار ١٤ ساڵەوەن. کـێ بەرپرسیارە بۆ دڵنیابوونەوە لە ئەوەى کە ئەوان قایشـی سەلامەتیان بەستووە یان کوشنى سەلامەتـى تایبەت بە منداڵیان بەکارهێناوە کە پێویسـتن؟','You, the driver','تۆى شۆفیر.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:89',(select id from public.theory_sections where slug = 'safety-and-vehicle'),25,'What part of the car does the law require you to keep in good condition?','یاسا داوات لێدەکات چ بەشێکـى ئۆتۆمبێلەکە لە بارودۆخێکـى باشدا بهێڵیتەوە؟','The seat belts','قایشـی کوشنەکـان.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:90',(select id from public.theory_sections where slug = 'safety-and-vehicle'),26,'What will reduce fuel consumption?','چـى دەبێتە هۆى کەمکردنەوەى بەکـارهێنانـى سووتەمەنـى؟','Driving more slowly','بە هێواشـی شۆفێری کردن.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:91',(select id from public.theory_sections where slug = 'safety-and-vehicle'),27,'When may a passenger travel in a car without wearing a seat belt?','کەى دەکرێــت سەرنشینێک گەشت بکات لە ئۆتۆمبێلێکدا بەبێ بەستنـى پشتێنـى سەلامەتـى؟','When they''re exempt for medical reasons','کاتێـک لەبەر هۆکـاری تەندروستـی قایشـی سەلامەتـى نابەستن.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:92',(select id from public.theory_sections where slug = 'safety-and-vehicle'),28,'What can people who live or work in towns and cities do to help reduce urban pollution levels?','دانیـشتوانـی شارۆچکە و شارەکان ئەوانەشـی لەوێ کـاردەکەن و دەتوانن چـی بکەن بۆ کەمـکردنەوەى پیس بوونـى ژینگەی ناوچە شارستانییەکـان؟','Walk or cycle','پیاسەکردن یان پاسـکیل لێخوڕین.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:93',(select id from public.theory_sections where slug = 'safety-and-vehicle'),29,'How should you drive when you''re driving along a road that has road humps?','چۆن شۆفێـرى دەکەیـت کاتێک بە درێژایـی ڕێگـایەک کە تاسـەى لەسەرە شۆفێـرى دەکەیت ؟','Maintain a reduced speed throughout','بە خێراییەکـى کەم بە درێژایـی ڕێگـاکە بەردەوام بە','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:94',(select id from public.theory_sections where slug = 'safety-and-vehicle'),30,'You want to put a rear-facing baby seat on the front passenger seat. What must you do if the passenger seat is protected by a frontal airbag?','دەتەوێــت کوشنێکـى تایبەت بە منداڵـى ساوا لەسەر کوشنـی پێشەوە جێگیربکەیت. دەبێــت چـی بکەیت ئەگەر کوشنـى پێشەوە ئێرباگـی هەبێت؟','Deactivate the airbag','ئێربـاگەکە لەکـاربخە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:95',(select id from public.theory_sections where slug = 'safety-and-vehicle'),31,'When will your vehicle use more fuel?','کەى ئۆتۆمبێلەکەت سووتەمەنـى زیاتر بەکاردەهێنـێ؟','When its tyres are under-inflated','کاتێک تایەکانى بەڕێژەى پێویست هەوای تێدا نییە(کەم هەوایە).','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:96',(select id from public.theory_sections where slug = 'safety-and-vehicle'),32,'What should you do when you leave your car unattended for a few minutes?','دەبێـت چـی بکەیت کاتێک کە ئۆتۆمبێـلەکەت بەبـێ ئەوەی کەسـی تیا بێت بۆ ماوەى چەند خولەکێک بەجێدەهــــێڵـیت؟','Lock it and remove the key','ئۆتۆمبێلەکە قفڵ بکە و سویچەکە لەگەڵ خۆت ببە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:97',(select id from public.theory_sections where slug = 'safety-and-vehicle'),33,'What makes the vehicle in the picture ''environmentally friendly''?','چــى وا لەم ترامەی نێو وێنەکە دەکــات دۆستــــى ژینگە بێـت؟','It''s powered by electricity','بەهــۆى کـارەباوە وزەکەى دابین کراوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:98',(select id from public.theory_sections where slug = 'safety-and-vehicle'),34,'Why have ''red routes'' been introduced in major cities?','بۆچـى ئەو ڕێگـایانە هێڵـی سوورن لە شارە سەرەکییەکـاندا هەیە؟','To help the traffic flow','بۆ یارمەتیدانـى بەردەوام بوونـى هاتووچۆى ئۆتۆمبـێل.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:99',(select id from public.theory_sections where slug = 'safety-and-vehicle'),35,'The fluid level in your battery is low. What fluid should you use to top it up?','ئاستـى شلەى ناو پاترییـەکەت نزمە. دەبێت چ شـلەیەک بۆ پڕکردنـى بەکاربهـێنـى ؟','Distilled water','ئاوی دڵۆپێنـراو.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:100',(select id from public.theory_sections where slug = 'safety-and-vehicle'),36,'When should you check the engine oil level?','کەى دەبێـت چێکـی ڕۆنـى بزوێنەر بکەیــــــــــــــت؟','Before a long journey','پێش دەستپێکردنـى گەشتێکـى دریژ.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:101',(select id from public.theory_sections where slug = 'safety-and-vehicle'),37,'How will you benefit from following the manufacturer''s service schedule for your vehicle?','چۆن سوودمەند دەبیـــــــــــت لە پابەندبوون بە ڕێنماییەکانـى خزمەتگوزارى کۆمپانیاى چاکردنەوەی ئۆتۆمـبێلەکەتەوە؟','Your vehicle will remain reliable','ئۆتۆمبێلەکەت زیاتر تۆکمە دەبێت پشتـی پـێ بەستـی.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:102',(select id from public.theory_sections where slug = 'safety-and-vehicle'),38,'What does it mean if this light comes on while you''re driving?','هەڵبوونـى ئەم گـڵۆپ لەکاتـی شۆفێـری کردنە مانای چیە؟','A fault in the braking system','هەڵەیەک لە سیستەمـى برێکدا هەیە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:103',(select id from public.theory_sections where slug = 'safety-and-vehicle'),39,'You have to arrive on time for an appointment. How should you plan for the journey?','دەبێــت لە کاتـى خۆیدا لە چاوپێکەوتنێکدا ئامادەبیت. چۆن پلانـى گەشتەکە دادەنێیت؟','Allow plenty of time for the trip','کاتێکـى زۆرتر بۆ گـەشتەکە دابنێ.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:104',(select id from public.theory_sections where slug = 'safety-and-vehicle'),40,'How can you reduce the risk of your vehicle being broken into at night?','چۆن دەتوانـى مەترسـی شکاندنـی سەر ئۆتۆمبێلەکەت کەمبکەیتەوە لە شەودا؟','Leave it in a well-lit area','ئۆتۆمـبێلەکەت بەجێبـهێڵە لە ناوچەیەک کە بە باشـی ڕووناککرابێتەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:105',(select id from public.theory_sections where slug = 'safety-and-vehicle'),41,'What can you achieve if you drive smoothly?','چى بەدەست دەهێنـی ئەگەر بە لەسەرخۆی شۆفێـری بکەیت؟','Reduction in fuel consumption by about 15%','کەمکـردنەوەى بەکارهێنانـى سووتەمەنـى بە نزیکەى ١٥%.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:106',(select id from public.theory_sections where slug = 'safety-and-vehicle'),42,'How can you help to prevent your car radio being stolen?','چۆن دەتوانـى ڕێگە لە دزینـى ڕادیۆى ناو ئۆتۆمبێـلەکەت بگریت؟','Install a security-coded radio','جێگیرکردنـى ڕادیـۆیەک کە کۆدى ئاسایش (سکیورتـى) لەگەڵ بێــــــت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:107',(select id from public.theory_sections where slug = 'safety-and-vehicle'),43,'What''s the purpose of road humps, chicanes and narrowings?','تاسەکانـى رێگـاوبان و هێڵەکـان و تەسکـکردنەوەکان بۆ چ مەبەستێک بەکاردێن؟','To reduce traffic speed','بۆ کەمکردنەوەى خێرایـی هاتووچۆى ئۆتۆمبێل.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:108',(select id from public.theory_sections where slug = 'safety-and-vehicle'),44,'How would under-inflated tyres affect your vehicle?','چۆن ئەو تایەى کەم هەوا کـاریگەرى دەخاتە سەر ئۆتۆمبێلەکەت؟','The vehicle''s stopping distance would increase','مەوداى ئیستۆپ گرتنـى ئۆتۆمبێـلەکەت زیاد دەکـات.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:109',(select id from public.theory_sections where slug = 'safety-and-vehicle'),45,'What does it mean if your vehicle keeps bouncing after you sharply press down and release on the bodywork over a wheel?','واتای چییە ئەگەر بە توندی دەستت خستە سەر بۆنیدی ئوتومبیلەکە و پاشان دەستت لابرد بەڵام بۆنیدەکە زۆر بەرز و نزم بکات ؟','The shock absorbers are worn','دەبڵـی ئۆتۆمبـێلەکە خراپ بووە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:110',(select id from public.theory_sections where slug = 'safety-and-vehicle'),46,'When are you not allowed to sound your vehicle''s horn?','کەى ڕێگـەت پێنادرێــت هۆرنـى ئۆتۆمبێلەکەت لێبدەیـــــــت؟','Between 11.30 pm and 7.00 am in a built-up area','لە نێوان ١١.٣٠ شەو بـۆ ٧ ی بەیانـى لە ناوچەى دانیشتوان.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:111',(select id from public.theory_sections where slug = 'safety-and-vehicle'),47,'What will happen if your car''s wheels are unbalanced?','چـی ڕوودەدات ئەگەر تایەکانـى ئۆتۆمبێلـەکەت باڵانس نەبن ؟','The steering will vibrate','سووکانـى ئۆتۆمبێلەکە دەلەرزێـت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:112',(select id from public.theory_sections where slug = 'safety-and-vehicle'),48,'How can you reduce the chances of your car being broken into when leaving it unattended?','چۆن دەتوانیت چانسـی شکاندنـى دەرگـاو پەنجەرەى ئۆتۆمبێلەکەت کەم بکەیتەوە کاتێک جێیدەهێڵیت و کەسـی تێدا نییە؟','Take all valuables with you','هەموو شتێکـى بە بەهـا لەگەڵ خۆت بەریت .','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:113',(select id from public.theory_sections where slug = 'safety-and-vehicle'),49,'How can you avoid wasting fuel?','چۆن ڕێگری لە بەفیڕۆدانـى سووتەمەنـى دەکەیت؟','By having your vehicle serviced regularly','لە ڕێگەى بەردەوام سێرڤسکردنـی ئۆتۆمبیلەکەت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:114',(select id from public.theory_sections where slug = 'safety-and-vehicle'),50,'Why do MOT tests include an exhaust emission test?','بۆچـى تێستـىMOT تێستـی دەردراوەکانـى ئەگزۆزى ئۆتۆمبێل(ئەگزۆز) تێدایە؟','To help protect the environment against pollution','بۆ پاراستنـى ژینگە لە پیس بوونـى بەهۆی ئوتومبیـلەکەتەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:115',(select id from public.theory_sections where slug = 'safety-and-vehicle'),51,'How can you plan your route before starting a long journey?','چۆن پلان بۆ ڕێگەکەت دادەنێیت پێش دەستپێکردنـى گەشتێکـى درێژ؟','Use a route planner on the internet','ڕۆد پلانەری سەر ئینتەرنێت بەکاربهێنە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:116',(select id from public.theory_sections where slug = 'safety-and-vehicle'),52,'You have to make an unexpected journey. You''re carrying a five-year-old child on the back seat of your car. They''re under 1.35 metres (4 feet 5 inches) tall. How should you seat them if a correct child restraint isn''t available?','‎دەبێـت گەشتێکـى چاوەڕوان نەکراو ئەنجام بدەیــت. منداڵێکـى تەمەن پێنج ساڵت لەکوشنـى دواوە داناوە و بەرزى باڵاى لە خوارەو ١.٣٥مەتر (٤ پـێ بۆ ٥ ئینج). چۆن دەتوانـى منداڵەکە دابنشێنـى لەسەر کوشنەکە لە حاڵەتێکدا ئەگەر کوشنـى تایبەت بە منداڵ بەردەست نەبوو؟','Using an adult seat belt','‎بە بەکارهێنانـى قایشـی سەلامەتـى سەرنشینـى گەورە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:117',(select id from public.theory_sections where slug = 'safety-and-vehicle'),53,'When should tyre pressures be checked?','‎کەی دەبێــت چێکـی پەستانـى هەواى تایە بکرێت؟','When tyres are cold','‎کاتێک کە تایەکـان ساردن.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:118',(select id from public.theory_sections where slug = 'safety-and-vehicle'),54,'How can you reduce the damage your vehicle causes to the environment?','‎چۆن دەتوانـى ئەو زیانە کەم بکەیتەوە کە ئۆتۆمبێلەکەت دەیگەیەنێــــــــت بە ژینگە؟','Anticipate well ahead','‎بەباشـی پێشەوەى ڕێگـاکە بخوێنەرەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:119',(select id from public.theory_sections where slug = 'safety-and-vehicle'),55,'How will your journey be affected by travelling outside the busy times of day?','گەشتەکەت چۆن دەبێت ئەگەر لەدەرەوەى کاتە قەرەباڵەغەکانـى ڕۆژ لێبخوڕی؟','Your journey will have fewer delays','گەشتەکەت دواکەوتنـى کەمترى تێدەکەوێـــــــــــت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:120',(select id from public.theory_sections where slug = 'safety-and-vehicle'),56,'How much more fuel will you use by driving at 70 mph, compared with driving at 50 mph?','چەندێک سووتەمەنـى زیاتر بەکاردەهێنـى لە لێخوڕین لە خێرای ٧٠ میل لە کاتژمێرێـکدا بە بەراورد بەخێرایـی لە ٥٠ میل لە کاتژمێرێکدا؟','About 15%','نزیکەى ١٥%.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:121',(select id from public.theory_sections where slug = 'safety-and-vehicle'),57,'What can cause excessive or uneven tyre wear?','چـى دەبێتە هۆى ساف بوونـى ڕووکـارى دەرەوەى تایەکـان؟','A faulty braking system','کێشە لە سیستەمـى برێکدا.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:122',(select id from public.theory_sections where slug = 'safety-and-vehicle'),58,'What''s the safest thing to do if you have to leave valuables in your car?','سەلامەتترین شت چییە بیکەیت ئەگەر پێویستـی کرد شتە بەبەهاکـانت لە ئۆتۆمبێلەکەت بەجێبهێڵـى؟','Lock them out of sight','لەشوێنێـک دایانبنـێ کە بەرچاو نەبێت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:123',(select id from public.theory_sections where slug = 'safety-and-vehicle'),59,'How will a roof rack affect your car?','چۆن سلایدى سەقف کاریگەرى دەخاتە سەر ئۆتۆمبێلەکەت؟','Fuel consumption will increase','بەکارهێنانـى سووتەمەنـى ئۆتۆمبێلەکە زیاتردەبێــت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:124',(select id from public.theory_sections where slug = 'safety-and-vehicle'),60,'You service your own vehicle. How should you dispose of the old engine oil?','خۆت خزمەتگوزارى بۆ ئۆتۆمبێلەکەت ئەنجام دەدەیت. چۆن ڕۆنـى کۆنـى ئۆتۆمبێلەکەت فڕێ دەدەیت؟','Take it to a local-authority site','بیبە بۆ شوێنـی ڕێگەپێدراوی وەرگرتنـی ڕۆن.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:125',(select id from public.theory_sections where slug = 'safety-and-vehicle'),61,'How can driving in a fuel-efficient manner help protect the environment?','چۆن شۆفێرى کردن بە شێوازێک کە ڕێگربێـــت لە بەفیڕۆچوونـى سووتەمەنى یارمەتـى پاراستنـى ژینگە دەدات؟','By reducing exhaust emissions','لە ڕێگەى کەمکردنەوەى دەردراوەکـانـى ئەگزۆزەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:126',(select id from public.theory_sections where slug = 'safety-and-vehicle'),62,'How should you dispose of a used vehicle battery?','چۆن باترى بەکارهێنراو فڕێ دەدەیــــت؟','Take it to a local-authority disposal site','بیبەیت بۆ شوێنـى فڕێدانـى پاتری لە ناوچەکەدا.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:127',(select id from public.theory_sections where slug = 'safety-and-vehicle'),63,'Why is it important to wear suitable shoes when you''re driving?','بۆچـى لەپـێ کردنـى پێڵاو گرنگە لە کاتێکدا شۆفێرى دەکەیـــــت؟','To maintain control of the pedals','بۆ کۆنترۆڵ کردنـی پایدەرەکان.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:128',(select id from public.theory_sections where slug = 'safety-and-vehicle'),64,'Why should you try and park in a secure car park?','بۆچـى دەبێـت هەوڵ بدەیـــت و ئۆتۆمبێلەکەت لە گەراجێکـى سەلامەتـى ئۆتۆمبێل پارک بکەیت؟','It helos deter thieves','ڕێگری لە دزەکـان دەکات.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:129',(select id from public.theory_sections where slug = 'safety-and-vehicle'),65,'You''re carrying two 13-year-old children and their parents in your car. Who''s responsible for seeing that the children wear seat belts?','دوو منداڵـى تەمەن ١٣ ساڵ و دایک و باوکیانت سەرخستووە لە ئۆتۆمبێلەکەتدا. کـێ بەرپرسە لە ئەوەى منداڵەکـان پشتوێنـى سلامەتـى ببەستن؟','You, the driver','تۆى شۆفـێر.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:130',(select id from public.theory_sections where slug = 'safety-and-vehicle'),66,'What''s likely to happen if you put too much oil in your engine?','دەکرێـت چـى ڕووبدات ئەگەر تۆ ڕۆنـى زۆر بکەیتە نێو بزوێنەرى ئۆتۆمبێلەکەتەوە؟','The oil seals will leak','شوێنـى قەپاتـکردنـى ڕۆنەکە لێدەچێت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:131',(select id from public.theory_sections where slug = 'safety-and-vehicle'),67,'What should you remove from your car before leaving it unattended?','دەبێت چـى لە نێو ئۆتۆمبێلەکەت لابەریت پێش ئەوەى بەجێبهێڵـى و هیچ سەرنشینیکىشـی تیدا نەبێــت؟','The vehicle registration document','بەڵگەنامەى تۆمارکردنـى ئۆتۆمبێلەکە(ڕیجیسترەیشن).','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:132',(select id from public.theory_sections where slug = 'safety-and-vehicle'),68,'What''s the legal minimum depth of tread for car tyres?','کەمترین قوڵـى ڕێگەپێدراوى نەخشـی سەر تایەکـان چەندە؟','1.6mm','١.٦ ملم','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:133',(select id from public.theory_sections where slug = 'safety-and-vehicle'),69,'What could cause you to crash if the level is allowed to get too low?','چـی دەبێـتە هـــۆى ئەوەى کە ئۆتۆمبێـلەکەت تووشـی بەیەکدادان بێــت ئەگەر ئەو ئاستەى کە ڕێگـەى پێدراوە زۆر نزم بێتەوە؟','Brake-fluid level','ئاستـى ڕۆنـى برێک.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:134',(select id from public.theory_sections where slug = 'safety-and-vehicle'),70,'You plan your route before starting a journey. Why should you also plan an alternative route?','پلانـت بۆ ڕێگەکەت داناوە پێش دەستپێکردنـى گەشتەکەت. بۆچـى لە هامان کاتدا دەبێـت پلانـى ڕێگەیەکـى جێگرەوە دابنێیت؟','Your original route may be blocked','لەوەیە ڕێگـای یەکەم کە هەڵتبـژاردووە گیرابێت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:135',(select id from public.theory_sections where slug = 'safety-and-vehicle'),71,'You''re carrying an 11-year-old child on the front seat of your car. They''re under 1.35 metres (4 feet 5 inches) tall. What seat belt security must be in place?','منداڵێکـى تەمەن ١١ ساڵت سەرخستووە لەسەر کوشنـى پێشەوەى ئۆتۆمبێلەکەت. باڵاى منداڵەکە لە خوارەوەى 1.35مەترە (٤ پـێ و ٥ ئینج). چ پشتوێنێکـى سەلامەتـى دەبێـــت بەکاربهێنریـت؟','They must use a suitable child restraint','دەبێــت کوشنـى تایبەت بە منداڵان بەکاربهێنـێــــت.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:136',(select id from public.theory_sections where slug = 'safety-and-vehicle'),72,'What does fuel-efficient driving achieve?','شۆفێرىکردن لەگەڵ ڕێگریکردن لە بەفیڕۆدانـى سووتەمەنـى سوودی چیە؟','Improved road safety','باشتربوونـى سەلامەتـى ڕێگـاوبان.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:137',(select id from public.theory_sections where slug = 'safety-and-vehicle'),73,'What should you do if your vehicle pulls to one side when you use the brakes?','دەبێـت چـی بکەیت کاتێک برێکەکانت بەکاردەهـێنیت ئۆتۆمبێلەکەت بۆ لایەک دەچێت؟','Have the brakes checked as soon as possible','بە زووترین کات چێکـی برێکەکـان بکە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:138',(select id from public.theory_sections where slug = 'safety-and-vehicle'),74,'Where would parking your vehicle cause an obstruction?','لە کوێ پارکینـی ئۆتۆمبێلەکەت دەبێتە هۆى ڕێگەگرتن؟','In front of a property entrance','لە پێش دەرگـاى چوونەژوورەوەى شوێنێک.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:139',(select id from public.theory_sections where slug = 'safety-and-vehicle'),75,'You''re stopped at the side of the road. What must you do if you''ll be waiting there for some time?','ئۆتۆمبێلەکەت وەستاندووە لەسەر لایەکـى ڕێگـاکە. دەبێـت چـی بکەیت ئەگەر چاوەڕوان بیت بۆ ماوەیەک؟','Switch off the engine','بزوێنەرى ئۆتۆمبێلەکە بکوژێنیتەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:140',(select id from public.theory_sections where slug = 'safety-and-vehicle'),76,'Which driving technique can help you save fuel?','چ تەکنیکێکـى شۆفێری کردن دەتوانێت یارمەتیت بدات لە کەم بەکارهێنانـی سووتەمەنیدا؟','Missing out some gears','بەکـارنەهێـنانـی هەندێک گێـڕ.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:141',(select id from public.theory_sections where slug = 'safety-and-vehicle'),77,'What''s the purpose of a catalytic converter?','کەتەلایزەر کۆنڤێرتەر بۆ چ مەبەستێک بەکاردێـــــت؟','To reduce harmful exhaust gases','بۆ کەمـکـردنەوەى گازە زیانبەخشەکانـى ئەگزۆز.','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:142',(select id from public.theory_sections where slug = 'safety-and-vehicle'),78,'You''re driving a car with blind-spot monitoring function. What must you regularly check to make sure that the function will work properly?','تۆ ئۆتۆمبیلێک لێدەخوڕیت کە ئەرکی چاودێریکردنی خاڵی کوێری هەیە. پێویستە بە بەردەوامی چی بپشکنی بۆ دڵنیابوون لەوەی کە کردارەکە بە باشی کار دەکات؟','That the sensors on the car are clean','کە هەستەوەرەکانی سەر ئۆتۆمبێلەکە خاوێنن','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:143',(select id from public.theory_sections where slug = 'safety-and-vehicle'),79,'You''re driving along a dual carriageway. This symbol is displayed on your dashboard. Which advanced driver-assistance system is turned on?','تۆ بە درێژایی دوو ڕێگا لێدەخوڕیت. ئەم هێمایە پیشان دەدرێت لەسەر داشبۆردەکەت. کام سیستەمی پێشکەوتووی یارمەتیدانی شۆفێر هەڵکراوە؟','Lane-keep assist','یارمەتیدەری هێشتنەوەی هێڵ','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:144',(select id from public.theory_sections where slug = 'safety-and-vehicle'),80,'Modern cars are often fitted with a variety of technologies, called advanced driver-assistance systems. What is the main purpose of these systems?','ئۆتۆمبێلە مۆدێرنەکان زۆرجار تەکنەلۆژیای جۆراوجۆریان تێدایە کە پێی دەوترێت سیستەمی پێشکەوتووی یارمەتی شۆفێر. مەبەستی سەرەکی ئەم سیستەمانە چییە؟','To make the roads safer','بۆ ئه وه ی ڕێگاکان سه لالامه تتر بکه ن','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:145',(select id from public.theory_sections where slug = 'safety-and-vehicle'),81,'You''re driving along a motorway and switch on adaptive cruise control. What are you now allowed to do?','تۆ بە درێژایی ڕێگایەکی خێرا لێدەخوڕیت و کروز کۆنتڕۆڵی خۆگونجاندن دادەگیرسێنیت. ئێستا ڕێگەت پێدراوە چی بکەی؟','Check the road signs','هێماکانی ڕێگا بپشکنە','draft','content:uk-theory-questions'),
  ('theory:safety-and-vehicle:146',(select id from public.theory_sections where slug = 'safety-and-vehicle'),82,'Which advanced driver-assistance systems is designed to actively prevent collisions?','کام سیستەمی پێشکەوتووی یارمەتیدەری شۆفێر بۆ ڕێگریکردن لە پێکدادانەکان دروستکراوە؟','Advanced emergency braking system','سیستەمی پێشکەوتووی برێکی فریاگوزاری','draft','content:uk-theory-questions'),
  ('theory:safety-margins:147',(select id from public.theory_sections where slug = 'safety-margins'),1,'What should you do when you''re overtaking a motorcyclist on a windy day?','دەبێت چی بکەیت کاتێک کە ماتۆڕسوارێک تێدەپەڕێنیت لە ڕۆژێکدا کە باى هەیە؟','Pass widely','بە دووری زۆر تێپەڕێنە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:148',(select id from public.theory_sections where slug = 'safety-margins'),2,'What should you do before starting a journey in foggy weather?','تۆ دەبێت چی بکەیت پێش دەستپێکردنى گەشتێک لە کەش و هەوایەکى تەماویدا؟','Allow more time','ڕێگا بدە بە کاتى زیاتر واتە درەنگ تر برۆ','draft','content:uk-theory-questions'),
  ('theory:safety-margins:149',(select id from public.theory_sections where slug = 'safety-margins'),3,'You''re driving along a country road. You see this sign. What should you do after dealing safely with the hazard?','بە درێژایی ڕێگاى دەرەوەى شار شۆفێری دەکەیت. ئەم هێمایە دەبینیت. دەبێت چی بکەیت لە پاش مامەڵە کردن بە شێوەیەکى سەلامەت لەگەڵ مەترسییەکە؟','Test your brakes','برێکەکانت تێست بکە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:150',(select id from public.theory_sections where slug = 'safety-margins'),4,'You''re travelling on the motorway. How can you lower the risk of a collision when the vehicle behind is following too closely?','لەسەر مۆتۆروەییەک گەشت دەکەیت. چۆن دەتوانیت مەترسی بەیەکدادان کەم بکەیتەوە کاتێک ئوتومبێلێک زۆر بە نزیکى لە دواوەیە؟','Increase your distance from the vehicle in front','مەوداى دووری لە ئۆتۆمبێلەکەى پێشەوەت زیاتر بکە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:151',(select id from public.theory_sections where slug = 'safety-margins'),5,'You''re following other vehicles in fog. You have your headlights on dipped beam. What else can you do to reduce the chances of being in a collision?','لە دواى کۆمەڵە ئۆتۆمبێلەکەوە ڕێ دەکەیت لە کەشێکی تەماویدا. لایتى پێشەوەت خستووەتە سەر نزم. دەتوانیت چی تر بکەیت بۆ کەمکردنەوەى ئەگەری بەیەکدادان؟','Keep a safe distance from the vehicle in front','مەوداى دوورى سەلامەتى لەگەڵ ئۆتۆمبێلەکانى پێشەوە بهێڵەرەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:152',(select id from public.theory_sections where slug = 'safety-margins'),6,'What requires extra care when you''re driving or riding in windy conditions?','چی پێویستى بە وریایی زیاترە کاتێک شۆفیری دەکەیت یان ماتۆڕسکیل لێدەخوڕیت لە کەشى باد؟','Passing pedal cyclists','تێپەڕین بە تەنیشت پاسکیل سوارەکاندا.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:153',(select id from public.theory_sections where slug = 'safety-margins'),7,'You''ve just gone through flood water. What should you do to make sure your brakes are working properly?','کەمێک دەبێت بە نێو ئاوى لافاودا ڕۆیشتوویت. دەبێت چی بکەیت بۆ دڵنیابوونەوە لەوەى کە برێکەکانت بە تەواوەتى کار دەکەن؟','Go slowly while gently applying the brakes','بە هێواشی بڕۆ و بە نەرمى برێک بگرە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:154',(select id from public.theory_sections where slug = 'safety-margins'),8,'In which conditions will your overall stopping distance increase?','لە چ بارودۆخێکدا مەودای گشتى ئیستۆپ گرتنەکەت زیاد دەکات؟','In the rain','لە کەش و هەواى باراناویدا.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:155',(select id from public.theory_sections where slug = 'safety-margins'),9,'You''re driving in freezing conditions. What should you do as you approach a sharp bend?','لە کەشێکی زۆر ساردا بەڕادەیەک لە ئاستى بەستندایە شۆفێرى دەکەیت. دەبێت چی بکەیت کاتێک نزیک دەبیتەوە لە ڕێگایەکی کورتی زۆر چەماوەدا؟','Slow down gently','بە نەرمی ئۆتۆمبێلەکەت هێواش بکەرەوە','draft','content:uk-theory-questions'),
  ('theory:safety-margins:156',(select id from public.theory_sections where slug = 'safety-margins'),10,'What should you do when you park a car facing downhill?','دەبێت چی بکەیت کاتێک ئۆتۆمبێلێک پارکین دەکەیت لە گردێکی لێژدا؟','Turn the steering wheel towards the kerb','سووکانەکە ڕووە و قەراغی ڕێگاکە بسوڕینە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:157',(select id from public.theory_sections where slug = 'safety-margins'),11,'Why should you keep well to the left as you approach a right-hand bend?','بۆچى دەبێت لە دەستە چەپ بمێنیتەوە کاتێک نزیک دەبیتەوە لە ڕێگایەکی چەماوە بۆ دەستە ڕاست؟','To improve your view of the road','بۆ باشترکردنى ئاسۆى بینینت بۆسەر ڕێگاکە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:158',(select id from public.theory_sections where slug = 'safety-margins'),12,'How can you avoid wheelspin when you''re driving on an icy road?','چۆن خۆت بە دووردەگریت لە حاڵەتى خولانى تایە (فەرتەناش)لە کاتێکدا شۆفێری دەکەیت لەسەر ڕێگایەکى بەستوو؟','Drive at a slow speed in the highest gear possible','بە خێراییەکى کەم و بە گێڕی بەرزشۆفێری بکە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:159',(select id from public.theory_sections where slug = 'safety-margins'),13,'What will be affected if the road surface becomes soft in very hot weather?','چی کاریگەرى دەکەوێتە سەر لە حاڵەتێکدا ئەگەر ڕووى ڕێگاکە سۆفت بێت لە کەشێکی زۆر گەرمدا؟','The tyre grip','توانای لێکخاشاندنی(گرتن) تایەکە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:160',(select id from public.theory_sections where slug = 'safety-margins'),14,'On what type of road surface may anti-lock brakes be ineffective?','لە چ جۆرە ڕوویەکى سەر ڕێگا دەکرێت برێکى دژە قوفڵ ئیش نەکات؟','Loose','ڕێگایەک بەرد و چەوی لەسەر بێت.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:161',(select id from public.theory_sections where slug = 'safety-margins'),15,'You''re about to start a journey in freezing weather. What part of your vehicle should you clear of ice and snow?','بەتەمایت لە کەشێکی بەستوودا دەست بە گەشتێک بکەیت. دەبێت چ بەشێکى ئۆتۆمبێلەکە لە سەهۆڵ و بەفر پاک بکەیتەوە؟','The windows','پەنجەرەکانى ئۆتۆمبێلەکە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:162',(select id from public.theory_sections where slug = 'safety-margins'),16,'How should you use anti-lock brakes when you need to stop in an emergency?','چۆن دەبێت برێکى دژە قوفڵ بەکاربهێنیت کاتێک پێویستى کرد بوەستیت لە حاڵەتى ئیمرجنسیدا؟','Brake promptly and firmly until you''ve stopped','دەست بەجێ و بە توندى برێک بگرە تاوەکو دەوەستیت.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:163',(select id from public.theory_sections where slug = 'safety-margins'),17,'You''re driving on an open road in dry weather. What distance should you keep from the vehicle in front?','لەسەر ڕێگایەکى کراوە و لە کەشێکی وشکدا شۆفیری دەکەیت. دەبێت مەودای دووریت لە ئۆتۆمبێلەکەى پێشەوە چەند بێت؟','A two-second time gap','بۆشایى دوو چرکەیی.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:164',(select id from public.theory_sections where slug = 'safety-margins'),18,'Where is your vehicle most likely to be affected by side winds?','لە کوێ زیاتر ئۆتۆمبێلەکەت دەکرێت کاریگەرى بکەوێتە سەر بەهۆی ئەو بایانەی لە لاتەنیشت ڕێگاکانەوە هەڵدەکەن؟','On an open stretch of road','لەسەر ڕێگایەکى درێژبووەوەى کراوە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:165',(select id from public.theory_sections where slug = 'safety-margins'),19,'You''re driving along a wet road. How can you tell if your vehicle''s tyres are losing their grip on the surface?','شۆفێری دەکەیت بە درێژایی ڕێگایەکى تەڕدا. چۆن دەزانیت ئەگەر تایەکانى ئۆتۆمبێلەکەت هێزى لێکخشاندنیان بۆ گرتنى ڕووى ڕێگاکە لەدەست دەدەن؟','The steering will feel very light','سووکانەکە زۆر سووک دەبێت.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:166',(select id from public.theory_sections where slug = 'safety-margins'),20,'You''re driving in a built-up area that has traffic-calming measures. What should you do when you approach a road hump?','لە ناوچەیەکى قەرەباڵغدا شۆفێری دەکەیت هێڵەکانی کەمکردنەوەی خێرایی لەسەرە. دەبێت چی بکەیت کاتێک نزیک دەبیتەوە لە تاسەیەک؟','Check your mirror and slow down','سەیری ئاوێنەکەت بکەو ئۆتۆمبێلەکەت هێواش بکەرەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:167',(select id from public.theory_sections where slug = 'safety-margins'),21,'What will help you to move off on a snowy surface?','چی یارمەتیت دەدات بۆ ئەوەى ئۆتۆمبێلەکەت لەسەر ڕوویەک کە بەفرى لەسەر بێت لێبخوڕیت؟','Using a higher gear than normal','گێڕی بەرز بە بەراورد لەگەڵ گێرێکى ئاسایی بەکاربهێنە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:168',(select id from public.theory_sections where slug = 'safety-margins'),22,'What lights should you use when you''re driving on a wet motorway and vehicles are throwing up surface spray?','دەبێت چ لایتێک بەکاربهێنیت کاتێک لەسەر مۆتۆروەیەکى تەڕ شۆفێری دەکەیت و ئۆتۆمبێلەکانى تریش پرژەی ئاویان لێ دەردەچێت؟','Dipped headlights','لایتی نزمى پێشەوە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:169',(select id from public.theory_sections where slug = 'safety-margins'),23,'How can you use your vehicle''s engine as a brake?','چۆن دەتوانى بزوێنەرى ئۆتۆمبێلەکەت وەکو برێک بەکاربهێنى؟','By changing to a lower gear','لە ڕێگەى گۆڕینى گێڕەکە بۆ گێڕی نزم.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:170',(select id from public.theory_sections where slug = 'safety-margins'),24,'What should you do when you''re using a contraflow system?','دەبێت چی بکەیت کاتێک کە سیستەمى ئاڕاستەى پێچەوانەى ڕێگا بەکاردەهێنیت؟','Choose an appropriate lane in good time','سایدێکى گونجاو لە کاتی گونجاو هەڵبژێرە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:171',(select id from public.theory_sections where slug = 'safety-margins'),25,'You''re driving a vehicle that has anti-lock brakes. How should you apply the footbrake when you need to stop in an emergency?','شۆفیری ئۆتۆمبێلێک دەکەیت کە برێکى دژە قوفڵى هەیە. چۆن دەبێت برێکى پێ بەکاربهێنیت کاتێک پێویستە لە حاڵەتێکى ئیمەرجنسیدا بوەستیت؟','Rapidly and firmly','بە خێرایی و بە توندى.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:172',(select id from public.theory_sections where slug = 'safety-margins'),26,'How much can stopping distances increase in icy conditions?','چەند جار مەوداى برێکگرتنەکە زیاد دەبێت لە کەش وهەوای سەهۆڵینەکاندا؟','Ten times','دە جار.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:173',(select id from public.theory_sections where slug = 'safety-margins'),27,'What''s the main cause of skidding?','هۆکارى سەرەکى خلیسکانى ئۆتۆمبێل چییە؟','The driver','شۆفێرەکە','draft','content:uk-theory-questions'),
  ('theory:safety-margins:174',(select id from public.theory_sections where slug = 'safety-margins'),28,'What can result when you travel for long distances in neutral (known as coasting)?','چ ئەنجامێکى دەبێت کاتێک بۆ ماوەیەکى دوور و درێژ بە گێڕی بۆش گەشت دەکەیت؟','Reduction in control','کەمبوونەوەی کۆنترۆڵکردن.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:175',(select id from public.theory_sections where slug = 'safety-margins'),29,'What should you do when you''re driving in snowy conditions?','دەبێت چی بکەیت کاتێک شۆفێری دەکەیت لە کەشی بەفر باریندا؟','Brake gently in plenty of time','زۆربەی کاتەکان بەنەرمی برێک بگرە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:176',(select id from public.theory_sections where slug = 'safety-margins'),30,'What''s the main benefit of driving a four-wheel-drive vehicle?','سوودی سەرەکى لێخوڕینی ئۆتۆمبێلى سیستەمى چوار تایە سووڕاو چییە؟','Improved grip on the road','تایەکە باشتر ڕێگاکە دەگرێت.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:177',(select id from public.theory_sections where slug = 'safety-margins'),31,'You''re following a vehicle on a wet road. You stay a safe distance behind it. What should you do if a driver overtakes you and pulls into the gap you''ve left?','لە دواى ئۆتۆمبێلێکەوەیت لەسەر ڕێگایەکى تەڕ. بۆشایی سەلامەتیت لە دواوەی ئۆتۆمبێلەکە بەجێهێشتووە. دەبێت چی بکەیت ئەگەر شۆفێرێک تۆی تێپەڕاند وە ڕۆیشتە نێو ئەو بۆشاییە سەلامەتەى هێشتووتەتەوە؟','Drop back to regain a safe distance','بڕۆ دواوە بۆ دووبارە بەجێهێشتنی مەوداى سەلامەتی.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:178',(select id from public.theory_sections where slug = 'safety-margins'),32,'What would suggest you''re driving on an icy road?','چی ڕوودەدات کاتێک لەسەر ڕێگایەکى سەهۆڵین شۆفێری دەکەیت؟','There''s less tyre noise','دەنگى تایەکان کەمترە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:179',(select id from public.theory_sections where slug = 'safety-margins'),33,'You''re about to go down a steep hill. What should you do to control the speed of your vehicle?','خەریکى بە گردێکى لێژدا دەڕۆیتە خوارەوە. دەبێت چی بکەیت بۆ کۆنترۆڵکردنى خێرایی ئۆتۆمبێلەکەت؟','Select a low gear and use the brakes carefully','گێڕى نزم هەڵبژێرەو برێک بە وریاییەوە بەکاربهێنە.','draft','content:uk-theory-questions'),
  ('theory:safety-margins:180',(select id from public.theory_sections where slug = 'safety-margins'),34,'What''s most likely to waste fuel?','چى زیاتر دەبێتە هۆى بەفیڕۆدانى سووتەمەنى؟','Under-inflated tyres','ئەگەر تایەکان کەم هەوا بوو.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:181',(select id from public.theory_sections where slug = 'hazard-awareness'),1,'What should you do if a driver pulls out of a side road in front of you, causing you to brake hard?','دەبێت چی بکەیت ئەگەر شۆفێرێک لە پێشەوەت لابداتە سەر قەراغی ڕێگاکە وە ببێتە هۆى ئەوەى کە تۆ بە توندى برێک ڕابکێشیت؟','Ignore the error and stay calm','هەڵەکە پشتگوێ بخەو بە هێمنى بمێنەرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:182',(select id from public.theory_sections where slug = 'hazard-awareness'),2,'You''re approaching a crossroads. What should you do if the traffic lights have failed?','نزیک دەبیتەوە لە ڕێگایەکى یەکتربڕ. دەبێت چی بکەیت ئەگەر ترافیک لایتەکان لەکارکەوتن؟','Be prepared to stop for any traffic','ئامادە بە بۆ وەستان بۆ هەر جۆرە هاتووچۆیەکى ئۆتۆمبێل.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:183',(select id from public.theory_sections where slug = 'hazard-awareness'),3,'What should you do if the vehicle starts reversing off the driveway?','دەبێت چی بکەیت ئەگەر ئۆتۆمبێلەکە دەستیکرد بە هاتنە دەرەوە بە بەگدا لە ڕاڕەوى حەوشەکەوە بۆ سەر شەقامەکە؟','Sound your horn and be prepared to stop','هۆرنەکەت لێبدە و ئامادە بە بۆ وەستان.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:184',(select id from public.theory_sections where slug = 'hazard-awareness'),4,'What should you expect if you see this sign ahead?','پێشبینى چی دەکەیت ئەگەر لە پێشەوە ئەم هێمایەى هاتووچۆ ببینیت؟','The road will bend sharply to the left','ڕێگاکە پێچى زۆر کورتی بۆ دەستە چەپ تێدیە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:185',(select id from public.theory_sections where slug = 'hazard-awareness'),5,'Why are vehicle mirrors often slightly curved (convex)?','بۆچى ئاوێنەکانى ئۆتۆمبێلەکان زۆر جار کەمێک ڕووچاڵن (قۆقزن)؟','They give a wider field of vision','مەودای بینینی بەرفراوانتر دەستەبەردەکەن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:186',(select id from public.theory_sections where slug = 'hazard-awareness'),6,'What should you do if you think the driver of the vehicle in front has forgotten to cancel their right indicator?','دەبێت چی بکەیت ئەگەر پێت وایە شۆفێرى ئۆتۆمبێلەکەى پێشەوە لەبیری چووە گڵۆپی ئیشارەتی دەستە ڕاست بکوژێنێتەوە؟','Stay behind and don''t overtake','لە دواوە بمێنەرەوەو تێپەڕاندن ئەنجام مەدە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:187',(select id from public.theory_sections where slug = 'hazard-awareness'),7,'What type of vehicle displays this yellow sign?','چ جۆرە ئۆتۆمبێلێک ئەم هێما زەردە پیشان دەدات؟','A school bus','پاسێکى قوتابخانە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:188',(select id from public.theory_sections where slug = 'hazard-awareness'),8,'What must you do if your eyesight has become very poor and you''re no longer able to meet the driver''s eyesight requirements?','دەبێت چی بکەیت ئەگەر ئاستى بینینى چاوت زۆر لاواز بوو و چی تر مەرجەکانى ئاستى بینیى شۆفێرت نەبوو؟','Tell the driver licensing authority','بە فەرمانگەى دەسەڵاتى پێدانى مۆڵەتى شۆفێرى بڵێیت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:189',(select id from public.theory_sections where slug = 'hazard-awareness'),9,'Why should the junction on the left be kept clear?','بۆ چى لە ڕێگا یەکتربڕەکەدا ڕێگەکەى دەستە چەپ بەردەمى بە بەردەوامى واڵا بێت؟','To allow vehicles to enter and emerge','بۆ ڕێگەدان بە ئۆتۆمبێلەکان بۆ ئەوەى داخڵ بە ڕێگەکە بن و لێی دەربچن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:190',(select id from public.theory_sections where slug = 'hazard-awareness'),10,'You''re invited to a pub lunch. What should you do if you know that you''ll have to drive in the evening?','بانگهێشتکراوى بۆ نیوەڕۆ خوانێک. دەبێت چی بکەیت ئەگەر زانیت لە ئێوارەکەی دەبێت شۆفێرى بکەیت؟','Don''t drink any alcohol at all','بەهیچ شێوەیەک هیچ خواردنەوەیەکى کحولى مەخۆرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:191',(select id from public.theory_sections where slug = 'hazard-awareness'),11,'What''s the main hazard the driver of the red car (arrowed) should be aware of?','سەرەکیترین مەترسى چییە کە شۆفیرى ئۆتۆمبێلە سوورەکە ( ئاماژەى بۆ کراوە) دەبێت لێی بەئاگا بێت؟','The bus may move out into the road','پاسەکە دەکرێت بێتە بەردەمى.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:192',(select id from public.theory_sections where slug = 'hazard-awareness'),12,'You''re driving towards this left-hand bend. What danger should you be anticipating?','بەرەو ئەم چەمانەوەیەى دەستە چەپ شۆفیرى دەکەیت، پێشبینى چ مەترسییەک دەکەیت؟','Pedestrians walking towards you','کەسانى پیادەڕۆ بەرەو ڕووت دێن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:193',(select id from public.theory_sections where slug = 'hazard-awareness'),13,'Why should you check the information leaflet before taking any medicine?','بۆ چى دەبێت نامیلکەى زانیاری ڕێنماییەکانى دەرمان بخوێنیتەوە پێش بەکارهێنانى هەر جۆرە دەرمانێک؟','Some types of medicine can affect your ability to drive safely','هەندێک لە جۆرەکانى دەرمان دەتوانن کاریگەرى بخەنە سەرت نەتوانی بە سەلامەتى لێبخوڕیت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:194',(select id from public.theory_sections where slug = 'hazard-awareness'),14,'What should the driver of the red car (arrowed) do?','شۆفێرى ئۆتۆمبێلە سوورەکە دەبێت چی بکات (ئەوەى کە بە تیرە زەردەکە ئاماژەى بۆ کراوە)','Wait for the pedestrian in the road to cross','چاوەڕێی پیادەڕۆکان دەکات لەسەر ڕێگاکە بۆ پەڕینەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:195',(select id from public.theory_sections where slug = 'hazard-awareness'),15,'You''re about to drive your car. What should you do if you can''t find the glasses you need to wear?','خەریکى ئۆتۆمبێلەکەت لێبخوڕیت. دەبێت چی بکەیت ئەگەر نەتوانى چاویلکەکانت بدۆزیتەوە کە پێویستە لەچاوی بکەیت؟','Find a way of getting home without driving','ڕێگایەک بدۆزەرەوە بۆ گەیشتن بە ماڵەوە بەبێ شۆفیری کردن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:196',(select id from public.theory_sections where slug = 'hazard-awareness'),16,'What should you do if you begin to feel drowsy while you''re driving?','دەبێت چی بکەیت ئەگەر هەستکرد خەواڵووى لە کاتێکدا شۆفێرى دەکەیت؟','Stop and rest as soon as possible','هەرچی زووە بوەستە و پشووبدە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:197',(select id from public.theory_sections where slug = 'hazard-awareness'),17,'What should you do about driving if you''ve been taking medicine that causes drowsiness?','دەبێت چی بکەیت ئەگەر بەتەمای شۆفێریکردن بیت و دەرمانێکت خواردبێت کە دەبێتە هۆى خەواڵووبوون؟','Avoid driving and check with your doctor','دوورکەوەرەوە لە شۆفێریکردن ڕاوێژ بکە لەگەڵ دکتۆرەکەتدا.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:198',(select id from public.theory_sections where slug = 'hazard-awareness'),18,'When may you use hazard warning lights?','کەى دەتوانیت لایتەکانى ئاگادارکردنەوەى مەترسی بەکاربهینێت؟','When driving on a motorway to warn traffic behind of a hazard ahead','کاتێک لەسەر مۆتۆڕوەی شۆفێری دەکەیت بۆ ئاگادارکرنەوەى ئۆتۆمبێلەکانى دواوەت لە مەترسییەکەی لە پێشەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:199',(select id from public.theory_sections where slug = 'hazard-awareness'),19,'You''re driving on this dual carriageway. Why may you need to slow down?','شۆفێرى دەکەیت لەسەر دەبڵ کاریجوەی (ڕێگای سەرەکی) بۆ چی دەبێت ئۆتۆمبێلەکەت هێواش بکەیتەوە؟','There are roadworks ahead of you','لە پێشەوە کارکردن لەڕێگاکەدا هەیە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:200',(select id from public.theory_sections where slug = 'hazard-awareness'),20,'What does the solid white line at the side of the road indicate?','هێڵە سپییە بێ پچڕانەکە واتای چیە لە قەراغی ڕێگاکە؟','Edge of the carriageway','قەراغی کاریجوەیەکە( ڕێگا سەرەکییەکە.)','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:201',(select id from public.theory_sections where slug = 'hazard-awareness'),21,'What must you do if your ability to drive is impaired during a period of illness?','دەبێت چی بکەیت ئەگەر توانات بۆ شۆفێرى کردن لاواز بوو لە کاتی نەخۆشیدا؟','Stop driving until you''re fit to drive again','بوەستە لە شۆفێرى کردن تاوەکو هەست بەباشی دەکەیت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:202',(select id from public.theory_sections where slug = 'hazard-awareness'),22,'What can you do to help prevent tiredness on a long journey?','دەتوانى چی بکەیت بۆ ڕێگەگرتن لە ماندووبوون لە گەشتێکى دووروودرێژدا؟','Take regular refreshment breaks','ماوە ماوە پشوو وەربگرە .','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:203',(select id from public.theory_sections where slug = 'hazard-awareness'),23,'Why should you slow down as you approach this hazard?','بۆچى تۆ دەبێت ئۆتۆمبێلەکەت هێواش بکەیتەوە کە نزیکدەبیتەوە لەم مەترسییە؟','Because of the level crossing','بەهۆى خاڵى یەکتربڕینى ڕێگاى ئۆتۆمبێل و هێڵى شەمەندەفەرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:204',(select id from public.theory_sections where slug = 'hazard-awareness'),24,'What should the driver of the car approaching the crossing do?','دەبێت ئەو شۆفێری ئۆتۆمبێلەی کە لە شوێنى پەڕینەوەى نزیک دەبێتەوە چی بکات؟','Slow down and get ready to stop','ئۆتۆمبێلەکە هێواش بکەرەوە و ئامادەبە بۆ وەستان.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:205',(select id from public.theory_sections where slug = 'hazard-awareness'),25,'What should you do as you approach this cyclist?','دەبێت چی بکەیت کاتێک نزیک دەبیتەوە لەم پاسکیل سوارە؟','Slow down and allow the cyclist to turn','ئۆتۆمبێلەکەت هێواش بکەرەوەو ڕێگا بە پاسکیل سوارەکە بدە پێچ بکاتەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:206',(select id from public.theory_sections where slug = 'hazard-awareness'),26,'You intend to turn left at the traffic lights. What should you do just before turning?','دەتەوێت پێچ بکەیتەوە بە دەستە چەپدا لەم ترافیک لایتەدا. دەبێت پێش پێچکردنەوە چی بکەیت؟','Check for bicycles on your left','وریایى پاسکیل بە لە دەستە چەپت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:207',(select id from public.theory_sections where slug = 'hazard-awareness'),27,'You want to turn left at this junction. What should you do if your view of the main road is restricted?','دەتەوێ بە دەستە چەپدا پێچ بکەیتەوە لەم ڕێگا یەکتربڕەدا. دەبێت چی بکەیت ئەگەر نەتوانی بەتەواوەتی ڕێگا سەرەکییەکە ببنیت؟','Approach slowly and edge out until you can see more clearly','بە هێواشی نزیک بەرەوە برۆ پێشەوە تاوەکو ڕوونتر بدەبینى.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:208',(select id from public.theory_sections where slug = 'hazard-awareness'),28,'What advice should you give to a driver who has had a few alcoholic drinks at a party?','چ ئامۆژگارییەک دەدەیت بە شۆفێرێک کە هەندێک خواردنەوەى کحولى خواردوەتەوە لە ئاهەنگێکدا؟','Go home by public transport','بگەڕێتەوە ماڵەوە بە گواستنەوە گشتییەکان.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:209',(select id from public.theory_sections where slug = 'hazard-awareness'),29,'What hazard should you be aware of when travelling along this street?','دەبێت وریای چ مەترسییەک بیت کاتێک بە درێژایی ئەم ڕێگەیە شۆفێرى دەکەیت؟','Children running out between vehicles','منداڵان ڕابکەنە دەرەوە لە نێوان ئۆتۆمبێلەکاندا.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:210',(select id from public.theory_sections where slug = 'hazard-awareness'),30,'You''re behind this cyclist. When the traffic lights change, what should you do?','لە دواى ئەم پاسکیل سوارەوەیت . دەبێت چی بکەیت کاتێک گڵۆپی ترافیک لایتەکە دەگۆڕێت؟','Allow the cyclist time and room','کات و بوار بە پاسکیلسوارەکە بدەیت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:211',(select id from public.theory_sections where slug = 'hazard-awareness'),31,'You take some cough medicine given to you by a friend. What should you do before driving your car?','هەندێک دەرمانى کۆکە بەکاردەهێنیت کە لە لایەن هاوڕێیەکەوە پێت دراوە. دەبێت چی بکەیت پێش لێخوڕینى ئۆتۆمبێلەکەت؟','Check the label to see if the medicine will affect your driving','نووسراوى سەر دەرمانەکە بخوێنەرەوە بۆ ئەوەى بزانیت ئایا دەرمانەکە کاریگەرى دەکاتە سەر شۆفێریکردنت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:212',(select id from public.theory_sections where slug = 'hazard-awareness'),32,'Why are place names painted on the road surface?','بۆچى ناوى شوێنەکان لەسەر ڕووى ڕێگاکان دەنەخشێنرێت؟','To help you select the correct lane in good time','بۆ یارمەتیدانت لە هەڵبژاردنى سایدى دروست لە کاتێکى گونجاودا.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:213',(select id from public.theory_sections where slug = 'hazard-awareness'),33,'Do you need to plan rest stops when you''re planning a long journey?','ئایا پێویستت بە پلانی وەستان بۆ پشوو هەیە کاتێک پلانى گەشتێکى درێژ دادەنێت؟','Yes, regular stops help concentration','بەڵێ, ماوە ماوە وەستان بۆ پشوودان یارمەتى تەرکیز کردن دەدات.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:214',(select id from public.theory_sections where slug = 'hazard-awareness'),34,'Which type of glasses would make driving at night more difficult?','کام جۆرى چاویلکە شۆفیری کردن لەشەودا قورستر دەکات؟','Tinted','چاویلکەیەى ڕەنگاو ڕەنگی تاریک.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:215',(select id from public.theory_sections where slug = 'hazard-awareness'),35,'Why must you take great care when emerging from this junction?','بۆ چى پێویستە زۆر وریا بیت کاتێک لەم ڕێگاى یەکتربڕەوە دەردەچیت؟','The view is restricted','مەودای بینین سنووردارە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:216',(select id from public.theory_sections where slug = 'hazard-awareness'),36,'You''re about to drive home. What should you do if you feel very tired and have a severe headache?','بەرەو ماڵەوە شۆفێری دەکەیت. دەبێت چی بکەیت ئەگەر هەستت بە ماندووبوونێکى زۆر کردو سەرئێشەیەکى خراپت گرت؟','Wait until you''re fit and well before driving','چاوەڕێ بکە تاوەکو باش دەبیت و تەندروستیت لەبار دەبێت بۆ شۆفیری کردن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:217',(select id from public.theory_sections where slug = 'hazard-awareness'),37,'What should you do if you become tired while you''re driving on a motorway?','دەبێت چی بکەیت ئەگەر ماندوو بیت لە کاتێکدا لەسەر مۆتۆڕوەی شۆفێری دەکەیت؟','Leave the motorway at the next exit and rest','لە خاڵى دەرچوونى داهاتوو مۆتۆڕوەیەکە بەجێبهێڵە و پشوو بدە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:218',(select id from public.theory_sections where slug = 'hazard-awareness'),38,'What type of vehicle uses an amber flashing beacon on a dual carriageway?','چ جۆرە ئۆتۆمبێلێک گڵۆپی ئاگادارکردنەوەى زەردباو بەکاردەهێنێت لەسەر دەبڵ کاریجوەی (ڕێگای سەرەکی)؟','A tractor','تراکتۆر','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:219',(select id from public.theory_sections where slug = 'hazard-awareness'),39,'What does this signal from a police officer mean to oncoming traffic?','ئەم ئاماژەیەى کارمەندى پۆلیسی هاتووچۆ بە ماناى چی دێت بۆ ئەو ئۆتۆمبێلانەى کە دێن؟','Stop','بوەستە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:220',(select id from public.theory_sections where slug = 'hazard-awareness'),40,'How would age affect an older person''s driving ability?','چۆن تەمەن کاریگەرى لەسەر توانای شۆفێری کردنى کەسێکى بە تەمەن هەیە؟','They''ll take longer to react to hazards','ئەوان کاتێکى زیاتریان پێدەچێت بۆ کاردانەوە لە مەترسییەکان.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:221',(select id from public.theory_sections where slug = 'hazard-awareness'),41,'What should you do if a doctor prescribes drugs that are likely to affect your driving?','دەبێت چی بکەیت ئەگەر دکتۆرێک دەرمانێکت بۆ بنووسێت کە ئەگەری زۆرە کاریگەرى بخاتە سەر شۆفێریکردنەکەت؟','Get someone else to drive','کەسێکى تر بهێنە بۆ شۆفێری کردن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:222',(select id from public.theory_sections where slug = 'hazard-awareness'),42,'Where would you expect to see these markers?','پێشبینى دەکەیت لە کوێ ئەم نیشانانە ببینیت؟','On a large goods vehicle','لەسەر ئۆتۆمبێلێکى بارهەڵگرى گەورە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:223',(select id from public.theory_sections where slug = 'hazard-awareness'),43,'What must you do if poor health affects your driving?','دەبێت چی بکەیت ئەگەر خراپی تەندروستیت کاریگەرى بخاتەسەر شۆفێریکردنت؟','Inform the licensing authority','ئاگادارى فەرمانگەى پێدانى مۆڵەتى شۆفێری بکەرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:224',(select id from public.theory_sections where slug = 'hazard-awareness'),44,'How does drinking alcohol affect your driving behaviour?','چۆن خواردنەوەى کحول کاریگەرى دەخاتە سەر ڕەفتارى شۆفێریکردنت؟','It increases confidence','هەستى متمانەبەخۆبوون زیاتر دەکات.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:225',(select id from public.theory_sections where slug = 'hazard-awareness'),45,'What should you do if you start to feel drowsy while you''re driving on a motorway?','دەبێت چی بکەیت ئەگەر هەستت بە خەواڵووى کرد لە کاتێکدا لەسەر مۆتۆڕوەی شۆفێری دەکەیت؟','Open a window and stop as soon as it''s safe and legal','پەنجەرەیەک بکەرەوە و هەرکاتێک سەلامەت و یاساییە بوەستە .','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:226',(select id from public.theory_sections where slug = 'hazard-awareness'),46,'You''ve just been overtaken by this motorcyclist. What should you do if the rider cuts in sharply?','زۆر نییە تێپەڕێنراوى لە لایەن ئەم ماتۆڕسوارەوە. دەبێت چی بکەیت ئەگەر ماتۆڕسوارەکە لەناکاو هاتە بەردەمت؟','Keep a safe gap','بۆشاییەکى سەلامەتى بهێڵرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:227',(select id from public.theory_sections where slug = 'hazard-awareness'),47,'Which road user has caused a hazard?','کام لەم بەکارهێنەرانەی ڕێگاکە مەترسیان دروست کردووە؟','The parked car (arrowed A)','ئۆتۆمبێلە وەستاوەکە (ئاماژەی بۆ کراوە.)','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:228',(select id from public.theory_sections where slug = 'hazard-awareness'),48,'You''ve been involved in an argument that''s made you feel angry. What should you do before starting your journey?','دەمەقاڵێیەکت کردووە کە توڕەیی کردووی. دەبێت چی بکەیت پێش دەستپێکردنى گەشتەکەت؟','Calm down','هێور بەرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:229',(select id from public.theory_sections where slug = 'hazard-awareness'),49,'What should the driver of the grey car be especially aware of?','شۆفێرى ئۆتۆمبێلە خۆڵەمێشییەکە دەبێت بە تایبەتى وریایی چی بێت؟','Doors opening on parked cars','کردنەوەى دەرگای ئەو ئۆتۆمبێلانەى کە وەستاون.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:230',(select id from public.theory_sections where slug = 'hazard-awareness'),50,'Some two-way roads are divided into three lanes. Why are they particularly dangerous?','هەندێک لە ئەو ڕێگایانەى کە دوو ئاراستەن دابەش دەکرێن بۆ سەر سێ ساید. بۆچى بەتایبەت مەترسیدارن؟','Traffic in both directions can use the middle lane to overtake','ئۆتۆمبێلی هەردوو سایدەکە دەتوانن سایدى ناوەڕاست بەکاربهێنن بۆ تێپەڕاندن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:231',(select id from public.theory_sections where slug = 'hazard-awareness'),51,'What can seriously reduce your ability to concentrate?','چ شتێک دەبێتە هۆى کەمکردنەوەى توانای تەرکیزکردنت؟','Drugs','ماددەى هۆشبەرەکان.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:232',(select id from public.theory_sections where slug = 'hazard-awareness'),52,'You''re on a three-lane motorway. How should you overtake a slow-moving lorry in the middle lane if it''s showing this sign?','لەسەر مۆتۆڕەوەی سێ سایدیت. چۆن دەتوانیت لۆرییەک کە هێواش دەڕوات تێپەڕێنیت لە سایدى ناوەڕاست ئەگەر لەسەرى ئەم هێمایەش پیشاندرابوو؟','Approach with care and overtake on the left of the lorry','بە وریاییەوە لە لۆرییەکە نزیک بەرەوە و لە دەستە چەپەوە تێیپەڕێنە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:233',(select id from public.theory_sections where slug = 'hazard-awareness'),53,'What should you do if the traffic in the left-hand lane is slowing?','دەبێت چی بکەییت ئەگەر ئۆتۆمبێلەکەی سایدى دەستە چەپ هێواشیکردەوە؟','Slow down, keeping a safe separation distance','ئۆتۆمبێلەکەت هێواش بکەرەوە و دووریی سەلامەتی بهێڵەرەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:234',(select id from public.theory_sections where slug = 'hazard-awareness'),54,'Where would it be unsafe to overtake?','لە کوێ سەلامەت نییە تێپەڕاندن ئەنجام بدەیت؟','Approaching a junction','بە نزیک بوونەوە لە ڕێگاى یەکتربڕ.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:235',(select id from public.theory_sections where slug = 'hazard-awareness'),55,'You''re driving a car fitted with automatic transmission. When would you use ''kick down''?','شۆفێرى ئۆتۆمبێلێکی گێڕ ئۆتۆماتیک دەکەیت، کەى پێ لەئەکسلەکە دەنێت؟','To accelerate quickly','بۆ دەرچوون بە خێرایی.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:236',(select id from public.theory_sections where slug = 'hazard-awareness'),56,'What should you do if the red lights start flashing as you approach a level crossing?','تۆ دەبێت چی بکەیت ئەگەر گڵۆپە سوورەکان فلاش بکەن لە کاتی نزیکبوونەوە لە هێڵی شەمەندەفەرەکە؟','Stop before the barrier','بوەستە پێش بەربەستەکە','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:237',(select id from public.theory_sections where slug = 'hazard-awareness'),57,'A driver''s behaviour has upset you. How can you get over this incident safely?','ڕەفتارى شۆفێرێک ناڕەحەتى کردووى. چۆن دەتوانیت ئەم بارودۆخە تێپەڕێنیت بە سەلامەتى؟','Stop and take a break','بوەستە و پشوویەک بدە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:238',(select id from public.theory_sections where slug = 'hazard-awareness'),58,'How can drinking alcohol affect your ability to drive or ride?','خواردنەوەى کحولی چۆن کاریگەرى دەخاتە توانای شۆفیری کردنت یان لێخوڕینى ماتۆڕسکیل؟','Your ability to judge speed will be reduced','توانایی بڕیاردانت بۆ خێرایی کەم دەبێتەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:239',(select id from public.theory_sections where slug = 'hazard-awareness'),59,'What''s the main hazard you should be aware of when following this cyclist?','ئەو مەترسییە سەرەکییە چییە کە دەبێت ئاگادارى بیت لە کاتى شۆفێری کردن لە دواى ئەم پاسکیل سوارەدا؟','The cyclist may swerve into the road','پاسکیل سوارەکە دەکرێت ئاراستەکەى بۆ سەر ڕێگاکە بگۆڕێت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:240',(select id from public.theory_sections where slug = 'hazard-awareness'),60,'You''re driving towards this level crossing. What would be the first warning of an approaching train?','بەرەو ئەم هێڵی ئاسنە شۆفێرى دەکەیت. یەکەمین ئاگادارکردنەوەى شەمەندەفەرێکە چی دەبێت کاتێک نزیک دەبێتەوە؟','A steady amber light','گڵۆپى زەردباوى دادەگیرسێت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:241',(select id from public.theory_sections where slug = 'hazard-awareness'),61,'What should you do if it''s raining and you''re following this lorry on a motorway?','دەبێت چی بکەیت ئەگەر باران ببارێت و لە دواى ئەم لۆرییە لێبخوڕیت لە سەر مۆتۆڕوەی؟','Be aware of spray reducing your vision','ئاگادارى پرژەی باران بە لە کەمکردنەوەى مەودای بینینت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:242',(select id from public.theory_sections where slug = 'hazard-awareness'),62,'You need glasses to read a vehicle number plate at the required distance. When must you wear them?','پێویستیت بە چاویلکەیە بۆ خوێندنەوەى تابلۆى ئۆتۆمبێل لە دوورى داواکراوەوە. کەى دەبێت لەچاوی بکەیت؟','Whenever you''re driving','هەرکاتێک کە شۆفێریت کرد.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:243',(select id from public.theory_sections where slug = 'hazard-awareness'),63,'What type of vehicle could you expect to meet in the middle of the road?','پێشبینى چ جۆرە ئۆتۆمبێلێک دەکەیت ببینیت لە ناوەڕاستى ڕێگاکە؟','Lorry','لۆری','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:244',(select id from public.theory_sections where slug = 'hazard-awareness'),64,'You''re driving on a road with several lanes. What do these signs above the lanes mean?','لەسەر ڕێگایەک کە چەند سایدێکى هەیە شۆفێرى دەکەیت. ئەم هێمایانەى سەرەوەى سایدەکان بە مانای چی دێن؟','The two left lanes are open','دوو سایدەکەى دەستە چەپ کراوەن.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:245',(select id from public.theory_sections where slug = 'hazard-awareness'),65,'What''s the main hazard shown in this picture?','لەم وێنەیەدا مەترسی سەرەکی چییە؟','The cyclist crossing the road','پاسکیل سوارەکە بەڕێگەکەدا دەپەڕێتەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:246',(select id from public.theory_sections where slug = 'hazard-awareness'),66,'What must you do at this junction?','دەبێت چی بکەیت لە ئەم ڕێگا یەکتربڕەدا؟','Stop behind the line, then edge forward to see clearly','لە پشت هێڵەکەوە بوەستە پاشان بڕۆ پێشەوە بۆ ئەوەى بە ڕوونى ببینیت.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:247',(select id from public.theory_sections where slug = 'hazard-awareness'),67,'What might you expect to happen in this situation?','پێشبینى چی دەکەیت ڕووبدات لەم بارودۆخەدا؟','Traffic will move into the left-hand lane','ئوتومبیلەکان دەڕۆنە سەر سایدى دەستە چەپ.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:248',(select id from public.theory_sections where slug = 'hazard-awareness'),68,'When should you use hazard warning lights?','کەى دەبێت لایتەکانى ئاگادارکردنەوەى مەترسی بەکاربهێنیت؟','When your vehicle has broken down and is causing an obstruction','کاتێک ئۆتۆمبێلەکەت پەکى کەوتووە و ڕێگەی گرتووە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:249',(select id from public.theory_sections where slug = 'hazard-awareness'),69,'Why should you be cautious when going past this bus waiting at a bus stop?','بۆچى دەبێت وریا بیت کاتێک کە بە تەنیشت ئەم پاسەدا دەڕۆیت کە لە چاوەڕوانیدایە مۆقیفی پاس (شوێنی وەستانی پاس)؟','People may cross the road in front of it','دەکرێت خەڵکى لە ڕێگاکەی بەردەمیدا بپەڕنەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:250',(select id from public.theory_sections where slug = 'hazard-awareness'),70,'What will be a serious distraction while you''re driving?','چی دەبێتە هۆی سەرلێتێکچوونی جدى لە کاتێکدا کە شۆفیری دەکەیت؟','Looking at road maps','تەماشاکردنى نەخشەکانى ڕێگا.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:251',(select id from public.theory_sections where slug = 'hazard-awareness'),71,'Which type of vehicle should you be ready to give way to as you approach this bridge?','دەبێت ئامادەییت بۆ چ جۆرە ئۆتۆمبێلێک هەبێت کە پێش تۆ بڕوات کاتێک لەم پردە نزیک دەبیتەوە؟','Buses','پاسەکان','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:252',(select id from public.theory_sections where slug = 'hazard-awareness'),72,'You''re waiting to emerge at a junction. Your view is restricted by parked vehicles. What can help you to see traffic on the road you''re joining?','چاوەڕێ دەکەیت بچیتە لە ڕێگایەکى یەکتربڕ. مەودای بینینت سنووردارکراوە لە لایەن ئەو ئۆتۆمبێلانەى کە پارکین کراون. چی یارمەتیت دەدات بۆ بینینی ئۆتۆمبێلەکانی سەر ڕێگاکە کاتێک کە دەچیتە سەرى؟','Reflections of traffic in windows','تیشکدانەوەى ئۆتۆمبێلەکان لەسەر پەنجەرەکان.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:253',(select id from public.theory_sections where slug = 'hazard-awareness'),73,'What should you do as you approach this overhead bridge?','دەبێت چی بکەیت کاتێک نزیک دەبیتەوە لەم بەرزە پردە؟','Be prepared to give way to large vehicles in the middle of the road','ئامادەبە بۆ ئەوەى ڕێگە بە ئۆتۆمبێلە گەورەکان بدەیت لە ناوەڕاستى ڕێگاکە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:254',(select id from public.theory_sections where slug = 'hazard-awareness'),74,'You''re driving on a one-way street. What should you do if you realise you''ve taken the wrong route?','لەسەر شەقامێکى یەک ئاراستە شۆفێری دەکەیت. دەبێت چی بکەیت ئەگەر بۆت دەرکەوت ڕێگایەکى هەڵەت بەکارهێناوە؟','Continue and find another route','بەردەوام بە لە شۆفێری کردن و ڕێگایەکە تر بدۆزیتەوە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:255',(select id from public.theory_sections where slug = 'hazard-awareness'),75,'You''re following a slower-moving vehicle. What should you do if there''s a junction just ahead on the right?','بەدواى ئۆتۆمبێلیکەوەى کە هێواشە لە ڕۆیشتندا. دەبێت چی بکەیت ئەگەر لە پێشەوە ڕێگایەکى یەکتربڕ لە دەستەڕاست هەبوو؟','Only consider overtaking when you''re past the junction','بیر لە تێپەڕاندن بکەرەوە تەنها لە حاڵەتێکدا ئەگەر ڕێگا یەکتربڕەکەت تیپەڕاند.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:256',(select id from public.theory_sections where slug = 'hazard-awareness'),76,'Why should you reduce your speed here?','بۆچی دەبێت خێراییەکەت کەم بکەیتەوە لێرە؟','A staggered junction is ahead','ڕێگایەکى فرە یەکتربڕ لە پێشەوەیە.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:257',(select id from public.theory_sections where slug = 'hazard-awareness'),77,'How should you drive or ride in areas with traffic-calming measures?','چۆن دەبێت شۆفیری ئۆتۆمبێل بکەیت یان ماتۆڕسکیل لێبخوڕیت لەو ناوچانەى ڕێگاکانیان هێماو هێڵکارى لەسەرە؟','At a reduced speed','بە خێراییەکى کەم.','draft','content:uk-theory-questions'),
  ('theory:hazard-awareness:258',(select id from public.theory_sections where slug = 'hazard-awareness'),78,'What will become more expensive after you''ve been convicted of driving while unfit through drink or drugs?','چ شتێک زیاتر گران دەبێت پاش ئەوەى تۆمەتبارکراویت بە خواردنەوەى خواردنەوە کحولییەکان یان بەکارهینانى ماددەى هۆشبەر؟','Insurance premiums','پارەى بیمە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:259',(select id from public.theory_sections where slug = 'vulnerable-road-users'),1,'You see a pedestrian carrying a white stick that also has a red band. What does this mean?','پیادەڕۆیەک دەبینی گۆچانێکى سپی کە شریتى سوورى پێوەیە بە دەستەوە گرتووە. ئەمە بە ماناى چی دێت؟','They''re deaf and blind','ئەوان نابیست و نابینان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:260',(select id from public.theory_sections where slug = 'vulnerable-road-users'),2,'As you approach a pelican crossing, the lights change to green. What should you do if older people are still crossing?','نزیک دەبیتەوە لە شوێنى پەڕینەوەى پیادەڕۆیی زیرەک, گڵۆپەکە دەگۆڕدرێت بۆ سەوز. دەبێت چی بکەیت ئەگەر کەسانى بەساڵاچوو هێشتا لە پەڕینەوەدا بن؟','Wait patiently while they cross','بە ئارامى چاوەڕێ بکە لە کاتێکدا کە دەپەڕنەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:261',(select id from public.theory_sections where slug = 'vulnerable-road-users'),3,'What action should you take when you see flashing amber lights under a school warning sign?','دەبێت چی بکەیت کاتێک دەبینیت گڵۆپی زەرباو فلاش دەکات لە ژێر هێمایەکى ئاگادارکردنەوەى سکوڵدا؟','Reduce speed until you''re clear of the area','خێراییەکە کەم بکەرەوە تاوەکو ناوچەکە چۆڵ دەبێت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:262',(select id from public.theory_sections where slug = 'vulnerable-road-users'),4,'Which sign means that there may be people walking along the road?','کام یەکێک لەم هێمایانە بە ماناى ئەوە دێت کە دەکرێت خەڵک بە درێژایی ڕێگاکە هاتوچۆ بکات؟','D','D','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:263',(select id from public.theory_sections where slug = 'vulnerable-road-users'),5,'Why do motorcyclists use dipped headlights in daylight?','بۆچى ماتۆڕسوارەکان لایتی نزم بەکاردەهێنێنن لە کاتى ڕۆژدا؟','So that the rider can be seen more easily','بۆ ئەوەى ماتۆڕسوارەکە بە ئاسانتر ببینرێت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:264',(select id from public.theory_sections where slug = 'vulnerable-road-users'),6,'Why should you allow extra room while overtaking a motorcyclist on a windy day?','بۆچی ڕێگە دەدەیت بە مەوداى زیاترت لە کاتی تێپەڕاندنی ماتۆڕسوارێک لە ڕۆژێکى بادا؟','The rider may be blown in front of you','دەکرێت ماتۆڕسوارەکە لەبەردەمدا بکەوێت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:265',(select id from public.theory_sections where slug = 'vulnerable-road-users'),7,'What would you do if you see older people crossing the road ahead?','دەبێت چی بکەیت ئەگەر لە پێشەوە خەڵکى بەساڵاچووت بینی لە ڕێگەکە دەپەڕنەوە؟','Be patient and allow them to cross in their own time','ئارام بگەرەو ڕێگەیان بدە بپەڕنەوە لە کاتى خۆیاندا.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:266',(select id from public.theory_sections where slug = 'vulnerable-road-users'),8,'What does this sign mean?','ئەم هێمایە بە ماناى چی دێت؟','With-flow cycle lane','لەگەڵ هەمان ئاراستەى ڕۆیشتنى سایدى پاسکیلەکە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:267',(select id from public.theory_sections where slug = 'vulnerable-road-users'),9,'You''re driving in a slow-moving queue of traffic. What should you do just before changing lane?','شۆفێری دەکەیت لە ئیزدیحامێکدا. دەبێت چی بکەیت پێش گۆڕینى سایدەکە؟','Look for motorcyclists filtering through the traffic','چاوبگێڕە بۆ ماتۆڕسوار و کە لە بەینی ئۆتۆمبێلەکاندا تێدەپەڕن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:268',(select id from public.theory_sections where slug = 'vulnerable-road-users'),10,'What does it mean when a moving vehicle is showing a flashing amber beacon?','ئەوە بە ماناى چی دێت کاتێک کە ئۆتۆمبێلێک لە حاڵەتى ڕۆیشتندا گڵۆپێکى زەردباو دادەگیرسێنێت و دەکوژێنێتەوە؟','The vehicle is slow moving','ئۆتۆمبێلەکە هێواشە لە ڕۆیشتندا.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:269',(select id from public.theory_sections where slug = 'vulnerable-road-users'),11,'You''re turning left from a main road into a side road. What should you do if there''s a pedestrian on the pavement waiting to cross the side road?','بە دەستە چەپدا لادەدەیت لە ڕێگایەکى سەرەکییەوە بۆ سەر ڕێگا لاوەکیەکە. دەبێت چی بکەیت ئەگەر کەسێکى پیادەڕۆ هەبوو لەسەر شۆستەکە چاوەڕێی دەکات لە ڕێگا لاوەکیەکەوە بپەڕێتەوە؟','Wait and give way to the pedestrian','چاوەڕێ بکەو ڕێگە بدە بە کەسە پیادەڕۆکە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:270',(select id from public.theory_sections where slug = 'vulnerable-road-users'),12,'You''ve stopped at a pelican crossing. What should you do if a disabled person is crossing slowly in front of you and the lights change to green?','وەستاوى لە شوێنى پەڕینەوەى پیادەڕۆی زیرەک. دەبێت چی بکەیت ئەگەر کەسێکە خاوەن پێداویستى تایبەت بە هێواشی بپەڕێتەوە لە پێش تۆ وە گڵۆپەکان بگۆڕدرێن بۆ سەوز؟','Wait for them to finish crossing','چاوەڕێیان بکە تاوەکو دەپەڕینەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:271',(select id from public.theory_sections where slug = 'vulnerable-road-users'),13,'Where should you take particular care to look for motorcyclists and cyclists?','لە کوێ دەبێت زیاتر وریا بیت بۆ چاوت لە ماتۆڕسوار و پاسکیل سوارەکان بێت؟','At junctions','لە ڕێگا یەکتربڕەکان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:272',(select id from public.theory_sections where slug = 'vulnerable-road-users'),14,'You''re approaching this roundabout. What should you do when a cyclist is keeping to the left while signalling to turn right?','نزیک دەبیتەوە لەم ڕاوند ئەباوت. دەبێت چی بکەیت کاتێک کە پاسکیل سوارێک لە دەستە چەپ دەمێنێتەوە لە کاتێکدا بە دەستى ئاماژە بۆ لادان بە دەستە ڕاستدا دەکات؟','Allow them space to turn','بواریان بدە بۆ پێچکردنەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:273',(select id from public.theory_sections where slug = 'vulnerable-road-users'),15,'Where would you see this sign?','لە کوێ ئەم هێمایە دەبینیت؟','On the rear of a school bus or coach','لە بەشی دواوەى پاسێکى سکوڵ.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:274',(select id from public.theory_sections where slug = 'vulnerable-road-users'),16,'You''re about to overtake a cyclist on a road that has a 30 mph speed limit. How much room should you leave them as you overtake?','خەریکى پاسکیل سواررێک تێدەپەڕێنیت لەسەر ڕێگایەک خێرای دیاریکراو ٣٠ میلە لە کاتژمێرێکدا. دەبێت بە ئەندازەى چەندێک مەودایان بدەیت هەر کە تێیان دەپەڕێنیت؟','At least as much room as you would if you were overtaking a car','بە لایەنى کەمەوە ئەوەندە مەوداى بۆ بەجێبهێڵى هەروەکو ئەوەى کە لە کاتى تێپەڕاندنى ئۆتۆمبێلێک بەجێیدەهێڵیت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:275',(select id from public.theory_sections where slug = 'vulnerable-road-users'),17,'You''re driving at night. What should you do if you''re dazzled by a vehicle behind you?','لە شەودا شۆفێری دەکەیت. دەبێت چی بکەیت ئەگەر ئۆتۆمبێلیک لە دواوە لایتەکەی بێزاری کردی؟','Set your mirror to the anti-dazzle position','ئاوێنەکە دابەرەوە بۆ ئەوەی لایتەکە بێزارت نەکات.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:276',(select id from public.theory_sections where slug = 'vulnerable-road-users'),18,'You''re driving in town. Why should you be careful if there''s a bus at a bus stop on the other side of the road?','شۆفێری دەکەیت لە شارۆچکەدا. بۆچى دەبێت وریا بیت ئەگەر پاسێک هەبوو لە شوێنى وەستانى پاسدا لەوبەری ڕێگاکە؟','Pedestrians might come from behind the bus','دەکرێت کەسانى پیادەڕۆ لە دواوەى پاسەکەوە دەربچن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:277',(select id from public.theory_sections where slug = 'vulnerable-road-users'),19,'You''ve driven up to a pelican crossing. What must you do while the amber light is flashing?','شۆفێریت کردووە تاوەکو گەیشتوویت بە شوێنى پەڕینەوەى پیادەڕۆی زیرەک پێویستە چی بکەیت لە کاتێکدا کە گڵۆپە زەردباوەکە فلاش دەکات؟','Give way to any pedestrians on the crossing','ڕێگە بدە بە هەر پیادەڕۆیەک لەسەر شوێنى پەڕینەوەکە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:278',(select id from public.theory_sections where slug = 'vulnerable-road-users'),20,'Why is a toucan crossing different from other crossings?','بۆچی شوێنى پەڕینەوەى پیادەڕۆ و پاسیکیلسوار جیاوازە لە پەڕینەوەکانی تر؟','Cyclists can use it','پاسکیل سوارەکان دەتوانن بەکارى بهێنن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:279',(select id from public.theory_sections where slug = 'vulnerable-road-users'),21,'What''s the purpose of these road markings?','مەبەست لە ئەم نیشانەکردنانەى سەر ڕێگا چییە؟','To ensure children can see and be seen when they''re crossing the road','بۆ دڵنیابوونەوە لەوەى منداڵان دەتوانن ببینن و ببینرێن کاتێک لە ڕێگاکە دەپەڕنەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:280',(select id from public.theory_sections where slug = 'vulnerable-road-users'),22,'Who may use toucan crossings?','کێ دەتوانێت شوێنى پەڕینەوەى کەسانى پیادەڕۆو پاسیکیل سوار بەکاربهێنێت؟','Cyclists and pedestrians','پاسکیل سوارەکان و پیادەڕۆکان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:281',(select id from public.theory_sections where slug = 'vulnerable-road-users'),23,'What does this sign mean?','ئەم هێمایە ماناى چی دەگەیەنێت؟','Cycle route ahead','ڕێگاى پاسکیل لە پێشەوەیە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:282',(select id from public.theory_sections where slug = 'vulnerable-road-users'),24,'What should you do if you want to turn left at a junction where pedestrians have started to cross?','دەبێت چی بکەیت ئەگەر بتەوێت پێچ بکەیتەوە بە دەستە چەپدا لە ڕێگایەکى یەکتربڕدا کە کەسانى پیادەڕۆ دەستیان کردووە بە پەڕینەوە لەسەرى؟','Give way to them','ڕێگەیان پێ بدە بپەڕنەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:283',(select id from public.theory_sections where slug = 'vulnerable-road-users'),25,'What does this sign mean?','ئەم هێمایە ماناى چییە؟','A route for pedestrians and cyclists','ڕێگا بۆ کەسانى پیادەڕۆو پاسکیل سوارەکانە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:284',(select id from public.theory_sections where slug = 'vulnerable-road-users'),26,'Why do motorcyclists often look round over their right shoulder just before turning right?','بۆچى ماتۆڕسوارەکان زۆرجار پێش ئەوەى پێچ بکەنەوە بە دەستەڕاستدا سەیرى لای ڕاستیان دەکەن؟','To check for traffic in their blind area','بۆ چێکی هاتووچۆی ئۆتۆمبێلەکان لە ناوچەى کوێریاندا.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:285',(select id from public.theory_sections where slug = 'vulnerable-road-users'),27,'What should you do when you see these horse riders in front?','دەبێت چی بکەیت کاتێک ئەم ئەسپ سوارانە دەبینیت لە پێشەوە؟','Slow down and be ready to stop','ئۆتۆمبێلەکەت هێواش بکەرەوە ئامادە بە بۆ وەستان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:286',(select id from public.theory_sections where slug = 'vulnerable-road-users'),28,'How should you overtake horse riders?','چۆن ئەسپ سوارەکان تێدەپەڕێنیت؟','Drive slowly and leave plenty of room','بە هێواشی شۆفیری بکە مەوداى زۆر بەجێبهێڵە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:287',(select id from public.theory_sections where slug = 'vulnerable-road-users'),29,'You''re driving past a line of parked cars. What should you do if a ball bounces out into the road ahead?','شۆفێری دەکەیت و تێدەپەڕیت بە لای ڕیزێک لە ئۆتۆمبێلى وەستاودا. دەبێت چی بکەیت ئەگەر تۆپێک دەرچوو هاتە سەر ڕێگاکە لە پێشەوە؟','Slow down and be prepared to stop for children','ئۆتۆمبێلەکەت هێواش بکەرەوەو ئامادەبە بۆ وەستان بۆ منداڵەکان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:288',(select id from public.theory_sections where slug = 'vulnerable-road-users'),30,'You want to turn right from a main road into a side road. What should you do just before turning?','دەتەوێت لابدەیت بە دەستە ڕاستدا لە ڕێگایەکى سەرەکییەوە بۆ سەر ڕێگایەکی لاوەکی. دەبێت یەکسەر چی بکەیت پێش لادان؟','Check for traffic overtaking on your right','چاو بگێڕە بۆ ئۆتۆمبێلەکانی کە لە دەستە ڕاستەوە تێپەڕاندن ئەنجام دەدەن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:289',(select id from public.theory_sections where slug = 'vulnerable-road-users'),31,'You''re following a cyclist. What should you do when you wish to turn left a short distance ahead?','بەدواى پاسکیل سوارێک کەوتوویت. دەبێت چی بکەیت کاتێک دەتەوێت لەو مەودا کورتەی پێشەوە پێچ بکەیتەوە بە دەستە چەپدا؟','Hold back until the cyclist has passed the junction','لە دواوە بمێنەرەوە تاوەکو پاسکیل سوارەکە لە یەکتربڕەکە تێدەپەڕێت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:290',(select id from public.theory_sections where slug = 'vulnerable-road-users'),32,'You''re approaching a roundabout. What should you do if a cyclist ahead is signalling to turn right?','لە ڕاوندئەباوتێک نزیک دەبیتەوە. دەبێت چی بکەیت ئەگەر پاسکیل سوارێک لە پێشەوە ئاماژەى دا بۆ پێچ کردنەوە بە لای ڕاستدا؟','Give the cyclist plenty of room','مەوداى زۆر بدە بە پاسکیل سوارەکە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:291',(select id from public.theory_sections where slug = 'vulnerable-road-users'),33,'What does it mean if you see a pedestrian with a dog that has a yellow or burgundy coat?','ئەوە بە ماناى چی دێت ئەگەر تۆ کەسێکى پیادەڕۆت بینی لەگەڵ سەگێک کە بەرگێکى زەرد یان ماڕۆنی لەبەر بوو؟','The pedestrian is deaf','پیادەڕۆکە نابیستە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:292',(select id from public.theory_sections where slug = 'vulnerable-road-users'),34,'Which vehicle should you allow extra room as you overtake them?','دەبێت مەوداى زیاتر بدەیت بە کام هۆکارى گواستنەوە لە کاتێکدا کە تێیان دەپەڕێنیت؟','Bicycle','پاسکیل','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:293',(select id from public.theory_sections where slug = 'vulnerable-road-users'),35,'The road outside this school is marked with yellow zigzag lines. What do these lines mean?','ڕێگاکەى دەرەوەى ئەم سکوڵە بە هێڵى زیگزاگى ڕەنگ زەرد نیشانە کراوە. مەبەست لەم هێڵانە چین؟','You shouldn''t wait or park your vehicle here','نابێت لێرە چاوەڕێ بیت یان ئۆتۆمبێلەکەت بوەستێنیت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:294',(select id from public.theory_sections where slug = 'vulnerable-road-users'),36,'Why do motorcyclists wear bright clothing?','بۆچى ماتۆڕسوارەکان جلی درەوشاوە لەبەردەکەن؟','To make them more visible','وایان لێدەکات زیاتر دیار بن و ببینرێن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:295',(select id from public.theory_sections where slug = 'vulnerable-road-users'),37,'You see a horse rider as you approach a roundabout. What should you do if they''re signalling right but keeping well to the left?','لە ئەسپ سوارێک نزیک دەبیتەوە لە ڕاوند ئەباوتێک. دەبێت چی بکەیت ئەگەر ئەوان ئاماژەیان دا کە بەرەو دەستە ڕاست دەچن بەڵام هەر لە دەستە چەپدا مانەوە؟','Stay well back','بە باشی لە دواوە بمێنەرەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:296',(select id from public.theory_sections where slug = 'vulnerable-road-users'),38,'How will a school crossing patrol signal you to stop?','چۆن کارمەندى دەستەى پەڕاندنەوەى قوتابیانى سکوڵ ئاماژەت بۆ دەکەن بوەستیت؟','By displaying a ''stop'' sign','لە ڕێگەى پیشاندانى هێماى "وەستان".','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:297',(select id from public.theory_sections where slug = 'vulnerable-road-users'),39,'You''re turning right from a main road into a side road. There''s no oncoming traffic. What should you do if pedestrians are standing on the pavement waiting to cross the side road?','لە سەر ڕێگایەکى سەرەکییەوە بە دەستەڕاستدا پێچ دەکەیتەوە بۆ سەر ڕێگایەکی لاوەکی. هیچ یەکێک لە هۆکارەکانى گواستنەوە بەرەوڕووت نایەت. دەبێت چی بکەیت ئەگەر کەسانى پیادەڕۆ لەسەر شۆستەکە وەستابێتن وچاوەڕێ پەڕینەو ەبن لە ڕێگا لاوەکیەکەوە؟','Wait and give way to the pedestrians','چاوەڕێ بکەو ڕێگە بدە بە پیادەڕۆکان بپەڕنەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:298',(select id from public.theory_sections where slug = 'vulnerable-road-users'),40,'What should you do when you''re following a motorcyclist along a road that has a poor surface?','دەبێت چی بکەیت کاتێک لە دواى ماتۆڕسکیلێکەوە بە درێژایی ڕێگایەک چاڵ و چۆلێ تێدایە ڕێ دەکەیت؟','Allow extra room in case they swerve to avoid potholes','مەوداى زیاتر بدە لە حاڵەتێکدا ئەگەر ئەوان بە خێرایی ئاراستەیان گۆڕى بۆ خۆلادان لە چاڵەکانى سەر ڕێگا.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:299',(select id from public.theory_sections where slug = 'vulnerable-road-users'),41,'Powered vehicles used by disabled people are small and can be hard to see. What must they display if they''re travelling on a dual carriageway?','ئوتومبیلی کارەبایی کە لە لایەن کەسانى خاوەن پێداویستى تایبەتەوە بەکاردەهێنرێت، بەهۆی بچوکیانەوە بە زەحەمەت دەبینرێن. ئەوان دەبێت چی پیشان بدەن ئەگەر گەشت بکەن لەسەر دەبڵ کاریجوەی؟','Flashing amber beacon','گڵۆپی زەردباوى ئاگادارکەرەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:300',(select id from public.theory_sections where slug = 'vulnerable-road-users'),42,'Where would you see this sign?','لە کوێ ئەم هێمایە دەبینیت؟','On a school bus','لەسەر پاسی سکوڵ.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:301',(select id from public.theory_sections where slug = 'vulnerable-road-users'),43,'You''re following two cyclists as they approach a roundabout in the left-hand lane. Where would you expect the cyclists to go?','لە دواى دوو پاسکیلسوارەوەیت کە نزیک دەبنەوە لە ڕاوند ئەباوتێک لە سایدى دەستە چەپ. پێشبینى دەکەیت پاسکیلسوارەکان بۆ کوێ بڕۆن؟','Any direction','هەر ئاراستەیەک.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:302',(select id from public.theory_sections where slug = 'vulnerable-road-users'),44,'You want to reverse into a side road. What should you do if you aren''t sure that the area behind your car is clear?','دەتەوێت بە بەگدا ئۆتۆمبێلەکەت ببەیتە سەر ڕێگایەکی لاوەکی. دەبێت چی بکەیت ئەگەر دڵنیا نەبوویت لەوەی دواوەى ئۆتۆمبێلەکەت چۆڵە؟','Get out and check','لە ئۆتۆمبیلەکەت دابەزە و چێکی دەرەوە بکە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:303',(select id from public.theory_sections where slug = 'vulnerable-road-users'),45,'Which road users are most difficult to see when you''re reversing your car?','کام یەکێک لە بەکارهێنەرانى ڕێگا زۆر قورسە ببینرێن کاتێک بەگ دادەنێیت؟','Children','منداڵان','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:304',(select id from public.theory_sections where slug = 'vulnerable-road-users'),46,'How should you react to inexperienced drivers?','چۆن کاردانەوەت دەبێت لەگەڵ ئەو شۆفێرانەى کە ئەزموونیان نییە؟','Be patient and prepare for them to react more slowly','ئارام بگرە و خۆت ئامادە بکە بە هێواشییەکى زیاتر کاردانەوەیان لەگەڵ بنوێنیت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:305',(select id from public.theory_sections where slug = 'vulnerable-road-users'),47,'What should you do when you''re approaching this crossing?','دەبێت چی بکەیت کاتێک کە نزیک دەبیتەوە لە هێڵى پەڕینەوە؟','Prepare to slow down and stop','ئامادە بە بۆ هێواش کردنەوە و وەستان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:306',(select id from public.theory_sections where slug = 'vulnerable-road-users'),48,'Why should you look carefully for motorcyclists and cyclists at junctions?','بۆ دەبێت زۆر بە وریاییەوە چاو بگیڕی بۆ ماتۆڕسوارەکان و پاسکیل سوارەکان لە یەکتربڕدا؟','They''re harder to see','قورسترن بۆ بینین.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:307',(select id from public.theory_sections where slug = 'vulnerable-road-users'),49,'Why should these road markings be kept clear?','بۆچى ئەم نیشانانەى سەر ڕێگا دەبێت بە چۆڵى بمێننەوە؟','To allow children to see and be seen when they''re crossing the road','بۆ ئەوەى ڕێگە بەمنداڵان بدەیت کە ببینن وەهەروەها ببینرێن کاتێک لە ڕیگاکە دەپەڕنەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:308',(select id from public.theory_sections where slug = 'vulnerable-road-users'),50,'What hazard should you be especially aware of if you''re turning left into a side road?','دەبێت بە تایبەتى وریای چ مەترسییەک بیت ئەگەر تۆ پێچ بکەیتەوە بۆ دەستە چەپ بۆ چوونە ناو ڕێگایەکی لاوەکی؟','Pedestrians','کەسانى پیادەڕۆ.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:309',(select id from public.theory_sections where slug = 'vulnerable-road-users'),51,'What should you do when you''re following a learner driver who stalls at a junction?','دەبێت چی بکەیت کاتێک لە دواى شۆفێرێکەوەیت کە لە فێربووندایە و لە ڕێگایەکى یەکتربڕدا وەستاوە؟','Be patient, as you expect them to make mistakes','ئارام بگرە هەروەکو ئەوەى پێشبینى لێ دەکەیت هەڵە بکات.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:310',(select id from public.theory_sections where slug = 'vulnerable-road-users'),52,'You''re on a country road that has no pavement. What should you anticipate finding on your side of the road?','لەسەر ڕێگایەکى دەرەوەى شاریت کە شۆستەى نییە. پێشبینى چی دەکەیت کە بوونى هەبێت لەسەر قەراغی ڕێگاکە؟','Pedestrians','پیادەڕۆکان','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:311',(select id from public.theory_sections where slug = 'vulnerable-road-users'),53,'What should you do when you''re passing loose sheep on the road?','دەبێت چی بکەیت کاتێک بە لای ڕانە مەڕێکدا تێدەپەڕیت کە لەسەر ڕێگاکەن؟','Go very slowly','زۆر بە هێواشی بڕۆ.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:312',(select id from public.theory_sections where slug = 'vulnerable-road-users'),54,'What should you do when you see an older person about to cross the road ahead?','دەبێت چی بکەیت کاتێک کەسێکى بەساڵاچوو دەبینیت خەریکە دەپەڕێتەوە لە پێشەوەی ڕێگاکە؟','Be careful; they may misjudge your speed','وریا بە, دەکرێت ئەوان بە هەڵە هەڵسەنگاندن بۆ خێراییەکەت بکەن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:313',(select id from public.theory_sections where slug = 'vulnerable-road-users'),55,'You''re travelling on a narrow section of road. What should you do if a horse rider ahead is riding in the centre of the lane?','گەشت دەکەیت لەسەر ڕێگایەکی بەرتەسک. دەبێت چی بکەیت ئەگەر ئەسپ سوارێک لە پێشەوە لە ناوەڕاستى سایدەکە ئەسپسوارى دەکرد؟','Stay behind and allow them to ride in this position','لە دواوە بمێنەرەوەو ڕێگەیان پێ بدە لە شوێنی خۆیان ئەسپ سوارى بکەن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:314',(select id from public.theory_sections where slug = 'vulnerable-road-users'),56,'At night, what does it mean if you see a pedestrian wearing reflective clothing and carrying a bright red light?','ئەگەر لە شەودا کەسێکى پیادەڕۆت بینى جلێکى درەوشاوەى لەبەردابوو وە لایتێکى درەوشاوەى سوورى هەڵگرتبوو، ئەوە بە ماناى چی دێت؟','You''re approaching an organised walk','نزیک دەبیتەوە لە ڕێکردنێکى بەکۆمەڵ.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:315',(select id from public.theory_sections where slug = 'vulnerable-road-users'),57,'Which is the most vulnerable road user?','کام لە بەکارهێنەرانى ڕێگا زۆرترین مەترسی ڕووبەڕوو دەبێتەوە؟','Motorcyclist','ماتۆڕسوار','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:316',(select id from public.theory_sections where slug = 'vulnerable-road-users'),58,'You''ve just passed your driving test. How can you reduce your risk of being involved in a collision?','ئەوەندە نییە لە تاقیکردنەوەى شۆفێری دەرچوویت. چۆن دەتوانى مەترسی تووشبوونت بە ڕووداوى بەیەکدادان کەم بکەیتەوە؟','By taking further training','لە ڕێگەى ئەنجامدانى ڕاهێنانى زیاترەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:317',(select id from public.theory_sections where slug = 'vulnerable-road-users'),59,'You''re approaching a roundabout. What should you do if there are horses being ridden in front of you?','نزیک دەبیتەوە لە ڕاوند ئەباوتێک. دەبێت چی بکەیت ئەگەر چەند ئەسپ سوارێک لە پێشتەوە بوون؟','Give them plenty of room','بوارى زۆریان پێ بدە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:318',(select id from public.theory_sections where slug = 'vulnerable-road-users'),60,'You''re driving towards a zebra crossing. What should you do if a person in a wheelchair is waiting to cross?','بەرەو هێڵێکى پەڕینەوەى سەر شەقام شۆفیری دەکەیت. دەبێت چی بکەیت ئەگەر کەسێک کە لەسەر عەرەبانەیە چاوەڕێی دەکات بپەڕێتەوە؟','Be prepared to stop','ئامادە بە بۆ وەستان.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:319',(select id from public.theory_sections where slug = 'vulnerable-road-users'),61,'You''re waiting to come out of a side road. Why should you look carefully for motorcycles?','چاوەڕێ دەکەیت لە قەراغی ڕێگایەکەوە دەربچیت. بۆچی دەبێت بە وریاییەوە چاو بۆ ماتۆڕسکیلەکان بگێڕیت؟','Motorcycles can easily be hidden behind obstructions','دەکرێت ماتۆڕسکیلەکان بە ئاسانى بەهۆی هەر بەربەستێکەوە بێت دەرنەکەون.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:320',(select id from public.theory_sections where slug = 'vulnerable-road-users'),62,'You''re travelling behind a moped. What should you do if you want to turn left a short distance ahead?','گەشت دەکەیت لە پاش ماتۆڕێکى سکۆتەرەوە. دەبێت چی بکەیت ئەگەر بتەوێت لەو مەودا کورتەی پێشەوە بۆ دەستە چەپ پێچ بکەیتەوە؟','Stay behind until the moped has passed the junction','لە دواوە بمێنەرەوە تاوەکو ماتۆڕە سکۆتەرەکە ڕێگا یەکتربڕەکە تێدەپەڕێنێت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:321',(select id from public.theory_sections where slug = 'vulnerable-road-users'),63,'You want to turn right from a junction. What should you do if your view is restricted by parked vehicles?','دەتەوێت لە ڕێگایەکى یەکتربڕەوە بە لای ڕاستدا لابدەیت. دەبێت چی بکەیت ئەگەر مەودای بینینت بەهۆی ئوتومبیلە پارک کراوەکانەوە سنوورداربوو؟','Stop, then move forward slowly until you have a clear view','بوەستەو پاشان بە هێواشی بڕۆ پێشەوە تاوەکو بەباشی دەیبینیت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:322',(select id from public.theory_sections where slug = 'vulnerable-road-users'),64,'This junction, controlled by traffic lights, has a marked area between two stop lines. What''s this for?','ئەم ڕێگا یەکتربڕە بە ترافیک لایت کۆنترۆڵ کراوە و چەند هێمایەکی تێدایە لە نێوان هێڵی وەستانەکاندا. ئەمە بۆچی بەکاردەهێنریت؟','To allow cyclists to position in front of other traffic','بۆ ڕێگەدان بە پاسکیل سوارەکان کە بێنە بەردەمى ئۆتۆمبێلەکانى تر','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:323',(select id from public.theory_sections where slug = 'vulnerable-road-users'),65,'A horse rider is in the left-hand lane approaching a roundabout. Where should you expect the rider to go?','ئەسپ سوارێک لەسەر سایدى دەستە چەپەوە لە ڕاوند ئەباوتێک نزیک دەبێتەوە. پێشبینى دەکەیت ئەسپ سوارەکە بۆ کوێ بڕوات؟','In any direction','بۆ هەر ئاراستەیەک.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:324',(select id from public.theory_sections where slug = 'vulnerable-road-users'),66,'You''re about to overtake a cyclist. Why should you leave them as much room as you would give to a car?','خەریکى پاسکیل سوارێک تێدەپەڕێنیت. بۆچی دەبێت هەمان مەودای کە بۆ ئوتومبیلی جێدە‌هێڵی بۆ ئەویش ئەوەندە مەودا بەجێبهێڵیت؟','The cyclist might be unsettled if you pass too near them','دەکرێت پاسکیل سوارەکە هاوسەنگى تێکبچێت ئەگەر زۆر بە نزیکى بەلایاندا تێپەڕیت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:325',(select id from public.theory_sections where slug = 'vulnerable-road-users'),67,'What should you do if the left-hand pavement is closed due to street repairs?','دەبێت چی بکەیت ئەگەر بەهۆى چاککردنى شەقامەکەوە شۆستەى دەستە چەپ داخرا؟','Watch out for pedestrians walking in the road','ئاگاداری پیادەڕۆکان بە کە لە سەر ڕێگاکە دەڕۆن','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:326',(select id from public.theory_sections where slug = 'vulnerable-road-users'),68,'You''re driving past parked cars. What should you do if you see a bicycle wheel sticking out between the cars?','بە لای ئۆتۆمبێلە پارککراوەکاندا شۆفێری دەکەیت. دەبێت چی بکەیت ئەگەر تایەیەکى پاسکیلت بینی لە نێوان ئۆتۆمبیلەکاندا هاتبوویە دەرەوە؟','Slow down and be prepared to stop for a cyclist','ئۆتۆمبێلەکەت هێواش بکەرەوە و ئامادە بە بۆ پاسکیل سوارەکە بوەستیت.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:327',(select id from public.theory_sections where slug = 'vulnerable-road-users'),69,'Why should you check for motorcyclists just before turning right into a side road?','بۆچی دەبێت چاو بۆ ماتۆڕسوارەکان بگێڕیت پێش پێچکردنەوە بە دەستە ڕاستدا بۆ ڕێگایەکی لاوەکی؟','They may be overtaking on your right','دەکرێت تێپەڕاندن ئەنجام بدەن لە دەستە ڕاستەوە.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:328',(select id from public.theory_sections where slug = 'vulnerable-road-users'),70,'You''re at the front of a queue of traffic waiting to turn right into a side road. Why is it important to check your right mirror just before turning?','لە پێشەوەى ئیزدیحامێکی ئۆتۆمبێلدایت و لە چاوەڕوانیدان بۆ ئەوەى پێچبکەنەوە بە دەستە ڕاستدا بۆ سەر ڕێگای لاوەکی. بۆچی گرنگە تەماشای ئاوێنەى دەستە ڕاستت بکەیت کەمێک پێش پێچکردنەوە؟','To check for overtaking vehicles','بۆ چێکردنی ئەو ئۆتۆمبێلانەى تێپەڕاندن ئەنجام دەدەن.','draft','content:uk-theory-questions'),
  ('theory:vulnerable-road-users:329',(select id from public.theory_sections where slug = 'vulnerable-road-users'),71,'You''re about to reverse into a side road. What should you do if a pedestrian is waiting to cross behind your car?','خەریکى بە ئۆتۆمبێلەکەت بەگ دادەنێیت بۆ سەر ڕێگایەکی لاوەکی. دەبێت چی بکەیت ئەگەر کەسێکى پیادەڕۆ لە دواى ئۆتۆمبێلەکەتەوە چاوەڕێ بکات بپەڕێتەوە؟','Give way to the pedestrian','ڕێگە بە پیادەڕۆکە بدە .','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:330',(select id from public.theory_sections where slug = 'other-vehicles'),1,'You''re following a large vehicle as it approaches a crossroads. What should you do if the driver signals to turn left?','لە دواى ئۆتۆمبێلێکى گەورەوە شۆفێرى دەکەیت کە نزیک دەبێتەوە لە یەکتربڕێک . دەبێت چى بکەیت ئەگەر شۆفێرەکە ئیشارەتی داگیرساند بۆ پێچکردنەوە بۆ لاى چەپ؟','Wait for the vehicle to finish turning','چاوەڕێی ئۆتۆمبێلەکە بکە بۆ ئەوەى پێچبکاتەوە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:331',(select id from public.theory_sections where slug = 'other-vehicles'),2,'You''re driving in heavy traffic on a wet road. Which lights should you use if there''s a lot of surface spray?','لە سەر ڕێگایەکى تەڕ و لە ترافیکێکى زۆر قەرەباڵەغدا شۆفیرى دەکەیت. دەبێت چ جۆرە لایتێک هەڵبکەیت ئەگەر سەر ڕووى ڕێگەکە پرژەی ئاو هەڵبدات؟','Dipped headlights','لایتی نزمی پێشەوە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:332',(select id from public.theory_sections where slug = 'other-vehicles'),3,'What should you do when you''re approaching a bus that''s signalling to move away from a bus stop?','دەبێت چى بکەیت کاتێک نزیک دەبیتەوە لە پاسێک کە گڵۆپی ئیشارەتی هەڵکردووە بۆ ئەوەى بێتەوە ناو شەقامەکەوە لە شوێنى وەستانى پاسەوە؟','Allow it to pull away, if it''s safe to do so','ڕێگەى پێ بدە بڕوات و دووربکەوێتەوە, ئەمەش ئەگەر سەلامەت بێت ئەنجامى بدەیت.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:333',(select id from public.theory_sections where slug = 'other-vehicles'),4,'You''re approaching a mini-roundabout. What should you do if a long vehicle in front signals left but positions over to the right?','نزیک دەبیتەوە لە ڕاوند ئەباوتێکی مینی. دەبێت چى بکەیت ئەگەر بارهەڵگرێکى درێژ لە پێشەوە گڵۆپی ئیشارەتی لای چەپ داگیرسێنێت بەڵام بەرەو لاى دەستە ڕاست دەجوڵێت؟','Keep well back','لە دواوە بمێنەرەوە','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:334',(select id from public.theory_sections where slug = 'other-vehicles'),5,'Why should drivers be more careful on roads where trams also operate?','بۆچى دەبێت شۆفێرەکان زیاتر وریابن لە سەر ئەو ڕێگایانەى کە سیستەمى گواستنەوەى ترامى لەسەرە؟','Because trams can''t steer to avoid obstructions','چونکە ترامەکان ناتوانن ئاراستەى خۆیان بگۆڕن بۆ خۆلادان لە بەربەستەکان.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:335',(select id from public.theory_sections where slug = 'other-vehicles'),6,'You''re following a long vehicle as it approaches a crossroads. What should you do if it signals left but moves out to the right?','لە دواى بارهەڵگرێکى درێژەوە کە نزیک دەبێتەوە لە ڕێگەیەکى یەکتربڕ شۆفێرى دەکەیت. دەبێت چى بکەیت ئەگەر بارهەڵگرەکە ئیشارەتی دەستەچەپی داگیرساند بەڵام بەرەو لاى دەستە ڕاست جوڵەى کرد.','Stay well back and give it room','بەباشی لە دواوە بمێنەرەوە و ڕێگەى پێ بدە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:336',(select id from public.theory_sections where slug = 'other-vehicles'),7,'What should you do if there''s a bus at a bus stop ahead of you?','دەبێت چى بکەیت ئەگەر پاسێک لە شوێنى وەستانى پاسدا لە پێشتەوە هەبوو؟','Watch carefully for the sudden appearance of pedestrians','بە ووریاییەوە سەیرى دەرکەوتنى لەناکاوى پیادەڕەو بکەیت.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:337',(select id from public.theory_sections where slug = 'other-vehicles'),8,'You''re leaving a safe gap as you follow a large vehicle. What should you do if a car moves into this gap?','بۆشایییەکى سەلامەت بەجێدەهێڵى لەو کاتەى دواى ئۆتۆمبێلێکى گەورە دەکەویت. دەبێت چى بکەیت ئەگەر ئۆتۆمبیلێک بێتە ناو ئەم بۆشایییەوە؟','Drop back further','زیاتر بگەڕێیتە دواوە .','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:338',(select id from public.theory_sections where slug = 'other-vehicles'),9,'You''re about to overtake a slow-moving motorcyclist. Which sign would make you take special care?','خەریکى ماتۆڕسکیلێک کە هێواش لێدەخوڕێت تێدەپەڕێنیت. کام لە ئەم نیشانانە وات لێدەکەن وریاتر بیت؟','A','A','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:339',(select id from public.theory_sections where slug = 'other-vehicles'),10,'What should you be prepared to do in this situation?','لەم بارودۆخەدا دەبێت ئامادەی چى بیت ئەنجامی بدەیت ؟','Slow down and give way','ئۆتۆمبێلەکەت هێواش بکەرەوە و ڕێگە بدە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:340',(select id from public.theory_sections where slug = 'other-vehicles'),11,'What should you do if you want to overtake a long, slow-moving vehicle on a busy road?','دەبێت چى بکەیت ئەگەر بتەوێت ئۆتۆمبێلێکى بارهەڵگرى درێژى هێواش لە ڕۆیشتندا تێپەڕێنیت لەسەر ڕێگەیەکى قەرەباڵەغ؟','Keep well back so that you get a good view of the road ahead','بە شێوەیەکى گونجاو لە دواوە بمێنەرەوە بۆ ئەوەى باش ڕێگەکەى پێشەوەت لێوەدیار بێت.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:341',(select id from public.theory_sections where slug = 'other-vehicles'),12,'You''re following a lorry on a wet road. What should you do when spray makes it difficult to see the road ahead?','لە دواى لۆرییەکەوە لەسەر ڕێگەیەکى تەڕ شۆفێرى دەکەیت. دەبێت چى بکەیت لە کاتێکدا پرژەی ئاوی لۆرییەکە ناهێڵێت باش ڕێگاکەى پێشەوە ببینى؟','Drop back until you can see better','ئۆتۆمبێلەکەت هێواش بکەرەوە تاوەکو بتوانیت باشتر ببینیت.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:342',(select id from public.theory_sections where slug = 'other-vehicles'),13,'You''re travelling behind a bus. What should you do if it pulls up at a bus stop?','لە دوای پاسێکەوە شۆفێرى دەکەیت. دەبێت چى بکەیت ئەگەر پاسەکە لە وێستگەیەک وەستا ؟','Look for pedestrians','چاوبگێڕە بۆ پیادەڕەو.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:343',(select id from public.theory_sections where slug = 'other-vehicles'),14,'You''re towing a caravan. Which is the safest type of rear-view mirror to use?','کەرەڤانەیەک ڕادەکێشیت. چ ئاوێنەیەکی بینینی دواوە سەلامەترینە سەیری بکەیت؟','Extended-arm side mirrors','ئاوێنەی بەستراوی لاکان.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:344',(select id from public.theory_sections where slug = 'other-vehicles'),15,'It''s very windy. What should you do if you''re behind a motorcyclist who''s overtaking a high-sided vehicle?','لەکەشێکدا کە بای هەیە. دەبێت چى بکەیت ئەگەر لەپاش ماتۆڕسکیلێکەوە شۆفێرى بکەیت لە کاتێکدا ماتۆڕسکیلەکە ئۆتۆمبێلێکى بەرز تێدەپەرێنێت؟','Keep well back','بە شێوەیەکى گونجاو لە دواوە','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:345',(select id from public.theory_sections where slug = 'other-vehicles'),16,'What should you do if you overtake a cyclist when it''s very windy?','دەبێت چى بکەیت ئەگەر پاسکیلسوارێک تێپەڕێنیت لە کاتێکدا بایەکى زۆر توند هەیە؟','Allow extra room','مەجالێکى زیاتر بدە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:346',(select id from public.theory_sections where slug = 'other-vehicles'),17,'You''re driving on a single carriageway road. Why should you keep well back while you''re following a large vehicle?','لەسەر شەقامێکى یەک ئاراستە شۆفێرى دەکەیت. بۆچى دەبێت بە شێوەیەکى گونجاو لە دواوە بمێنیتەوە لە کاتێکدا لە دواى ئۆتۆمبێلێکى گەورە دەکەویت؟','To get the best view of the road ahead','بۆ بەدەست هێنانى باشترین مەودای بینینى ڕێگاکەی پێشەوە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:347',(select id from public.theory_sections where slug = 'other-vehicles'),18,'You''re waiting to turn right out of a minor road. It''s clear to the left but a lorry is coming from the right. Why should you wait, even if you have enough time to turn?','لە چاوەڕوانیدایت بۆ ئەوەى لەسەر ڕێگایەکى لاوەکی بەدەستە ڕاستدا پێچ بکەیتەوە. لە لای دەستە چەپەوە هیچ ئۆتۆمبێلێک نیە بەڵام لۆرییەک لە لای دەستە ڕاستەوە دێت. بۆ چى دەبێت چاوەڕوان بیت سەرەڕاى ئەوەى کە کاتى تەواوت هەیە بۆ پێچکردنەوە؟','Anything overtaking the lorry will be hidden from view','هەرشتێک کە لۆرییەکە تێپەڕێنێت ناتوانی بیبینیت.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:348',(select id from public.theory_sections where slug = 'other-vehicles'),19,'You''re following a long vehicle approaching a crossroads. What should you do if the driver signals right but moves close to the left-hand kerb?','لە دوای ئۆتۆمبێلێکى درێژەوە کە نزیک دەبێتەوە لە ڕێگایەکى یەکتربڕ شۆفێرى دەکەیت. دەبێت چى بکەیت ئەگەر شۆفێرەکە گڵۆپى ئیشارەتی دەستە ڕاستی داگیرساند بەڵام لە لێوارى شۆستەى دەستە چەپ نزیک کەوتەوە ؟','Wait behind the long vehicle','چاوەڕێ بکە لە دواى ئۆتۆمبێلە درێژەکەوە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:349',(select id from public.theory_sections where slug = 'other-vehicles'),20,'What should you do as you approach this lorry?','دەبێت چى بکەیت کاتێک نزیک دەبیتەوە لەم بارهەڵگرە؟','Slow down and be prepared to wait','ئۆتۆمبێلەکەت هێواش بکەرەوە و ئامادە بە بۆ چاوەڕوانى کردن.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:350',(select id from public.theory_sections where slug = 'other-vehicles'),21,'Why is it more difficult to overtake a large vehicle than a car?','بۆچى قورس ترە ئۆتۆمبێلێکى گەورە تێپەڕێنى بە بەروارد لەگەڵ ئۆتۆمبێلێکى بچووک؟','It will take longer to overtake a large vehicle','تێپەڕاندنى ئۆتۆمبێلێکى گەورە کاتێکى زیاترى پێویستە.','draft','content:uk-theory-questions'),
  ('theory:other-vehicles:351',(select id from public.theory_sections where slug = 'other-vehicles'),22,'Which vehicles are least likely to be affected by side wind?','کام ئۆتۆمبێل هەڵکردنى بای کەمتر کاریگەری لەسەری دەبێت؟','Cars','ئۆتۆمبێلە بچووکەکان.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:352',(select id from public.theory_sections where slug = 'vehicle-handling'),1,'What should you do when you''re overtaking at night?','دەبێت چی بکەیت کاتێک لە شەودا تێپەڕاندن ئەنجام دەدەیت؟','Beware of bends in the road ahead','ئاگادارى ڕێگا چەمانەوەکانى پێشەوە بە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:353',(select id from public.theory_sections where slug = 'vehicle-handling'),2,'What will happen if you use rear fog lights in good conditions?','چى ڕوودەدات ئەگەر لایتى تەمى دواوە بەکاربهێنى لە کەش و هەوایەکى خۆشدا؟','They''ll dazzle other drivers','سەر لە شۆفێرەکانى تر تێکدەدات.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:354',(select id from public.theory_sections where slug = 'vehicle-handling'),3,'You''re driving on the motorway in windy conditions. What should you do as you overtake a high-sided vehicle?','لەسەر مۆتۆڕوەی و لە کەشێکی بادا شۆفێرى دەکەیت. دەبێت چی بکەیت لە کاتێکدا ئۆتۆمبێلێکى بەرز تێدەپەڕێنیت؟','Be wary of a sudden gust','ئاگادارى ڕەشەبای لەناکاو بە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:355',(select id from public.theory_sections where slug = 'vehicle-handling'),4,'You''re driving in fog. Why should you keep well back from the vehicle in front?','لە کەشێکی تەماویدا شۆفێرى دەکەیت. بۆچى دەبێت بە باشى خۆت لە ئۆتۆمبێلەکەى پێشەوەت بپارێزیت؟','In case it stops suddenly','لە حاڵەتێکدا ئەگەر ئۆتۆمبێلەکە لەناکاو وەستا.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:356',(select id from public.theory_sections where slug = 'vehicle-handling'),5,'What will happen to your car when you drive up a steep hill?','چى بەسەر ئۆتۆمبێلەکەتدا دێت کاتێک بەسەر گردێکى بەرزدا شۆفێرى دەکەیت ؟','The engine will work harder','بزوێنەرەکە قورستر کاردەکات.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:357',(select id from public.theory_sections where slug = 'vehicle-handling'),6,'When must you use dipped headlights during the day?','پێویستە چ کاتێکی ڕۆژ لایتی نزم بەکاربهێنی؟','When you''re driving in poor visibility','کاتێک لە کەشێکدا شۆفێرى دەکەیت کە توانای بینینت کەمە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:358',(select id from public.theory_sections where slug = 'vehicle-handling'),7,'What will affect your vehicle''s stopping distance?','چی کاریگەرى دەکاتە سەر مەوداى ئیستۆپ گرتنى ئۆتۆمبێلەکەت؟','The condition of the tyres','بارودۆخى تایەکان.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:359',(select id from public.theory_sections where slug = 'vehicle-handling'),8,'Why should you reduce your speed when you''re driving or riding in fog?','بۆچى دەبێت خێراییەکەت کەم بکەیتەوە کاتێک لە کەشێکی تەمومژاویدا شۆفیرى ئۆتۆمبێل دەکەیت یاخود ماتۆڕسکیل لێدەخوڕیت ؟','It''s more difficult to see what''s ahead','بینینى پێشەوەی ڕێگاکە قورسترە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:360',(select id from public.theory_sections where slug = 'vehicle-handling'),9,'Which plate may appear with this road sign?','لەگەڵ ئەم هێمایەى هاتووچۆدا دەکرێت کام لەم پلێتانە لەگەڵیدا ببینرێت؟','B','B','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:361',(select id from public.theory_sections where slug = 'vehicle-handling'),10,'The road is wet. Why would a motorcyclist steer around drain covers while they were cornering?','ڕێگاکە تەڕە. بۆچى ماتۆڕسوارەکان خۆیان لە سەرە مەنهۆڵەکان لادەدەن لەڕێگا چەماوەکاندا؟','To prevent the motorcycle sliding on the metal drain covers','بۆ ڕێگریکردن لە خلیسکانی ماتۆڕسکیلەکە لەسەر سەرەمەنهۆڵەکە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:362',(select id from public.theory_sections where slug = 'vehicle-handling'),11,'What will happen if you hold the clutch pedal down or roll in neutral for too long?','چى ڕوودەدات ئەگەر بۆ ماوەیەکى زۆر پێ بخەیتەسەر کلاچەکە یان گێڕەکە بکەیتە بۆش ؟','It will reduce your control','کۆنترۆڵت کەم دەکاتەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:363',(select id from public.theory_sections where slug = 'vehicle-handling'),12,'When may you overtake another vehicle on their left?','کەى دەکرێت ئۆتۆمبێلێکى تر تێپەڕێنیت لە دەستە چەپییەوە؟','When you''re in a one-way street','کاتێک لە شەقامێکى یەک ئاراستەى.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:364',(select id from public.theory_sections where slug = 'vehicle-handling'),13,'When may you wait in a box junction?','کەى دەکرێت لە بۆکسی چوارگۆشەی یەکتربڕدا چاوەڕوان بکەیت ؟','When oncoming traffic prevents you turning right','کاتێک ئەو ئۆتۆمبێلانەى ڕووبەڕووت دێن ناهێڵن بە دەستەڕاستدا پێچ بکەیتەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:365',(select id from public.theory_sections where slug = 'vehicle-handling'),14,'You''re driving on an icy road. What distance from the car in front should you drive?','لەسەر ڕێگایەکى سەهۆڵین شۆفیرى دەکەیت. بە مەوداى چ دوورییەک لە ئۆتۆمبێلەکەى پێشەوە دەبێت شۆفیرى بکەیت؟','Ten times the normal distance','دە جار زیاتر لە مەوداى دوورى ئاسایی.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:366',(select id from public.theory_sections where slug = 'vehicle-handling'),15,'Why is it bad technique to coast when you''re driving downhill?','بۆچى تەکنیکێکى خراپە کە لە گردێک دەڕۆیتە خوارەوە ئوتومبیلەکە بکەیەتە بۆش ؟','The vehicle will gain speed more quickly','ئۆتۆمبێلەکە زووتر خێرایی زیاد دەکات.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:367',(select id from public.theory_sections where slug = 'vehicle-handling'),16,'What should you do if you park on the road when it''s foggy?','دەبێت چی بکەیت ئەگەر ئۆتۆمبیلەکەت لەسەر ڕێگایەک پارک کرد و کەش و هەواش تەماوى بوو؟','Leave parking lights switched on','گڵۆپى پارکین بە داگیرساوى بهێڵەرەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:368',(select id from public.theory_sections where slug = 'vehicle-handling'),17,'What should you do when you meet an oncoming vehicle on a single-track road?','دەبێت چی بکەیت كاتێک بەرەو ڕووی ئۆتۆمبێلی سایدی بەرامبەر دەبیتەوە لەسەر ڕێگایەکى یەک ساید؟','Stop at a passing place','لە شوێنی تێپەڕاندن بوەستە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:369',(select id from public.theory_sections where slug = 'vehicle-handling'),18,'Why would you fit chains to your wheels?','بۆچى دەبێت زنجیر لە تایەى ئۆتۆمبێلەکەت ببەستی ؟','To help prevent skidding in deep snow','بۆ ڕێگەگرتن لە خلیسکان لە بەفرى زۆردا.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:370',(select id from public.theory_sections where slug = 'vehicle-handling'),19,'Why is it dangerous to leave rear fog lights switched on after the fog has cleared?','بۆچى مەترسیدارە لایەتى تەمى دواوە بە داگیرساوى بەجێبهێڵى پاش ئەوەى تەمەکە نەما؟','They may be confused with brake lights','دەکرێت بە هەڵە وابزانرێت کە لایتى برێکە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:371',(select id from public.theory_sections where slug = 'vehicle-handling'),20,'Why could it be dangerous to keep the clutch down, or select neutral, for long periods of time while you''re driving?','بۆچى مەترسیدارە بۆماوەیەکی زۆر پێ لەسەر کلاج دانێت یاخود گێڕەکە لە بۆش بێت لە کاتێکدا شۆفێرى دەکەیت؟','You''ll have less steering and braking control','کەمتر کۆنترۆڵی سوکان و برێک دەکەیت.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:372',(select id from public.theory_sections where slug = 'vehicle-handling'),21,'You''re travelling in very heavy rain. How is this likely to affect your overall stopping distance?','لە کەشێکی بارانی بەلێزمەدا گەشت دەکەیت. ئەمە چۆن کاریگەرى دەکاتە سەر مەوداى ئیستۆپ گرتننەکەت؟','It will be doubled','دەبێت بە دووهێندە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:373',(select id from public.theory_sections where slug = 'vehicle-handling'),22,'Why should you test your brakes after this hazard?','بۆچى دەبێت برێکەکانت تێست بکەیت پاش ئەوەی ئەم هێماى مەترسییەت بینینى ؟','Your brakes will be wet','برێکەکانت تەڕ دەبن.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:374',(select id from public.theory_sections where slug = 'vehicle-handling'),23,'What''s the reason for traffic-calming measures?','هۆکارى بەکارهێنانى هێماو و هێڵەکانی هێواش کردنەوە چییە؟','To slow traffic down','بۆ هێواش کردنەوەى هاتووچۆى ئۆتۆمبێلەکان.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:375',(select id from public.theory_sections where slug = 'vehicle-handling'),24,'What''s the purpose of the yellow lines painted across the road?','مەبەست لە هێڵە زەردە کێشراوەکانى سەر ڕێگاکە چییە؟','To make you aware of your speed','بۆ ئەوەى ئاگادارى خێراییەکەت بیت.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:376',(select id from public.theory_sections where slug = 'vehicle-handling'),25,'You''ve been driving in fog. What must you do when the visibility improves?','لە کەشێکی تەماویدا شۆفێریت کردووە. دەبێت چی بکەیت کاتێک مەوداى بینین باشتر دەبێت؟','Switch off your fog lights','کوژاندنەوەى لایتەکانى تەم.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:377',(select id from public.theory_sections where slug = 'vehicle-handling'),26,'What should you do if you have to make a journey in foggy conditions?','دەبێت چی بکەیت ئەگەر پێویستى کرد لە کەشێکی تەماویدا گەشتێک بکەیت؟','Leave plenty of time for your journey','کاتێکى زۆر بۆ گەشتەکەت دابنێ.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:378',(select id from public.theory_sections where slug = 'vehicle-handling'),27,'Which lights must you use if you''re driving on a well-lit motorway at night?','کام یەکێک لە لایتەکان دەبێت بەکاربهێنیت ئەگەر لەسەر مۆتۆڕوەیەک کە بە باشى ڕووناک کرابێتەوە لە شەودا شۆفێرى بکەیت ؟','Use your headlights','لایتى پێشەوەى بەکاربهێنە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:379',(select id from public.theory_sections where slug = 'vehicle-handling'),28,'What''s a rumble device designed to do?','ئامێری ڕەمبڵ(ئامێری ئاگادارکردنەوە) بۆچى دیزاین کراوە؟','Alert you to a hazard','ئاگادارکردنەوە لە مەترسی.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:380',(select id from public.theory_sections where slug = 'vehicle-handling'),29,'What should you check before you start a journey in foggy weather?','دەبێت چێکی چی بکەیت پێش ئەوەى گەشتێک دەست پێبکەیت لە کەشێکی تەماویدا؟','The windows and lights are clean and clear','پەنجەرەکان و لایتەکان پاک و ڕوونن','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:381',(select id from public.theory_sections where slug = 'vehicle-handling'),30,'What should you do when dealing with this hazard?','دەبێت چی بکەیت کاتێک مامەڵە لەگەڵ ئەم هێماى مەترسییە دەکەیت؟','Use a low gear and drive slowly','گێڕێکى نزم بەکاربهێنەو بە هێواشی شۆفێرى بکە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:382',(select id from public.theory_sections where slug = 'vehicle-handling'),31,'When will you feel the effects of engine braking?','کەى هەست بە پەککەوتنى بزوێنەر دەکەیت؟','When you change to a lower gear','کاتێک گێڕەکە دەگۆڕیت بۆ گێڕێکى نزمتر.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:383',(select id from public.theory_sections where slug = 'vehicle-handling'),32,'What colour are the reflective studs along the left-hand edge of the motorway?','بەردی فسفۆڕی جیاکەرەوەی ڕێگا چ رەنگێکن لە سایدی دەستە چەپی مۆتۆڕوەی؟','Red','سوور','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:384',(select id from public.theory_sections where slug = 'vehicle-handling'),33,'You''re travelling on a road that has road humps. What should you do when the driver in front is travelling more slowly than you?','لەسەر ڕێگایەک کە تاسەى تێدایە گەشت دەکەیت. دەبێت چی بکەیت کاتێک شۆفێرەکەی بەردەمت لە تۆ هێواش تر لێدەخوڕیت؟','Slow down and stay behind','ئۆتۆمبێلەکە هێواش بکەرەوەو لە دواوە بمێنەرەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:385',(select id from public.theory_sections where slug = 'vehicle-handling'),34,'Why is travelling in neutral for long distances (known as coasting) bad driving technique?','بۆچى گەشتکردن بە ئۆتۆمبێلەکەت لە گێڕی بۆش کە (ناسراوە بە ڕۆیشتن بە بێ بەکارهێنانى هێزى بزوێنەر) بۆ ماوەیەکی زۆر بە تەکنیکێکى خراپی شۆفێری کردن لە قەڵەم دەدرێت؟','There won''t be any engine braking','بزوێنەرەکە برێک ناگرێت.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:386',(select id from public.theory_sections where slug = 'vehicle-handling'),35,'You''re driving on a motorway at night. Which lights should you have on if there are other vehicles just ahead of you?','لەسەر مۆتۆڕوەی لە شەودا شۆفێرى دەکەیت. دەبێت چ لایتێک دابگیرسێنیت ئەگەر ئۆتۆمبێلى تر لە پێشتەوە هەبوو؟','Dipped headlights','لایتی نزمى پێشەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:387',(select id from public.theory_sections where slug = 'vehicle-handling'),36,'Why should you switch off your rear fog lights when the fog has cleared?','بۆچى دەبێت لایتى تەمى دواوە بکوژێنیتەوە کاتێک کە تەمەکە نەما؟','To prevent dazzling drivers behind','بۆ ڕێگریکردن لە سەرلێشێواندنى شۆفێرەکانى دواوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:388',(select id from public.theory_sections where slug = 'vehicle-handling'),37,'Why are vehicles fitted with rear fog lights?','بۆچى لایتى تەم بۆ دواوەى ئۆتۆمبێلەکان دادەنرێت؟','To make them more visible in thick fog','بۆ ئەوەى لە ئۆتۆمبێلەکان زیاتر دیاربن لە کاتى کەشى تەمى زۆردا.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:389',(select id from public.theory_sections where slug = 'vehicle-handling'),38,'There''s been a heavy fall of snow. What should you consider before driving in these conditions?','بەفرێکى زۆر باریوە. دەبێت ڕەچاوى چی بکەیت پێش شۆفێری کردن لەم بارودۆخانەدا؟','Whether your journey is essential','گەشتەکەت گرنگە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:390',(select id from public.theory_sections where slug = 'vehicle-handling'),39,'How can you use your vehicle''s engine to control your speed?','چۆن دەتوانیت بزوێنەرەى ئۆتۆمبێلەکەت بەکاربهێنى بۆ کۆنترۆڵکردنى خێرایەکەت؟','By changing to a lower gear','لە ڕێگەى گۆڕینى گێڕەکەت بۆ گێڕێکى نزم.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:391',(select id from public.theory_sections where slug = 'vehicle-handling'),40,'You''re driving with your front fog lights switched on. What should you do if the fog has cleared?','شۆفیرى دەکەیت وە لایتى تەمى پێشەوەت داگیرساوە. دەبێت چی بکەیت ئەگەر تەمەکە نەمێنێت و کەش و هەوا ئاسایی بێتەوە؟','Switch them off as long as visibility remains good','تاوەکو مەوداى بینین بە باشى دەمێنێتەوە بیانکوژێنەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:392',(select id from public.theory_sections where slug = 'vehicle-handling'),41,'Which lights should you switch on when daytime visibility is poor but not seriously reduced?','دەبێت کام لە لایتەکان دابگیرسێنیت کاتێک ڕۆژە بەڵام مەوداى بینین لاوازە.','Dipped headlights','لایتی نزمى پێشەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:393',(select id from public.theory_sections where slug = 'vehicle-handling'),42,'When may front fog lights be used?','کەى دەکرێت لایتى تەمى پێشەوە بەکاربهێنرێت؟','When visibility is seriously reduced','کاتێک مەوداى بینین بەشێوەیەکى زۆر کەم دەبێتەوە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:394',(select id from public.theory_sections where slug = 'vehicle-handling'),43,'You''re driving at night. What should you do if you''re dazzled by headlights coming towards you?','لە شەودا شۆفێرى دەکەیت. دەبێت چی بکەیت ئەگەر لایتى پێشەوەى ئەو ئۆتۆمبێلانەى کە بەرەوڕووت دێن نەهێڵن پێشەوەی خۆت ببینیت؟','Slow down or stop','هێواشی بکەرەوە یاخود بوەستە.','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:395',(select id from public.theory_sections where slug = 'vehicle-handling'),44,'What must you do when you''re overtaking a car at night?','دەبێت چی بکەیت کاتێک ئۆتۆمبێلێک تێدەپەڕینیت لە شەودا؟','Make sure you don''t dazzle other road users','دڵنیابەرەوە لەوەى سەر لە بە کارهێنەرانى ترى ڕێگەکە ناشێوێنیت.(شەوارەیان ناکەیت)','draft','content:uk-theory-questions'),
  ('theory:vehicle-handling:396',(select id from public.theory_sections where slug = 'vehicle-handling'),45,'It''s very windy. What should you do if you''re behind a motorcyclist who''s overtaking a high-sided vehicle?','لەکەشێکدا کە بای هەیە. دەبێت چى بکەیت ئەگەر لەپاش ماتۆڕسکیلێکەوە شۆفێرى بکەیت لە کاتێکدا ماتۆڕسکیلەکە ئۆتۆمبێلێکى بەرز تێدەپەرێنێت؟','Keep well back','بە شێوەیەکى گونجاو لە دواوە بمێنەرەوە','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:397',(select id from public.theory_sections where slug = 'motorway-rules'),1,'What would you expect to find at a contraflow system on a motorway?','پێشبینى دەکەیت لە سیستمى هاتووچۆى ئاراستەى پێچەوانە چی بدۆزیتەوە ( چی ببینیت )کە دادەنرێت لەسەر مۆتۆروەیەک؟','Lower speed limits','ڕێگەپێدانى خێرایی کەم.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:398',(select id from public.theory_sections where slug = 'motorway-rules'),2,'What helps to reduce traffic bunching on a motorway?','چی یارمەتى کەمکردنەوەى قەرەباڵەغى هاتووچۆى ئۆتۆمبێلەکان دەدات لە سەر مۆتۆروەییەک؟','Variable speed limits','دانانی خێرایی جیاواز.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:399',(select id from public.theory_sections where slug = 'motorway-rules'),3,'How should you position yourself when you use the emergency telephone on a motorway?','دەبێت چۆن بوەستى کاتێک تەلەفونى ئێمەرجنسی بەکاردەهێنیت لەسەر مۆتۆروەییەک؟','Face the oncoming traffic','ڕووت لەو ئۆتۆمبێلانە بێت کە ڕووبەڕووت دێن.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:400',(select id from public.theory_sections where slug = 'motorway-rules'),4,'Your vehicle breaks down on a motorway and you manage to stop on the hard shoulder. What should you do if you use your mobile phone to call for help?','ئۆتۆمبێلەکەت لەسەر مۆتۆروەیەک پەکى کەوتووە وە تۆ توانیوتە بیوەستێنى لە ناوچەی هاردشۆڵدەری لەسەر مۆتۆڕوەی. دەبێت چی بکەیت ئەگەر تۆ مۆبایلەکەت بەکاربهێنى بۆ داواکردنى یارمەتى؟','Check your location from the nearest marker posts beside the hard shoulder','چێکی شوێنەکەت بکە لە نزیکترین ستوونى هێماکانەوە لە تەنیشت ناوچەی هاردشۆڵدەری.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:401',(select id from public.theory_sections where slug = 'motorway-rules'),5,'How should you use the lanes on a motorway?','دەبێت چۆن سایدەکان لەسەر مۆتۆروەی بەکاربهێنیت ؟','Keep to the left-hand lane unless you''re overtaking','بەردەوام بە لە شۆفێری کردن لەسەر سایدى دەستە چەپ مەگەر ئەوەى تێپەڕاندن ئەنجام بدەیت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:402',(select id from public.theory_sections where slug = 'motorway-rules'),6,'You''re travelling along a motorway. When are you allowed to overtake on the left?','بە درێژایی مۆتۆروەیەک گەشت دەکەیت. کەى ڕێگەت پێدەدرێت لە دەستە چەپەوە تێپەڕاندن ئەنجام بدەیت ؟','When in queues and traffic to your right is moving more slowly than you are','کاتێک ڕیزە ئۆتۆمبێلى سایدی دەستە ڕاستت و ئوتومبیلەکان بە بەراورد لەگەڵ تۆ زۆر هێواش تر دەڕۆن.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:403',(select id from public.theory_sections where slug = 'motorway-rules'),7,'You''re driving on the motorway. Which lane should you get into well before you reach your exit?','لە سەر مۆتۆروەى شۆفێرى دەکەیت. لەسەر چ سایدێک دەبێت بمێنیتەوە پێش ئەوەى بگەیتە ڕێگاى چوونەدەرەوەى مۆتۆروەیەکە؟','The left-hand lane','سایدى دەستە چەپ.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:404',(select id from public.theory_sections where slug = 'motorway-rules'),8,'When would you use an emergency refuge area on a smart motorway?','دەبێت کەى ناوچەى ڕێفیوجی ئەیرییا بەکاربهێنیت لەسەر مۆتۆروەی زیرەک؟','In cases of emergency or breakdown','لە حاڵەتى ئیمرجنسی یان پەککەوتندا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:405',(select id from public.theory_sections where slug = 'motorway-rules'),9,'What colour are the reflective studs between a motorway and a slip road?','ڕەنگى بەردی جیاکەرەوەی سەر ڕێگاى نێوان مۆتۆروەیەک و ئەو ڕێگایەی لێی جیادەبێتەوە چییە؟','Green','سەوز.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:406',(select id from public.theory_sections where slug = 'motorway-rules'),10,'You''re driving on a motorway. What does it mean if the car in front shows its hazard warning lights for a short time?','لەسەر مۆتۆروەییەک شۆفیری دەکەیت. ئەوە بەمانای چی دێت ئەگەر ئۆتۆمبێلی پێشت گڵۆپەکانى ئاگادارکردنەوەى مەترسی دابگیرسێنێت بۆ ماوەیەکى کورت؟','Traffic ahead is slowing or stopping suddenly','ئۆتۆمبێلەکانى پێشەوە خاو دەبێتەوە یان لەناکاو دەوەستێت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:407',(select id from public.theory_sections where slug = 'motorway-rules'),11,'What''s the national speed limit on motorways for cars and motorcycles?','ناشناڵ سپید لیمتد بۆ ئۆتۆمبێل و ماتۆڕسکیل چەندە لەسەر مۆتۆروەی؟','70 mph','٧٠ میل لە کاتژمێرێکدا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:408',(select id from public.theory_sections where slug = 'motorway-rules'),12,'You''re on a smart motorway. What does it mean when a red cross is displayed above the hard shoulder?','لەسەر مۆتۆروەیەکى زیرەکیت. هێمای زەڕبێکی سوور لە سەرەوەى هاردشۆڵدەرەکەوە پیشاندراوە ئەوە مانای چییە؟','You shouldn''t travel in this lane','نابێت شۆفیری بکەیت لەسەر ئەم سایدە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:409',(select id from public.theory_sections where slug = 'motorway-rules'),13,'Which vehicles aren''t allowed to use the right-hand lane of a three-lane motorway?','کام ئۆتۆمبێل ڕێگەى پێ نادرێت سایدى دەستە ڕاست بەکاربهێنێت لە مۆتۆروەیەکى سێ سایدیدا؟','Vehicles towing a trailer','ئەو ئۆتۆمبێلە بارهەڵگرانەى کە عەرەبانەی پێوەدەبەستراوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:410',(select id from public.theory_sections where slug = 'motorway-rules'),14,'Your vehicle breaks down on a motorway and you need to call for help. Why might it be better to use an emergency roadside telephone rather than a mobile phone?','ئۆتۆمبێلەکەت لەسەر مۆتۆروەی پەکى کەوتووە پێویستە پەیوەندى بکەیت بۆ داواکردنى یارمەتى. بۆچى باشترە تەلەفونى ئێمەرجنسی قەراغ ڕێگاکە بەکاربهێنیت وەک بەکارهێنانى مۆبایل؟','It allows easy location by the emergency services','یارمەتى تیمەکانی ئیمرجنسی دەدات کە شوێنەکە بە ئاسانى بدۆزنەوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:411',(select id from public.theory_sections where slug = 'motorway-rules'),15,'What''s the speed limit for a car towing a trailer on a motorway?','ئەوپەڕى خێرایی ڕێگەپێدراو چەندە بۆ ئەو ئۆتۆمبێلە بارهەڵگرانەى کە عەرەبانە بەدواى خۆیاندا ڕادەکێشن؟','60 mph','٦٠ میل لە کاتژمێرێکدا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:412',(select id from public.theory_sections where slug = 'motorway-rules'),16,'You''re on a three-lane motorway. Which lane are you in if there are red reflective studs on your left and white ones to your right?','لەسەر مۆتۆروەیەکى سێ سایدیت. لەسەر کام سایدیت ئەگەر بەردی جیاکەرەوەی ڕەنگ سووری سەر ڕێگا لە دەستە چەپت بن وە ڕەنگ سپیش لە دەستە ڕاستت بن؟','In the left-hand lane','لەسەر سایدى دەستە چەپ.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:413',(select id from public.theory_sections where slug = 'motorway-rules'),17,'You''re travelling along a motorway. Where would you find a crawler or climbing lane?','بە درێژایی مۆتۆروەیەک گەشت دەکەیت. لە کوێ دەتوانیت سایدى زیادەى ئۆتۆمبێلە بارهەڵگرو هێواشەکان بدۆزیتەوە بە تایبەتى لە ڕێگا هەورازەکاندا؟','On a steep gradient','ڕێگای هەورازى.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:414',(select id from public.theory_sections where slug = 'motorway-rules'),18,'What should you do when going through a contraflow system on a motorway?','دەبێت چی بکەیت کاتێک بەسەر ڕێگای سیستمی ئاڕاستە پێچەوانەدا دەڕۆیت لەسەر مۆتۆروەی؟','Keep a good distance from the vehicle ahead','مەوداییەکى دوورى باش بهێڵیتەوە لەگەڵ ئۆتۆمبێلەکەى پێشەوەت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:415',(select id from public.theory_sections where slug = 'motorway-rules'),19,'How do smart motorways prevent traffic bunching?','چۆن مۆتۆروەییە زیرەکەکان ڕێگرى دەکەن لە دروستبوونی قەرەباڵەغى شەقامەکان؟','By using variable speed limits','لە ڕێگەى بەکارهێنانى ئەوپەڕی خێرای جیاوازەوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:416',(select id from public.theory_sections where slug = 'motorway-rules'),20,'You''re on a motorway that isn''t subject to smart motorway regulations. When should you use the hard shoulder?','شۆفێری لەسەر مۆتۆروەییەک دەکەیت کە یاساکانی مۆتۆروەی زیرەکی تیا پەیڕوە ناکرێت. کەى دەبێت هارد شۆڵدەر بەکاربهێنیت؟','When you''re stopping in an emergency','کاتێک لە حاڵەتێکى ئێمەرجنسیدا دەوەستیت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:417',(select id from public.theory_sections where slug = 'motorway-rules'),21,'Where are amber reflective studs found on a motorway?','لە کوێی مۆتۆروەی بەردی جیاکەرەوەی رەنگی زەردباو دەدۆزرێنەوە ؟','Between the central reservation and the carriageway','لە نێوان بۆشایی نێوبەند( جەزرە وەسەتی)و کاریجوەی.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:418',(select id from public.theory_sections where slug = 'motorway-rules'),22,'What do these motorway signs mean?','ماناى ئەم هێمایەی مۆتۆروەی چیە؟','They''re countdown markers to the next exit','هێمای ژماردنە بۆ ڕێگاى دەرچوونى داهاتوو.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:419',(select id from public.theory_sections where slug = 'motorway-rules'),23,'Your vehicle has broken down on a motorway. What should you do if you aren''t able to get onto the hard shoulder?','ئۆتۆمبێلەکەت پەکى کەوتووە لەسەر مۆتۆڕوەیەک. دەبێت چی بکەیت ئەگەر نەتوانى بگەیت بە هاردشۆڵدەر؟','Switch on your hazard warning lights','گڵۆپى ئاگادارکردنەوەى مەترسی دابگیرسێنە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:420',(select id from public.theory_sections where slug = 'motorway-rules'),24,'How should you rejoin the motorway after a breakdown on the hard shoulder?','چۆن دووبارە دەڕۆیتەوە سەر مۆتۆروەی لە هاردشۆڵدەرەکەوە لە پاش ئەوەی پەکت کەوتوبوو؟','Build up speed on the hard shoulder before looking for a safe gap in the traffic','خۆت ئامادە بکە بۆ ئەوەى بە خێرایی لەسەر هاردشۆڵدەرەکەوە دەربچیت پێش ئەوەى چاوبگیری بۆ بۆشاییەکى سەلامەتى لە نێو هاتووچۆى ئۆتۆمبێلەکاندا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:421',(select id from public.theory_sections where slug = 'motorway-rules'),25,'On a three-lane motorway, which lane should you use if there''s no traffic ahead?','لەسەر مۆتۆروەیەکى سێ سایدى، دەبێت کام لە سایدەکان بەکاربهێنیت ئەگەر هیچ جۆرە هاتووچۆیەکى ئۆتۆمبێل لە پێشەوە نەبوو؟','Left','چەپ','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:422',(select id from public.theory_sections where slug = 'motorway-rules'),26,'Your car gets a puncture while you''re driving on the motorway. What should you do when you''ve stopped on the hard shoulder?','لە کاتێکدا لەسەر مۆتۆروەی شۆفێری دەکەیت ئۆتۆمبێلەکەت پەنچەر دەبێت. دەبێت چی بکەیت کە لەسەر هاردشۆڵدەر دەوەستیت ؟','Use an emergency telephone and call for help','تەلەفۆنێکى ئیمرجنسی بەکاربهێنە و داواى یارمەتى بکە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:423',(select id from public.theory_sections where slug = 'motorway-rules'),27,'Where should you stop to rest if you feel tired while you''re travelling along a motorway?','لە کوێ دەبێت بوەستیت بۆ پشوودان ئەگەر هەست بە ماندوویەتى کرد لە کاتێکدا لەسەر مۆتۆروەی شۆفیری دەکەیت ؟','At the nearest service area','لە نزیکترین ناوچەى خزمەتگوزارى چاککردنەوەى ئۆتۆمبێل.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:424',(select id from public.theory_sections where slug = 'motorway-rules'),28,'What colour are the reflective studs between the lanes on a motorway?','بەردە فسفۆرەکانی نێوان سایدەکانى مۆتۆروەی چ ڕەنگێکن ؟','White','سپی','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:425',(select id from public.theory_sections where slug = 'motorway-rules'),29,'What should you do if you''re driving on a motorway and you miss the exit that you wanted to take?','دەبێت چی بکەیت ئەگەر لەسەر مۆتۆروەیەک شۆفێری کرد و ویستت مۆتۆروەیەکە جێبهێڵى بەڵام رێگاى دەرچوون لە مۆتۆروەیەکە تێپەڕاند؟','Carry on to the next exit','بەردەوام بە لە شۆفیری کردن تاوەکو دەگەیت بە ڕێگاى چوونەدەرەوەى داهاتوو.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:426',(select id from public.theory_sections where slug = 'motorway-rules'),30,'You''re on a motorway. What must you do if there''s a red cross showing above every lane?','لەسەر مۆتۆروەیەکیت. پێویستە چی بکەیت ئەگەر هێمای زەڕبی سوور پیشاندرا لەسەر هەریەکێک لە سایدەکان؟','Stop and wait','بوەستە و چاوەڕێ بکە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:427',(select id from public.theory_sections where slug = 'motorway-rules'),31,'Your vehicle has broken down on a motorway. In which direction should you walk to find the nearest emergency telephone?','ئۆتۆمبێلەکەت پەکى کەوتووە لەسەر مۆتۆروەییەک. دەبێت چ ئاراستەیەکدا ڕێ بکەیت بۆ دۆزینەوەى نزیکترین تەلەفۆنى حاڵەتى ئیمیرجنسی؟','In the direction shown on the marker posts','بە ئەو ئاراستەیەى لەسەر ستوونى ‌هێماکان پیشاندراوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:428',(select id from public.theory_sections where slug = 'motorway-rules'),32,'You''re on a smart motorway. What does it mean when a mandatory speed limit is displayed above the hard shoulder?','لەسەر مۆتۆروەى زیرەک شۆفێری دەکەیت. ئەوە بە ماناى چی دێت کاتێک هێمای دیاریکردنى خێرایی ناچاری لەسەرو هاردشۆڵدەر پیشان دەدرێت ؟','The hard shoulder can be used as a running lane','هاردشۆڵدەر دەتوانرێت بەکاربهینرێت وەکو سایدى رۆیشتن ( وەک سایدەکانی دیکە )','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:429',(select id from public.theory_sections where slug = 'motorway-rules'),33,'What restrictions apply to people who have a provisional driving licence?','چ سنووردارێتییەک ئەپڵای دەبێت بەسەر ئەو کەسانەی مۆڵەتى شۆفیری فیرکارییان هەیە؟','They can''t drive unaccompanied','ناتوانن شۆفیری بکەن بەبێ ئەوەى کە کەسی تریان لەگەڵ بێت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:430',(select id from public.theory_sections where slug = 'motorway-rules'),34,'You''re in the right-hand lane of a three-lane motorway. What do these overhead signs mean?','لە سایدى دەستەڕاستى مۆتۆروەیەکى سێ سایدیدت. ئەو هێمایانەى بەشی سەرەوە بە ماناى چی دێن؟','Move to the left and reduce your speed to 50 mph','بڕۆ سایدى دەستە چەپ و خێراییەکەت کەم بکەرەوە بۆ ٥٠ میل لە کاتژمێرێکدا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:431',(select id from public.theory_sections where slug = 'motorway-rules'),35,'On a smart motorway, what does this sign mean?','لەسەر مۆتۆروەی زیرەک ئەم هێمایە بە ماناى چی دێت؟','Use all the lanes, including the hard shoulder','هەموو سایدەکان بەکاربهێنە لە ناویشیاندا هاردشۆڵدەرەکە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:432',(select id from public.theory_sections where slug = 'motorway-rules'),36,'What should you do while you''re driving or riding along a motorway?','دەبێت چی بکەیت لە کاتێکدا شۆفیری بکەیت یان ماتۆڕسکیلێک لێ بخوڕیت لەسەر مۆتۆڕوەی؟','Look much further ahead than you would on other roads','زیاترى سەیری پێشەوەت بکە بە بەروارد لەگەڵ ڕێگاکانى تر.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:433',(select id from public.theory_sections where slug = 'motorway-rules'),37,'Why is it particularly important to check your vehicle before making a long motorway journey?','بۆچی گرنگە بەتایبەتى چێكی ئۆتۆمبێلەکەت بکەیت پێش ئەوەى گەشت بکەیت لەسەر مۆتۆروەی؟','Continuous high speeds increase the risk of your vehicle breaking down','بە بەردەوامى لێخوڕین بە خێرایی بەرز مەترسی پەککەوتنى ئۆتۆمبێلەکەت زیاتر دەکات.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:434',(select id from public.theory_sections where slug = 'motorway-rules'),38,'What should you do immediately after joining a motorway?','دوای ڕۆیشتنە سەر مۆتۆروەی دەبێت ڕاستەوخۆ چی بکەیت؟','Stay in the left-hand lane','لە سایدى دەستە چەپ بمێنیتەوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:435',(select id from public.theory_sections where slug = 'motorway-rules'),39,'You''re joining a motorway from a slip road. How should you deal with traffic already on the motorway?','دەڕۆیتە سەر مۆتۆروەییەک لە ڕێگای لاوەکیەوە. چۆن مامەڵە لەگەڵ ئەو ئۆتۆمبێلانە دەکەیت پێش تۆ لەسەر مۆتۆروەییەکەن؟','Match your speed to traffic in the left-hand lane and filter into a safe gap','خێرایەکەت بخەرە ئاستى خێرایی ئۆتۆمبێلەکانى سایدى دەستە چەپ وە بڕۆ نێو بۆشاى سەلامەتەوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:436',(select id from public.theory_sections where slug = 'motorway-rules'),40,'Which vehicles are prohibited from using the motorway?','کام ئوتومبێل قەدەغەیە مۆتۆروەی بەکاربهێنێت؟','Powered mobility scooters','ماتۆڕى سکووتەرى کارەبایی.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:437',(select id from public.theory_sections where slug = 'motorway-rules'),41,'You''re driving on a motorway and have to slow down suddenly due to a hazard ahead. How can you warn drivers behind of the hazard?','لەسەر مۆتۆروەیەک شۆفیری دەکەیت. پێویستە ئۆتۆمبێلەکەت لەپڕ هێواش بکەیتەوە بەهۆى مەترسییەک لە پێشەوەیە. چۆن ئاگادارى شۆفێرەکانى دوای خۆت دەکەیتەوە لە مەترسییەکە؟','Switch on your hazard warning lights','گڵۆپەکانى ئاگادارکردنەوەى مەترسیت دابگیرسێنە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:438',(select id from public.theory_sections where slug = 'motorway-rules'),42,'When would you use the right-hand lane on a three-lane motorway?','کەى سایدى دەستەڕاست لەسەر مۆتۆروەیەکى سێ سایدى بەکاردەهێنیت ؟','When you''re overtaking','کاتێک تێپەڕاندن ئەنجام دەدەیت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:439',(select id from public.theory_sections where slug = 'motorway-rules'),43,'You stop on the hard shoulder of a motorway and use the emergency telephone. Where''s the best place to wait for help to arrive?','لەسەر هاردشۆڵدەرى مۆتۆڕوەی وەستاویت و تەلەفۆنى ئیمرجنسی بەکاردەهێنیت. باشترین شوێن کوێیە بۆ ئەوەى چاوەڕوانى گەیشتنی یارمەتى بکەیت؟','Well away from the carriageway','بە باشی لە مۆتۆوەیەکەوە دووربە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:440',(select id from public.theory_sections where slug = 'motorway-rules'),44,'You''re travelling in the left-hand lane of a three-lane motorway. How should you react to traffic joining from a slip road?','لەسەر سایدى دەستەچەپی مۆتۆروەیەکى سێ سایدى گەشت دەکەیت. دەبێت کاردانەوە چۆن بێت بەرامبەر ئەو ئۆتۆمبێلانەى لە ڕێگای لاوەکیەوە دێنەسەر مۆتۆروەییەکە؟','Adjust your speed or change lane if you can do so safely','خێراییەکەت ڕێکبخە یان سایدەکە بگۆڕە ئەگەر دەتوانیت بە سەلامەتى ئەنجامى بدەیت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:441',(select id from public.theory_sections where slug = 'motorway-rules'),45,'You''re towing a trailer along a three-lane motorway. When may you use the right-hand lane?','ترەیلەرێک ڕادەکێشیت بە درێژایی مۆتۆروەیەکى سێ سایدى. کەى دەتوانی سایدى دەستەڕاست بەکاربهێنىت؟','When there are lane closures','کاتێک کە داخرانى ساید لە ئارادایە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:442',(select id from public.theory_sections where slug = 'motorway-rules'),46,'What''s the national speed limit for a car or motorcycle on a motorway?','ناشناڵ سپید لیمتد چەندە بۆ ئۆتۆمبێل یاخود ماتۆڕسکیل لەسەر مۆتۆروەی؟','70 mph','٧٠ میل لە کاتژمێرێکدا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:443',(select id from public.theory_sections where slug = 'motorway-rules'),47,'What should you do when you''re approaching roadworks on a motorway?','دەبێت چی بکەیت کاتێک نزیک دەبیتەوە لە شوێنی کارکردنى سەر ڕێگا لەسەر مۆتۆروەی؟','Obey the speed limit','پابەند بیت بە خێرایی دیاریکراوە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:444',(select id from public.theory_sections where slug = 'motorway-rules'),48,'Traffic officers operate on motorways and some primary routes in England and Wales. What are they authorised to do?','کارمەندانى پۆلیسی هاتووچۆ لەسەر مۆتۆروەییەکان و هەندێک ڕێگاى سەرەکى لە ئینگلتەرا و وێڵز کاردەکەن. دەسەڵاتی چیان پێدراوە بیکەن؟','Stop and direct anyone on a motorway','دەتوانن هەرکەسێک بوەستن و ڕێنمایی بکەن لەسەر مۆتۆڕوەی.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:445',(select id from public.theory_sections where slug = 'motorway-rules'),49,'When should you use the left-hand lane of a motorway?','کەى دەبێت سایدى دەستە چەپ بەکاربهێنیت لەسەر مۆتۆروەی؟','When the road ahead is clear','کاتێک ڕێگاکەى پێشەوە چۆڵە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:446',(select id from public.theory_sections where slug = 'motorway-rules'),50,'Which vehicles should use the left-hand lane on a three-lane motorway?','چ ئۆتۆمبێلێک دەتوانێت سایدى دەستەچەپ بەکاربهێنێت لەسەر مۆتۆروەیەکى سێ سایدى؟','Any vehicle that isn''t overtaking','هەر ئۆتۆمبێلێک کە تێپەڕاندن ئەنجام نەدات.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:447',(select id from public.theory_sections where slug = 'motorway-rules'),51,'When are you allowed to stop on a motorway?','کەى ڕێگەت پێدراوە لەسەر مۆتۆروەی بوەستیت ؟','When you''re signalled to do so by traffic signals','کاتێک ‌هێماکانی سەر شەقام ئاماژەت دەدەنێ ئەو کارە ئەنجام بدەیت.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:448',(select id from public.theory_sections where slug = 'motorway-rules'),52,'You have stopped in an emergency refuge area. What must you do before you rejoin the carriageway?','وەستاویت لە ناوچەی ئیمرجنسی. دەبێت چی بکەیت پێش ئەوەى دووبارە بێیتەوە سەر کاریجەوەیەکە (ڕێگا سەرەکییەکە)؟','Use the emergency telephone','تەلەفۆنى ئێمرجنسی بەکاربهێنە.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:449',(select id from public.theory_sections where slug = 'motorway-rules'),53,'When may you stop on a motorway?','کەى دەکرێت لەسەر مۆتۆروەیەک بوەستى ؟','In an emergency or breakdown','لە حاڵەتێکى ئیمرجنسی یان پەککەوتندا.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:450',(select id from public.theory_sections where slug = 'motorway-rules'),54,'You''re on a smart motorway. What does it mean if a red cross is showing above the hard shoulder and mandatory speed limits above all other lanes?','لەسەر مۆتۆروەى زیرەکی. ئەوە بە ماناى چی دێت ئەگەر هێمایەکى زەڕبی سوور پیشان بدرێت لەسەر هاردشۆڵدەر و هێماى خێرایی دیاریکراو پیشان بدرێت لەسەر هەموو سایدەکان؟','The hard shoulder is for emergency or breakdown use only','هاردشۆڵدەر تەنها بەکاردەهێنرێت بۆ حاڵەتى ئیمرجنسی یان پەککەوتنى ئۆتۆمبێل.','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:451',(select id from public.theory_sections where slug = 'motorway-rules'),55,'What colour are the reflective studs between the hard shoulder and the left-hand lane of a motorway?','ڕەنگى بەردی جیاکەرەوەی شەقام نێوان هاردشۆڵدەرو سایدى دەستەچەپی مۆتۆروەیەک چییە؟','Red','سوور','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:452',(select id from public.theory_sections where slug = 'motorway-rules'),56,'Your vehicle broke down on the hard shoulder of a motorway, but has now been repaired. How should you rejoin the main carriageway?','ئۆتۆمبێلەکەت پەکى کەوتووە لەسەر هاردشۆڵدەرى مۆتۆڕوەی بەڵام ئێستا چاک کراوەتەوە. چۆن دووبارە دەچیتەوە سەر کاریجوەیەکە( ڕێگا سەرەکییەکە)؟','Gain speed on the hard shoulder before moving out onto the carriageway','لەسەر هاردشۆڵدەرەکە خێراییەکەت زیاد بکە پێش ئەوەى بڕۆیتە سەر کاریجوەیەکە (ڕێگا سەرەکییەکە.)','draft','content:uk-theory-questions'),
  ('theory:motorway-rules:453',(select id from public.theory_sections where slug = 'motorway-rules'),57,'Why is it important to make full use of the slip road as you join a motorway?','بۆچى گرنگە بە تەواوەتى ڕێگای لاوەکی بەکاربهێنى هەرکە دەڕۆیتە سەر مۆتۆروەی؟','To allow you to fit safely into the traffic flow in the left-hand lane','یارمەتیت دەدات بە سەلامەتى بچیتە نیو ڕێڕەوی هاتووچۆکەوە لە سایدى دەستە چەپ.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:454',(select id from public.theory_sections where slug = 'rules-of-the-road'),1,'When may you stop on a clearway?','کەى دەکرێــت لەسەر کـلیەروەی بوەستیت؟ (ڕێگـایەک کە جووڵەى ئۆتۆمبێلەکـان لەسەرى بەردەوامە و نابێـت بە هیچ شێوەیەک بوەستن تەنها لە حاڵەتـى بەپەلەدا نەبێــت)','Never','هەرگیـز.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:455',(select id from public.theory_sections where slug = 'rules-of-the-road'),2,'Which vehicle is most likely to take an unusual course at a roundabout?','چ ئۆتۆمبێلیک زیاتر ئاراستەو جوڵەى نائاسایـی وەردەگرێ لە کـاتـى سووڕاندەوەى بەدەورى ڕاوندئەباوتدا؟','Long vehicle','ئۆتۆمبێلـى درێژ.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:456',(select id from public.theory_sections where slug = 'rules-of-the-road'),3,'You''re turning right at a crossroads. An oncoming driver is also turning right. What''s the advantage of turning behind the oncoming vehicle?','لە ڕێگـایەکـى چوارڕێیاندا بە دەستە ڕاستدا پێچ دەکەیتەوە. شۆفێـرێکیش کە بەرەوڕووت دێـت بەهەمان شێوە بۆ دەستە ڕاست پێچ دەکـاتەوە. سوودى چییە لە دوای ئۆتۆمبێلەکەوە پێچ بکەیتەوە؟','You''ll have a clearer view of any approaching traffic','بینینێکـى باشتـرت دەبێــت بۆ هەر ئۆتۆمبێلێک کە نزیک دەبێتەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:457',(select id from public.theory_sections where slug = 'rules-of-the-road'),4,'When are you allowed to park in a parking bay for disabled drivers?','کەى ڕێگەت پێدەدرێـت ئۆتۆمبێلەکەت لە شوێنـى ڕاوەستاندنـى خاوەن پێداویستـى تایبەت پارکبکەیت؟','When you have a Blue Badge','کـاتێک ئۆتۆمبێلەکەت باجـى شینـى پێوەیە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:458',(select id from public.theory_sections where slug = 'rules-of-the-road'),5,'When may you stop and wait in a box junction?','کەى دەکرێـت بوەستیت و چاوەڕێ بکەیت لە چوارگۆشەی زەردی یەکتـربڕدا ؟','When oncoming traffic prevents you from turning right','کـاتێک ئۆتۆمبێلانەى ڕووبەڕووت دێن ڕێگەت پێنەدەن پێچبکەیتەوە بە دەستە ڕاستدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:459',(select id from public.theory_sections where slug = 'rules-of-the-road'),6,'What should you do if you see a pedestrian waiting at a zebra crossing?','دەبێــت چـی بکەیت کـاتێک پیادەڕۆیەکت بینـی لە شوێنـى پەڕینەوە چاوەڕێ دەکـات ؟','Be ready to slow down or stop to let them cross','ئامادەبە هێواشـی بکەیتەوە یاخود بوەستیت بۆ ئەوەى ڕێگەیان پێبدەیت بپەڕێتەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:460',(select id from public.theory_sections where slug = 'rules-of-the-road'),7,'Who has priority at an unmarked crossroads?','پێشڕەوی بۆ کێیە لەسەر ڕێگـایەکـى چوارڕێیان کە هێڵکـارى لەسەر دیارى نەکراوە؟','No-one has priority','پێشڕەوی بۆ هیچ کەسێک نییە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:461',(select id from public.theory_sections where slug = 'rules-of-the-road'),8,'Which vehicle might have to take a different course from normal at a roundabout?','چ ئۆتۆمبێلیک دەکرێـت لەسەر ئاراستەیەکـى جیاواز بڕوات بەدەر لە ئاراستەى ئاسایـی لەکـاتـی سووڕانەوە بە دەورى ڕاوند ئەباوتێکدا؟','Long vehicle','ئۆتۆمبێلـى درێژ.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:462',(select id from public.theory_sections where slug = 'rules-of-the-road'),9,'Where''s the safest place to park your vehicle at night?','سەلامەتتـرین شوێن کوێیە بۆ پارکردنـی ئۆتۆمبێلەکەت لە شەودا؟','In a garage','لە گەراجدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:463',(select id from public.theory_sections where slug = 'rules-of-the-road'),10,'You''re waiting at a pelican crossing. What does it mean when the red light changes to flashing amber?','چاوەڕێ دەکەیت لە شوێنـى پەڕینەوەى زیرەکدا (ئەم جۆرەیان ترافیک لایتـى تایبەت بە خۆى هەیە کە لە لایەن کەسانـى پیادەڕۆوە کۆنترۆڵ دەکرێت). مەبەست لەوە چییە کـاتێک کە گـڵۆپە سوورەکە دەگۆڕدرێـت بۆ گـڵـۆپـی زەردباو کە بەبەردەوامـى فلاش دەکـات؟','Give way to pedestrians on the crossing','ڕێگە بدە پیادەڕۆکـان بپەڕنەوە لە شوێنـى دیاریکراوى پەڕینەوەکە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:464',(select id from public.theory_sections where slug = 'rules-of-the-road'),11,'You''re travelling on a motorway in England. When must you stop your vehicle?','لەسەر مۆتۆڕوەی لە ئینگـلتەرا گەشت دەکەیت. کەى دەبێت ئۆتۆمبێلەکەت بوەستێنیت؟','When signalled to stop by a traffic officer','کـاتێک لە لایەن پۆلیسـی هاتووچۆوە ئاماژەت بۆ کرا بوەستیت .','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:465',(select id from public.theory_sections where slug = 'rules-of-the-road'),12,'You''re reversing into a side road. When would your vehicle be the greatest hazard to passing traffic?','بە ئۆتۆمبێلەکەت بەگدادەنێت بۆ قەراغـی ڕێگـاکە. کەى ئۆتۆمبێلەکەت دەبێتە مەترسییەکـى گەورە بۆ ئۆتۆمبێلەکـانـی لەوێوە دەڕۆن؟','When the front of your vehicle swings out','کـاتێک بەشـی پێشەوەى ئۆتۆمبێلەکەت لە قەراغـی ڕێگـاکەوە دەردەچێـت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:466',(select id from public.theory_sections where slug = 'rules-of-the-road'),13,'Where should you park your vehicle at night?','دەبێـت لە شەودا لە کوێ ئۆتۆمبێلەکەت پارک بکەیت ؟','In a well-lit area','لە ناوچەیەک بەباشـی ڕووناک کرابێتەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:467',(select id from public.theory_sections where slug = 'rules-of-the-road'),14,'How far are you allowed to reverse?','بۆ مەوداى چەندێک ڕێگەت پێدراوە بە ئۆتۆمبێلەکەت بەگدابنێیت؟','No further than is necessary','زیاد لەوەی پێویست دەکـات نەبێـت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:468',(select id from public.theory_sections where slug = 'rules-of-the-road'),15,'What should you do when you''re unsure whether it''s safe to reverse your vehicle?','دەبێــت چـی بکەیت کـاتێک کە دڵنیا نیت کە ئایا سەلامەتە بەگ دابنێیت؟','Get out and check','دابەزە لە ئۆتۆمبێلەکەت و چێک بکە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:469',(select id from public.theory_sections where slug = 'rules-of-the-road'),16,'What should you do when there''s an obstruction on your side of the road?','دەبێــت چـی بکەیت کاتێک بەربەستێک لە سەر سایدى ڕێگـاکەت هەیە؟','Give way to oncoming traffic','ڕێگە بدە بەو ئۆتۆمبێلانەى ڕووبەرووت دێن.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:470',(select id from public.theory_sections where slug = 'rules-of-the-road'),17,'Why could it be dangerous to reverse from a side road into a main road?','بۆچـی مەترسیدارە کە ئۆتۆمبێلەکەت بۆ دواوە بەگتدابنێیت لە قەراغـی ڕێگـایەکەوە بۆ سەر ڕێگـاى سەرەکـى؟','Your view will be restricted','مەودای بینینت سنووردار دەبێـت','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:471',(select id from public.theory_sections where slug = 'rules-of-the-road'),18,'You''re parked in a busy high street. What''s the safest way to turn your vehicle around so you can drive in the opposite direction?','ئۆتۆمبێلەکەت لە شەقامێکـى سەرەکـى قەرەباڵەغ پارک کردووە. سەلامەتترین ڕێگـا چییە بۆ ئەوەى ئۆتۆمبێلەکەت بسوڕێنیتەوە بۆ سەر سایدی بەرامبەر و لێبخوڕیت؟','Turn around in a quiet side road','پێچ بکەرەوە لە سایدە چۆڵەکەی ڕێگـاکە .','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:472',(select id from public.theory_sections where slug = 'rules-of-the-road'),19,'What''s the nearest you may park to a junction?','(پێویست ناکـات پێداچوونەوە بەم پرسیارەدا بکەیت ئەگەر لە ئیرلەنداى باکور دەژیت) نزیکترین مەودا چەندە لە یەکتـربڕێکدا ئۆتۆمبێلەکەتـی لـێ پارک بکەیت ؟','10 metres (32 feet)','١٠ مەتر (٣٢ پێ)','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:473',(select id from public.theory_sections where slug = 'rules-of-the-road'),20,'You want to turn right at a box junction. What should you do if there''s oncoming traffic?','دەتەوێـت پێچ بکەیتەوە بۆ لای راست لە یەکتـربڕی چوارگۆشەدا. (بۆکس) دەبێــت چـی بکەیت ئەگەر ئۆتۆمبێل بەرەوڕووت هات؟','Wait in the box junction if your exit is clear','لە چوارگۆشەکەدا چاوەڕێ بکە ئەگەر رێگـاى چوونەدەرەوەت چۆڵ بوو.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:474',(select id from public.theory_sections where slug = 'rules-of-the-road'),21,'You''re going to turn left from a main road into a minor road. What should you do as you approach the junction?','لە ڕێگـایەکـى سەرەکییەوە بۆ سەر ڕێگـایەکـى لاوەکـى پێچ دەکەیتەوە. دەبێـت چـی بکەیت کـاتێک لە یەکتـربڕەکە نزیک دەبیتەوە؟','Keep well to the left of the road','بە باشـی لە دەستە چەپـی ڕێگـاکە بمێنەرەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:475',(select id from public.theory_sections where slug = 'rules-of-the-road'),22,'What must you do if you come across roadworks that have a temporary speed limit displayed?','دەبێــت چـی بکەیت ئەگەر بەڕێگـایەکدا ڕۆیشتیت و کـارکردنـى لەسەر بوو و هێماى خێـرای سنوورداریشـی لەسەر دانرابوو؟','Obey the speed limit','گۆێڕایەڵـى هێماکە بە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:476',(select id from public.theory_sections where slug = 'rules-of-the-road'),23,'How should you signal if you''re going straight ahead at a roundabout?','چۆن گـڵـۆپـی ئیشارەتەکـانت بەکـاردەهێنیت ئەگەر ڕێک بەرەو پێشەوە لێبخوڕیت لە ڕاوند ئەباوتێکدا؟','Signal left just after you pass the exit before the one you''re going to take','گـڵـۆپـی ئیشارەتـی دەستە چەپ کـارپێبکە پاش ئەوەى خاڵـی دەرچوونت بەجێهێشت و پێش ئەوەی بچیتە سەر ئەو ڕێگـایەی کە دەتەویت بۆی بچێت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:477',(select id from public.theory_sections where slug = 'rules-of-the-road'),24,'You''re looking for somewhere to safely park your vehicle. Where would you choose to park?','بەدوای شوێنێکدا دەگەڕێیت بۆ ئەوەى بە سەلامەتـى ئۆتۆمبێلەکەتـی لـێ پارک بکەیت. چ شوێنێک هەڵدەبژێرى بۆ پارک کردن؟','In a designated parking space','لە شوێنێکـى دیاریکراوى پارکیـن.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:478',(select id from public.theory_sections where slug = 'rules-of-the-road'),25,'What''s the meaning of this sign?','ماناى ئەم هێمایە چییە؟','National speed limit applies','ناشناڵ سپید لیمتد بەکـاردەهێنرێــت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:479',(select id from public.theory_sections where slug = 'rules-of-the-road'),26,'What signal should you give when you''re going straight ahead at a roundabout?','چ گـڵۆپێکـى ئیشارەت دەبێـت بەکـاربهێنیت کـاتێک ڕاستەوخۆ بۆ پێشەوە شۆفیـرى دەکەیت لە ڕاوند ئەباوتێکدا؟','Signal left before leaving the roundabout','گـڵۆپـی ئیشارەتـی دەستەچەپ کـار پێبکە پێش ئەوەى ڕاوندئەباوتەکە بەجێبهێڵیت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:480',(select id from public.theory_sections where slug = 'rules-of-the-road'),27,'What does this sign mean?','ئەم هێمایە ماناى چییە.؟','End of minimum speed','کۆتایی کەمترین خێرایی ڕێگەپیدراو','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:481',(select id from public.theory_sections where slug = 'rules-of-the-road'),28,'You''re driving in the right-hand lane of a dual carriageway. What should you do if you see a sign showing that the right-hand lane is closed 800 yards ahead?','شۆفێـرى دەکەیت لە سایدى دەستەڕاستـى دەبڵ کـاریجوەی. دەبێـت چـى بکەیت ئەگەر هێمایەکـى هاتووچۆت بینـی نیشان درابوو کە سایدى دەستەڕاست لە ٨٠٠ یاردى پێشەوە داخراوە؟','Move to the left in good time','لە کـاتێکـى گونجاودا بچۆرە دەستەچەپ.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:482',(select id from public.theory_sections where slug = 'rules-of-the-road'),29,'What should you do if the amber lights come on and a warning sounds while you''re driving over a level crossing?','دەبێــت چـی بکەیت ئەگەر گـڵۆپە زەردباوەکـان هەڵ ببن و ئاگـادارکەرەوەی دەنگـی دەربکەن لە کـاتێکدا لەسەر هێڵـى ئاسنـى شەمەندەفەر شۆفێـرى دەکەیت ؟','Keep going and clear the crossing','بەردەوام بە لە لێخوڕین و هێڵـی شەمەندەفەرەکە چۆڵ بکە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:483',(select id from public.theory_sections where slug = 'rules-of-the-road'),30,'You see these double white lines along the centre of the road. When may you park on the left?','ئەم دوو هێڵە سپییە دەبینـى لە ناوەڕاستـى ڕێگـاکە کە یەکێکیان ڕاستەو ئەوى تریشیان پچڕپچڕە. کەى دەکرێـت ئۆتۆمبێلەکەت لە دەستە چەپ ڕاگریت ؟','To pick up or set down passengers','. بۆ هەڵگرتن و دابەزاندنـى سەرنشین.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:484',(select id from public.theory_sections where slug = 'rules-of-the-road'),31,'A cycle lane, marked by a solid white line, is in operation. What does this mean for car drivers?','سایدێکـى پاسکیل سوارى بە هێڵێکـى راست دیاریکراوە و لەکـاردایە،. ئەمە بە ماناى چـی دێــت بۆ شۆفیـرانـى ئۆتۆمبێل؟','They mustn''t drive along the lane','ناکرێـت بە درێژایـی سەر سایدەکە شۆفێـرى بکەن .','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:485',(select id from public.theory_sections where slug = 'rules-of-the-road'),32,'When may you drive without wearing your seat belt?','کەى دەکرێـت بەبـێ بەستنـى پشتوێنـى سەلامەتـی شۆفێـرى بکەیت ؟','When you''re carrying out a manoeuvre that includes reversing','کـاتێک جوڵەیەک بە بەگدا دەکەیت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:486',(select id from public.theory_sections where slug = 'rules-of-the-road'),33,'When may you enter a box junction?','کەى دەکرێــــــــــــــت بڕۆیتە نێو یەکتـربڕى چوارگۆشەوە؟','When your exit road is clear','کاتێک ڕێگـاى چوونە دەرەوەت چۆڵە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:487',(select id from public.theory_sections where slug = 'rules-of-the-road'),34,'What''s the national speed limit on a single carriageway road for cars and motorcycles?','ناشناڵ سپید لیمتدی ڕێگەپێدراو چەندە لە سەر ڕێگـای کـاریجوەی بۆ ئوتومبیل و ماتۆڕسکیل ؟','60mph','. ٦٠ میل لە کـاتژمێریکدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:488',(select id from public.theory_sections where slug = 'rules-of-the-road'),35,'Which road users benefit from toucan crossings?','کـام لە بەکـارهێنەرانـى ڕێگـا سوود دەبینن لە شوێنـى پەرینەوەى پیادە و پاسکیلسوار؟ ؟','Cyclists and pedestrians','پاسکیل سوارەکـان و پیادەڕۆکـان.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:489',(select id from public.theory_sections where slug = 'rules-of-the-road'),36,'A single carriageway road has this sign. What''s the maximum permitted speed for a car towing a trailer?','ڕێگـایەکـی سینگـڵ کـاریجوەی ئەم هێمایەى لەسەرە. خێـرایـی ڕێگەپێدراو چەندە بۆ ئۆتۆمبێلێک کە عەرەبانەیەک بە دواى خۆیدا ڕابکێشێـــــــت؟','50mph','. ٥٠ میل لە کـاتژمێـرێکدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:490',(select id from public.theory_sections where slug = 'rules-of-the-road'),37,'What''s the speed limit for a car towing a caravan on a dual carriageway?','خێـرایـی ڕێگەپێدراو چەندە بۆ ئۆتۆمبێلێک کە کەرەڤانەیەک بەدواى خۆیدا ڕابکێشێـــــت لەسەر دەبڵ کـاریجوەی ؟','60mph','٦٠ میل لە کـاتژمێـرێکدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:491',(select id from public.theory_sections where slug = 'rules-of-the-road'),38,'You''re driving at night with your headlights on main beam. A vehicle is overtaking you. When should you dip your headlights?','لە شەودا شۆفێـرى دەکەیــت لایتـى بەی پێشەوە کردۆتە سەر بەرز. ئۆتۆمبێلێک تێتدەپەڕێنیت. دەبێـــت کەى لایتـى پێشەوەت بخەیتە سەر نزم؟','As soon as the vehicle passes you','هەرکە ئۆتۆمبێلەکە تۆی تێپەڕاند.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:492',(select id from public.theory_sections where slug = 'rules-of-the-road'),39,'You''re in a built-up area at night and the road is well lit. Why should you use dipped headlights?','لە ناوچەیەکـى دانیشتوان و لە شەودا و لە ڕێگـایەک بە باشـی ڕووناک کراوەتەوە شۆفیـرى دەکەیت. بۆ چـى دەبێــت لایتـی نزمـى پێشەوەت بەکـاربهێنـى؟','So that you can be easily seen by others','بۆ ئەوەى بە ئاسانـى ببینرێیت لە لایەن ئەوانـى ترەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:493',(select id from public.theory_sections where slug = 'rules-of-the-road'),40,'You''re looking for somewhere to park your vehicle. Neither you or your passenger are disabled. What should you do if the only free spaces are marked for disabled drivers?','بەدواى شوێنێـکدا دەگەڕێیت بۆ پارک کردنـى ئۆتۆمبێلەکەت. هیچ کام لە خۆت و سەرنشینەکـانت خاوەن پێداویستى تایبەت نین. دەبێـت چـی بکەیت ئەگەر شوێنە چۆڵەکـان تایبەت بوون بە شۆفێـرانـى خاوەن پێداویستـى تایبەت؟','Wait for a regular parking space to become free','چاوەڕێ بکە تاوەکو شوێنێکـى ئاسایـی پارکینـی ئۆتۆمبێل چۆڵ دەبێـت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:494',(select id from public.theory_sections where slug = 'rules-of-the-road'),41,'What will the speed limit usually be where you can see street lights but no speed-limit signs?','خێـرایـی ڕێگەپێدراو دەبێــت چەندبێت کـاتێک لەسەر شەقامێک بیت بتوانـى گـڵۆپـى سەر شەقام ببینیت بەڵام هێمای خێـرایـی ڕێگەپێدراو نەبینیت؟','30mph','٣٠ میل لە کـاتژمێـرێکدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:495',(select id from public.theory_sections where slug = 'rules-of-the-road'),42,'You''re travelling along a residential street. There are parked vehicles on the left-hand side. Why should you keep your speed down?','ئۆتۆمبێلەکەت بە درێژایـی شەقامێکـى ناوچەى دانیشتوان لێدەخوڕیــت. لە دەستە چەپـی شەقامەکە ئۆتۆمبێلـى پارکـکراو هەیە. بۆچـی دەبێـت خێـراییەکەت کەم بکەیتەوە؟','Children may run out from between the vehicles','دەکرێــت منداڵان لە نێوان ئۆتۆمبێلەکـانەوە ڕابکەنە دەرەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:496',(select id from public.theory_sections where slug = 'rules-of-the-road'),43,'What''s the meaning of this sign?','ماناى ئەم هێمایە چییە؟','Waiting restrictions','سنوردارکردنی وەستان( چاوەڕوانى )','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:497',(select id from public.theory_sections where slug = 'rules-of-the-road'),44,'There are no speed-limit signs on the road. How is a 30 mph limit generally indicated?','هیچ هێمایەکـى خێـرایـی ڕێگەپێدراو لەسەر ڕێگەکە نییە. چۆن بە شێوەیەکـى گشتـى خێـرایـی ڕێگەپێدراوى ٣٠ میل لە کـاتژمێـرێکدا دیاریدەکرێــــــت؟','By street lighting','لە ڕێگەى ڕووناکەرەوەى سەر شەقام.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:498',(select id from public.theory_sections where slug = 'rules-of-the-road'),45,'What''s the national speed limit for cars and motorcycles on a dual carriageway?','ناشناڵ سپید لیمتد چەندە بۆ ئۆتۆمبێلەکـان و ماتۆڕسکیلەکـان لە سەر دەبڵ کـاریجوەی ؟','70mph','٧٠ میل لە کـاتژمێـرێکدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:499',(select id from public.theory_sections where slug = 'rules-of-the-road'),46,'When must you stop your vehicle?','کەى پێویستە ئۆتۆمبێلەکەت بوەستێنیــــــت؟','If you''re involved in an incident that causes damage or injury','ئەگەر تووشـی ڕووداوێک بیت کە ببێتە هۆى زیانگەیاندن یاخود برینداربوون.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:500',(select id from public.theory_sections where slug = 'rules-of-the-road'),47,'You''re waiting at a level crossing. What should you do if the red warning lights continue to flash after a train has passed by?','لە هێڵـى پەڕینەوەی شەمەندەفەر چاوەڕێ دەکەیت. دەبێــت چـی بکەیت ئەگەر گـڵۆپە ئاگـادارکەرەوە سوورەکـان فلاش بکەن بەبەردەوامـی لە پاش ئەوەى شەمەندەفەرەکە تێپەڕی؟','Continue to wait','. بەردەوام بە لە چاوەڕوانـى کردن.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:501',(select id from public.theory_sections where slug = 'rules-of-the-road'),48,'Where may you overtake on a one-way street?','لە کوێ دەتوانـی تێپەڕاندن ئەنجام بدەیت لەسەر شەقامێکـى یەک ئاراستە؟','On either the right or the left','لەسەر هەر سایدێک ڕاست یان چەپ.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:502',(select id from public.theory_sections where slug = 'rules-of-the-road'),49,'You''re driving on a road that has a cycle lane. What does it mean if the lane is marked by a broken white line?','لەسەر رێگەیەک کە سایدى پاسکیل سوارى لە تەنیشتیدا هەیە شۆفێـرى دەکەیت. مەبەست چییە لەو هێڵە سپیە پچڕ پچڕانەی سەر سایدەکە ؟','You shouldn''t drive in the lane unless it''s unavoidable','نابێــت لەسەر سایدى پاسکیل سوارییەکە شۆفیـرى بکەیت جگە لە ئەو حاڵەتەى نەتوانـى خۆتـى لـێ لابدەیت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:503',(select id from public.theory_sections where slug = 'rules-of-the-road'),50,'What does this sign mean?','ئەم هێمایە ماناى چییە ؟','End of controlled parking zone','کۆتای هاتنی ناوچەى پارککردنى یاخود وەستاندنى کۆنترۆڵکراو','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:504',(select id from public.theory_sections where slug = 'rules-of-the-road'),51,'When may you drive a car in this bus lane?','کەى دەکرێت ئۆتۆمبێلێک لێبخوڕیت لەسەر ئەم سایدى پاسە؟','Outside its hours of operation','لە دەرەوەى کـاتەکـانـى کـارکردنـى پاس.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:505',(select id from public.theory_sections where slug = 'rules-of-the-road'),52,'Who is authorised to signal you to stop?','کـێ دەسەڵاتـى پێدراوە ئاگـادارت بکـاتەوە بوەستیت؟','A police officer','کـارمەندێکـى پۆلیس.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:506',(select id from public.theory_sections where slug = 'rules-of-the-road'),53,'When should you use the right-hand lane of a three-lane dual carriageway?','دەکرێـت کەى سایدى دەستەڕاستـى ڕێگـاى کـاریجوەی سـێ سایدى بەکـاربهێنیت؟','When you''re overtaking or turning right','کـاتێک تێپەڕاندن ئەنجام دەدەیت یان پێچ دەکەیتەوە بۆ دەستە ڕاستدا.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:507',(select id from public.theory_sections where slug = 'rules-of-the-road'),54,'You''re approaching a busy junction. What should you do when, at the last moment, you realise you''re in the wrong lane?','لە ڕێگـایەکـى یەکتـربڕی قەرەباڵەغ نزیک دەبیتەوە. دەبێـت چـی بکەیت کـاتێک لە دوا ساتدا بۆت دەردەکەوێـت کە لەسەر سایدى هەڵەیــــت؟','Continue in that lane','. بەردەوام بە لە شۆفیـرى کردن لەسەر سایدەکە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:508',(select id from public.theory_sections where slug = 'rules-of-the-road'),55,'What should you do if you want to overtake a tractor but aren''t sure that it''s safe?','دەبێـت چـی بکەیت ئەگەر بتەوێــت تراکتۆرێک تێپەڕێنیت بەڵام دڵنیا نەبیت ســەلامەتە؟','Stay behind it if you''re in any doubt','لە دواوە بمێنەرەوە ئەگەر هەر گــومانێـکت هەیە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:509',(select id from public.theory_sections where slug = 'rules-of-the-road'),56,'What should you do when you park at night on a road that has a 40 mph speed limit?','دەبێـت چـی بکەیت کـاتێک ئۆتۆمبێلەکەت لە شەودا و لەسەر ڕێگـایەک پارک بکەیت کە خێـڕایـی ڕێگەپێدراوى ٤٠ میلە لە کاتژمێـرێکدا؟','Leave parking lights switched on','گـڵـۆپەکـانـى پارکیـن بە ئیشپێکراوى بهێڵەرەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:510',(select id from public.theory_sections where slug = 'rules-of-the-road'),57,'When may you stop on an urban clearway?','کەى دەکرێــت لەسەر کـلێروەی( ڕێـگـایەک کە ڕێگـای وەستاندن نادات) بوەستیت ؟','To set down and pick up passengers','بۆ دابەزاندن و هەڵگرتنـى سەرنشینەکـان.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:511',(select id from public.theory_sections where slug = 'rules-of-the-road'),58,'When would you use the right-hand lane of a two-lane dual carriageway?','کەى دەبێـت سایدى دەستە ڕاستـى ڕێگـاى دەبڵ کـاریجوەی بەکـاربهێنیت؟','When you''re turning right or overtaking','کـاتێک بە دەستەڕاستدا پێچ دەکەیتەوە یان تێپەڕاندن ئەنجام دەدەیت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:512',(select id from public.theory_sections where slug = 'rules-of-the-road'),59,'You''re waiting at a level crossing. What must you do if a train passes but the lights keep flashing?','لە هێڵـى پەڕینەوەی شەمەندەفەر چاوەڕێ دەکەیت. دەبێـت چـی بکەیت ئەگەر شەمەندەفەرێک تێپەڕی بەڵام گـڵۆپەکـانـى ئاگـادارکردنەوە بەردەوام بوون لە فلاشکردن؟','Carry on waiting','بەردەوام بە لە چاوەڕوانـى کردن.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:513',(select id from public.theory_sections where slug = 'rules-of-the-road'),60,'You want to park and you see this sign. What should you do on the days and times shown?','دەتەوێ ئۆتۆمبێلەکەت پارک بکەیت و ئەم هێمایە دەبینیت. دەبێـت چـی بکەیت لەو ڕۆژ و بەروارەى کە پیشان دراوە؟','Park in a bay and pay','ئۆتۆمبێلەکەت پارک بکە لە شوێنـى وەستاندن و پارە بدە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:514',(select id from public.theory_sections where slug = 'rules-of-the-road'),61,'Other than direction indicators, how can you give signals to other road users?','جگە لە گـڵـۆپـی ئیشارەتەکـان, چۆن ئاماژە دەدەیت بە بەکـارهێنەرانـى ترى ڕێگـاکە؟','By using brake lights','لە ڕێگەى بەکـارهێنانـى لایتـى برێکەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:515',(select id from public.theory_sections where slug = 'rules-of-the-road'),62,'You''re on a road that''s only wide enough for one vehicle. What should you do if a car is coming towards you?','لەسەر ڕێگـایەک کە تەنها بە ئەندازەی یەک ئۆتۆمبێل پانە. دەبێـت چـی بکەیت کە ئەگەر ئۆتۆمبێلێک بەرەوڕووت هات؟','Pull into a passing place on your left','بڕۆ سەر شوێنێکـى تێپەڕین لە دەستە چەپت.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:516',(select id from public.theory_sections where slug = 'rules-of-the-road'),63,'You''re looking for somewhere to park at night. When may you park on the right-hand side of the road?','بەدواى شوێنێکدا دەگەڕێیت بۆ پارک کردنـی ئۆتۆمبێلکەت لە شەودا. کەى دەکرێـت ئۆتۆمبێلەکەت پارکـى بکەیت لە دەستە ڕاستـى ڕێگـاکە؟','When you''re in a one-way street','کـاتێک لە شەقامـى یەک ئاراستەى.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:517',(select id from public.theory_sections where slug = 'rules-of-the-road'),64,'You''re turning right onto a dual carriageway. What should you do if the central reservation is too narrow to contain your vehicle?','لەسەر یەکێک لە سایدەکـانـى ڕێگـاى دەبڵ کـاریج وەی پێچ دەکەیتەوە بۆ دەستە ڕاست. دەبێت چـی بکەیـت ئەگەر نێوبەندەکە(جەزرە وەسەتیەکە) زۆر تەسک بوو بۆ ئۆتۆمبێلەکەت؟','Wait until the road is clear in both directions','چاوەڕێ بکە تاوەکو ڕێگـاکە چۆڵ دەبێـت لە هەردوو ئاراستەکەوە.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:518',(select id from public.theory_sections where slug = 'rules-of-the-road'),65,'Where will you see these red and white markers?','لە کوێ ئەم نیشانە سوورو سپیـیانە دەبینیت؟','Approaching a concealed level crossing','لە کـاتـی نزیکبوونەوە لە هێڵـی شاراوەى پەڕینەوەی شەمەندەفەر.','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:519',(select id from public.theory_sections where slug = 'rules-of-the-road'),66,'You''re driving on a busy main road. What should you do if you find that you''re driving in the wrong direction?','لەسەر ڕێگـایەکـى سەرەکـى قەرەباڵەغ شۆفێـرى دەکەیـت. دەبێـت چـی بکەیت ئەگەر بۆت دەرکەوت کە لەسەر ئاراستەیەکـى پێچەوانە شۆفێـری دەکەیت ؟','Turn around in a side road','لە ڕێگایەکی لاوەکیدا پێچبکەرەوە','draft','content:uk-theory-questions'),
  ('theory:rules-of-the-road:520',(select id from public.theory_sections where slug = 'rules-of-the-road'),67,'When may you drive over a pavement?','کەى دەکرێــت لەسەر شۆستەیەک شۆفێرى بکەیت ؟','To gain access to a property','بۆ ڕۆیشتنە ناو دامەزراوە یان موڵکێکـی تایبەتەوە.','draft','content:uk-theory-questions')
